-- ============================================================
-- db/68 - Modelo analitico externo e DW passam a viver no banco da plataforma
--
-- MUDANCA DE DECISAO, por diretriz do usuario em 31/08/2026.
--
-- O ADR-010 estabelecia que o modelo analitico externo seria instalado APENAS
-- no laboratorio `itmt_dw_homolog`, e que dele entrariam na plataforma somente
-- ideias adaptadas, uma a uma, com consumidor real (E1-E6, E15, E17-E21). A
-- diretriz nova e outra: o modelo inteiro passa a viver no banco `itmt`, e daqui
-- em diante toda tabela e todo DW nascem aqui. Esta migracao executa isso.
--
-- O que ela traz: 1.299 tabelas em 20 schemas - exatamente o conteudo do
-- laboratorio, validado fisicamente em PostgreSQL 17 + PostGIS 3.5.2 nesta
-- sessao (preflight APROVADO 8/8, 226 colunas de geometria todas em SRID 4674).
--
-- CORRECOES EMBUTIDAS - 5 defeitos que o gerador externo nunca corrigiu na
-- origem, reincidentes desde 28/08 e reaplicados a cada pacote:
--   1. duas FKs declaravam bigint contra uma PK uuid - nao criavam;
--   2. ON CONFLICT(codigo) numa tabela cuja unicidade e (codigo,versao);
--   3. NULL explicito em coluna NOT NULL DEFAULT (NULL nao aciona DEFAULT);
--   4. seed da Fase 2 estourava varchar(40) definido na Fase 1;
--   5. FK apontando coluna nao-unica em vez da surrogate.
-- Sem elas o arquivo nao aplica. Estao marcadas com /*CORRIGIDO*/ no lugar.
--
-- O QUE ESTA MIGRACAO NAO FAZ, e e importante saber:
--   . nao popula nada. As 132 tabelas de fato nascem VAZIAS, como estao no
--     laboratorio. Quem as preencheria e o runtime de ingestao do pacote
--     externo, que nunca foi entregue em sete rodadas;
--   . nao altera uma linha do modelo da casa. As 84 tabelas em `public`
--     (PascalCase, com RLS e auditoria encadeada) seguem intactas e continuam
--     sendo o que a API consulta. Os dois modelos convivem em schemas
--     separados, sem colisao de nomes;
--   . nao concede privilegio algum ao papel da API - ver abaixo.
--
-- PRIVILEGIOS FECHADOS POR PADRAO (decisao do usuario). O modelo externo tem
-- zero GRANT e zero RLS - foi a critica central do ADR-010 - e o `pg_default_acl`
-- desta instalacao daria SELECT automatico a `itmt_app` em tudo, colocando
-- 1.299 tabelas sem policy de tenant ao alcance da API. A migracao REVOGA
-- explicitamente, schema a schema, inclusive o default ACL. Liberar passa a ser
-- ato deliberado, tabela a tabela, quando houver consumidor - a mesma regra que
-- vale para as tabelas da casa.
--
-- REQUISITO: PostGIS. Sao 226 colunas de geometria em SRID 4674 (SIRGAS 2000).
-- A migracao RECUSA-SE a rodar sem a extensao, em vez de degradar para `text`:
-- um stub tornaria a camada geoespacial decorativa e o caminho de volta exigiria
-- ALTER em 226 colunas.
-- ============================================================

BEGIN;

DO $guarda$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'postgis') THEN
    RAISE EXCEPTION
      'db/68 exige PostGIS, ausente nesta instalacao do PostgreSQL. Instale-o '
      '(Stack Builder -> Spatial Extensions) e rode a migracao de novo. O modelo '
      'tem 226 colunas de geometria em SRID 4674; aplica-lo como texto tornaria a '
      'camada geoespacial decorativa.';
  END IF;
END
$guarda$;



-- ============================================================================
-- PLATAFORMA ITMT - BANCO COMPLETO DA FASE 1
-- PostgreSQL 16+ / PostGIS 3+
-- Versao 2.0.0 REFINADA - 2026-08-28
-- Arquitetura: catalogo -> controle -> bruto -> integracao ->
--              nucleo/geoespacial/documental -> dw -> semantico
-- ============================================================================

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE EXTENSION IF NOT EXISTS unaccent;
CREATE EXTENSION IF NOT EXISTS btree_gist;

CREATE SCHEMA IF NOT EXISTS catalogo;
CREATE SCHEMA IF NOT EXISTS controle;
CREATE SCHEMA IF NOT EXISTS bruto;
CREATE SCHEMA IF NOT EXISTS referencia;
CREATE SCHEMA IF NOT EXISTS nucleo;
CREATE SCHEMA IF NOT EXISTS integracao;
CREATE SCHEMA IF NOT EXISTS geoespacial;
CREATE SCHEMA IF NOT EXISTS documental;
CREATE SCHEMA IF NOT EXISTS dw;
CREATE SCHEMA IF NOT EXISTS semantico;
CREATE SCHEMA IF NOT EXISTS seguranca;

CREATE OR REPLACE FUNCTION controle.definir_atualizado_em()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  NEW.atualizado_em := now();
  RETURN NEW;
END $$;

CREATE TABLE IF NOT EXISTS catalogo.licenca_dado (
licenca_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(80) NOT NULL UNIQUE,
nome varchar(200) NOT NULL,
url_licenca text,
permite_redistribuicao boolean,
permite_uso_comercial boolean,
exige_atribuicao boolean,
observacoes text,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE catalogo.licenca_dado IS 'Licencas aplicaveis a fontes, conjuntos e recursos.';

CREATE TABLE IF NOT EXISTS catalogo.fonte_dado (
fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(80) NOT NULL UNIQUE,
nome varchar(250) NOT NULL,
instituicao varchar(250) NOT NULL,
url_oficial text,
url_api text,
tipo_acesso varchar(80),
autenticacao varchar(120),
prioridade varchar(5) NOT NULL DEFAULT 'P1' CHECK (prioridade IN ('P0','P1','P2','P3')),
dificuldade varchar(20) CHECK (dificuldade IN ('Baixa','Media','Alta')),
classificacao_confiabilidade varchar(120) /*CORRIGIDO: seed da F2 estourava 40*/,
periodicidade_padrao varchar(120),
agente_xingu varchar(160),
ativo boolean NOT NULL DEFAULT true,
fase smallint NOT NULL DEFAULT 1,
observacoes text,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE catalogo.fonte_dado IS 'Cadastro mestre das fontes de dados da Fase 1.';

CREATE TABLE IF NOT EXISTS catalogo.conjunto_dado (
conjunto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
codigo_origem varchar(200),
nome varchar(300) NOT NULL,
descricao text,
dominio varchar(120),
granularidade varchar(200),
periodicidade varchar(120),
url_catalogo text,
licenca_id bigint REFERENCES catalogo.licenca_dado(licenca_id),
possui_dados_pessoais boolean NOT NULL DEFAULT false,
nivel_acesso varchar(30) NOT NULL DEFAULT 'publico'
  CHECK (nivel_acesso IN ('publico','restrito','convenio','interno')),
ativo boolean NOT NULL DEFAULT true,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(fonte_id,codigo_origem)
);

COMMENT ON TABLE catalogo.conjunto_dado IS 'Conjuntos de dados publicados por cada fonte.';

CREATE TABLE IF NOT EXISTS catalogo.recurso_fonte (
recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
conjunto_id bigint NOT NULL REFERENCES catalogo.conjunto_dado(conjunto_id),
codigo_origem varchar(300),
nome varchar(300) NOT NULL,
url_recurso text,
formato varchar(80),
tipo_recurso varchar(40) CHECK (tipo_recurso IN
 ('api','arquivo','gis','documento','raster','catalogo','painel','outro')),
metodo_http varchar(10),
cabecalhos_padrao jsonb NOT NULL DEFAULT '{}'::jsonb,
parametros_padrao jsonb NOT NULL DEFAULT '{}'::jsonb,
paginacao jsonb NOT NULL DEFAULT '{}'::jsonb,
encoding varchar(40),
separador varchar(10),
compressao varchar(40),
ativo boolean NOT NULL DEFAULT true,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(conjunto_id,codigo_origem)
);

COMMENT ON TABLE catalogo.recurso_fonte IS 'Endpoint, arquivo ou servico concreto a ser coletado.';

CREATE TABLE IF NOT EXISTS catalogo.campo_fonte (
campo_fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
nome_origem varchar(300) NOT NULL,
nome_exibicao varchar(300),
descricao text,
tipo_origem varchar(100),
tipo_destino varchar(100),
obrigatorio boolean NOT NULL DEFAULT false,
chave_natural boolean NOT NULL DEFAULT false,
sensivel boolean NOT NULL DEFAULT false,
ordem integer,
dominio_valores jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(recurso_id,nome_origem)
);

COMMENT ON TABLE catalogo.campo_fonte IS 'Dicionario de campos da origem.';

CREATE TABLE IF NOT EXISTS catalogo.versao_recurso (
versao_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
versao_origem varchar(200),
publicado_em timestamptz,
valido_desde timestamptz,
valido_ate timestamptz,
schema_hash char(64),
conteudo_hash char(64),
tamanho_bytes bigint,
numero_registros bigint,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(recurso_id,versao_origem,conteudo_hash)
);

COMMENT ON TABLE catalogo.versao_recurso IS 'Versionamento logico e fisico dos recursos.';

CREATE TABLE IF NOT EXISTS catalogo.parametro_coleta (
parametro_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
nome varchar(160) NOT NULL,
tipo varchar(50),
valor_padrao text,
segredo_referencia varchar(300),
obrigatorio boolean NOT NULL DEFAULT false,
descricao text,
UNIQUE(recurso_id,nome)
);

COMMENT ON TABLE catalogo.parametro_coleta IS 'Parametros de coleta; segredos ficam apenas em Vault/KMS.';

CREATE TABLE IF NOT EXISTS catalogo.mapeamento_campo (
mapeamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
campo_fonte_id bigint NOT NULL REFERENCES catalogo.campo_fonte(campo_fonte_id),
tabela_destino varchar(300) NOT NULL,
coluna_destino varchar(300) NOT NULL,
expressao_transformacao text,
regra_nulidade text,
regra_dominio text,
ativo boolean NOT NULL DEFAULT true,
criado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(campo_fonte_id,tabela_destino,coluna_destino)
);

COMMENT ON TABLE catalogo.mapeamento_campo IS 'Mapeamento declarativo de origem para destino.';

CREATE TABLE IF NOT EXISTS catalogo.indicador (
indicador_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(160) NOT NULL UNIQUE,
nome varchar(300) NOT NULL,
descricao text,
dominio varchar(120) NOT NULL,
unidade_padrao varchar(80),
direcao_melhor varchar(20)
 CHECK (direcao_melhor IN ('maior','menor','neutro','contextual')),
formula text,
periodicidade varchar(100),
granularidade_minima varchar(100),
publicado boolean NOT NULL DEFAULT true,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE catalogo.indicador IS 'Catalogo semantico de indicadores.';

CREATE TABLE IF NOT EXISTS catalogo.indicador_fonte (
indicador_fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
conjunto_id bigint NOT NULL REFERENCES catalogo.conjunto_dado(conjunto_id),
codigo_indicador_origem varchar(200),
prioridade smallint NOT NULL DEFAULT 1,
metodo_calculo text,
observacoes text,
UNIQUE(indicador_id,conjunto_id,codigo_indicador_origem)
);

COMMENT ON TABLE catalogo.indicador_fonte IS 'Relaciona indicadores ITMT aos conjuntos de origem.';

CREATE TABLE IF NOT EXISTS catalogo.metodologia_indicador (
metodologia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
versao varchar(80) NOT NULL,
descricao text NOT NULL,
formula text,
criterios_inclusao text,
criterios_exclusao text,
fonte_metodologica text,
valido_desde date,
valido_ate date,
criado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(indicador_id,versao)
);

COMMENT ON TABLE catalogo.metodologia_indicador IS 'Metodologia versionada e reproduzivel.';

CREATE TABLE IF NOT EXISTS catalogo.acordo_integracao (
acordo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
tipo varchar(40) CHECK (tipo IN
 ('dados_abertos','termo_uso','convenio','acordo_cooperacao','contrato','outro')),
numero varchar(150),
titulo varchar(300),
inicio_vigencia date,
fim_vigencia date,
restricoes text,
responsavel_itmt varchar(200),
status varchar(30) DEFAULT 'ativo',
documento_uri text,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE catalogo.acordo_integracao IS 'Convenios, termos de uso e acordos.';

CREATE TABLE IF NOT EXISTS controle.lote_ingestao (
lote_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
conjunto_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
referencia varchar(200),
tipo_carga varchar(20) NOT NULL
 CHECK (tipo_carga IN ('completa','incremental','delta','reprocessamento','manual')),
iniciado_em timestamptz NOT NULL DEFAULT now(),
finalizado_em timestamptz,
status varchar(20) NOT NULL DEFAULT 'iniciado'
 CHECK (status IN ('iniciado','sucesso','parcial','falha','cancelado')),
executado_por varchar(200),
parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
observacoes text
);

COMMENT ON TABLE controle.lote_ingestao IS 'Unidade logica de ingestao.';

CREATE TABLE IF NOT EXISTS controle.execucao_carga (
execucao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
etapa varchar(40) NOT NULL CHECK (etapa IN
 ('coleta','validacao','bruto','transformacao','nucleo','dw','semantico','publicacao')),
iniciado_em timestamptz NOT NULL DEFAULT now(),
finalizado_em timestamptz,
status varchar(20) NOT NULL DEFAULT 'iniciado'
 CHECK (status IN ('iniciado','sucesso','parcial','falha','cancelado')),
registros_lidos bigint NOT NULL DEFAULT 0,
registros_inseridos bigint NOT NULL DEFAULT 0,
registros_atualizados bigint NOT NULL DEFAULT 0,
registros_rejeitados bigint NOT NULL DEFAULT 0,
bytes_processados bigint NOT NULL DEFAULT 0,
duracao_ms bigint,
parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
metricas jsonb NOT NULL DEFAULT '{}'::jsonb,
mensagem text
);

COMMENT ON TABLE controle.execucao_carga IS 'Execucao tecnica de uma etapa ETL/ELT.';

CREATE TABLE IF NOT EXISTS controle.arquivo_coletado (
arquivo_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
execucao_id uuid REFERENCES controle.execucao_carga(execucao_id),
recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
nome_arquivo varchar(500) NOT NULL,
uri_origem text,
uri_armazenamento text NOT NULL,
mime_type varchar(150),
compactacao varchar(40),
tamanho_bytes bigint,
sha256 char(64) NOT NULL,
etag varchar(300),
ultima_modificacao_origem timestamptz,
coletado_em timestamptz NOT NULL DEFAULT now(),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(recurso_id,sha256)
);

COMMENT ON TABLE controle.arquivo_coletado IS 'Inventario de arquivos preservados no object storage.';

CREATE TABLE IF NOT EXISTS controle.resposta_api_coletada (
resposta_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
execucao_id uuid REFERENCES controle.execucao_carga(execucao_id),
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
url_requisicao text NOT NULL,
parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
cabecalhos_resposta jsonb NOT NULL DEFAULT '{}'::jsonb,
status_http integer,
pagina varchar(100),
cursor_origem text,
sha256 char(64),
coletado_em timestamptz NOT NULL DEFAULT now(),
payload jsonb
);

COMMENT ON TABLE controle.resposta_api_coletada IS 'Snapshot auditavel das respostas API.';

CREATE TABLE IF NOT EXISTS controle.checkpoint_coleta (
checkpoint_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
chave varchar(200) NOT NULL,
valor text,
atualizado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(recurso_id,chave)
);

COMMENT ON TABLE controle.checkpoint_coleta IS 'Checkpoint/cursor de cargas incrementais.';

CREATE TABLE IF NOT EXISTS controle.registro_rejeitado (
rejeicao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
execucao_id uuid NOT NULL REFERENCES controle.execucao_carga(execucao_id),
identificador_origem varchar(500),
numero_linha bigint,
codigo_erro varchar(120),
motivo text NOT NULL,
payload jsonb,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.registro_rejeitado IS 'Registros rejeitados.';

CREATE TABLE IF NOT EXISTS controle.erro_carga (
erro_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
execucao_id uuid REFERENCES controle.execucao_carga(execucao_id),
severidade varchar(20) NOT NULL DEFAULT 'erro'
 CHECK (severidade IN ('info','aviso','erro','critico')),
codigo varchar(120),
mensagem text NOT NULL,
detalhe text,
contexto jsonb,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.erro_carga IS 'Erros tecnicos e funcionais.';

CREATE TABLE IF NOT EXISTS controle.regra_qualidade (
regra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(160) NOT NULL UNIQUE,
nome varchar(300) NOT NULL,
descricao text,
escopo_tabela varchar(300),
expressao_sql text,
severidade varchar(20) NOT NULL DEFAULT 'erro'
 CHECK (severidade IN ('info','aviso','erro','critico')),
limite_tolerancia numeric(12,6),
ativo boolean NOT NULL DEFAULT true,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.regra_qualidade IS 'Regras de qualidade automatizadas.';

CREATE TABLE IF NOT EXISTS controle.resultado_qualidade (
resultado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
execucao_id uuid NOT NULL REFERENCES controle.execucao_carga(execucao_id),
regra_id bigint NOT NULL REFERENCES controle.regra_qualidade(regra_id),
aprovado boolean NOT NULL,
total_avaliado bigint,
total_invalido bigint,
percentual_invalido numeric(12,6),
amostra jsonb,
executado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.resultado_qualidade IS 'Resultados das regras de qualidade.';

CREATE TABLE IF NOT EXISTS controle.estatistica_carga (
estatistica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
execucao_id uuid NOT NULL REFERENCES controle.execucao_carga(execucao_id),
tabela_destino varchar(300),
coluna varchar(300),
metrica varchar(100) NOT NULL,
valor_numerico numeric(30,10),
valor_texto text,
calculado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.estatistica_carga IS 'Perfil estatistico das cargas.';

CREATE TABLE IF NOT EXISTS controle.linhagem_dado (
linhagem_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
execucao_id uuid REFERENCES controle.execucao_carga(execucao_id),
origem_tipo varchar(30) NOT NULL,
origem_identificador text NOT NULL,
destino_tabela varchar(300) NOT NULL,
destino_chave text NOT NULL,
transformacao text,
criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.linhagem_dado IS 'Linhagem de dados entre origem e destino.';

CREATE TABLE IF NOT EXISTS controle.auditoria_alteracao (
auditoria_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tabela varchar(300) NOT NULL,
chave_registro text,
operacao char(1) NOT NULL CHECK (operacao IN ('I','U','D')),
usuario_execucao varchar(200),
dados_anteriores jsonb,
dados_novos jsonb,
ocorrido_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.auditoria_alteracao IS 'Auditoria das alteracoes canônicas.';

CREATE TABLE IF NOT EXISTS controle.fila_reprocessamento (
fila_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
referencia varchar(300),
motivo text NOT NULL,
prioridade smallint NOT NULL DEFAULT 5,
status varchar(20) NOT NULL DEFAULT 'pendente'
 CHECK(status IN ('pendente','processando','concluido','falha','cancelado')),
tentativas integer NOT NULL DEFAULT 0,
proxima_tentativa timestamptz,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.fila_reprocessamento IS 'Fila idempotente de reprocessamento.';

CREATE TABLE IF NOT EXISTS bruto.objeto_coletado (
objeto_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
versao_recurso_id bigint REFERENCES catalogo.versao_recurso(versao_recurso_id),
tipo_objeto varchar(30) NOT NULL CHECK (tipo_objeto IN
 ('json','linha_tabular','arquivo','documento','feicao','raster','binario','outro')),
identificador_origem text,
periodo_referencia varchar(100),
coletado_em timestamptz NOT NULL DEFAULT now(),
sha256 char(64),
payload_json jsonb,
payload_texto text,
uri_payload text,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE bruto.objeto_coletado IS 'Envelope bruto universal e imutavel.';

CREATE TABLE IF NOT EXISTS bruto.registro_tabular (
registro_bruto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
objeto_id uuid NOT NULL REFERENCES bruto.objeto_coletado(objeto_id) ON DELETE CASCADE,
numero_linha bigint,
dados jsonb NOT NULL,
hash_registro char(64),
UNIQUE(objeto_id,numero_linha)
);

COMMENT ON TABLE bruto.registro_tabular IS 'Linha de CSV/TXT/XLS convertida para JSONB sem perda.';

CREATE TABLE IF NOT EXISTS bruto.registro_json (
registro_json_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
objeto_id uuid NOT NULL REFERENCES bruto.objeto_coletado(objeto_id) ON DELETE CASCADE,
caminho_json text,
indice bigint,
dados jsonb NOT NULL,
hash_registro char(64)
);

COMMENT ON TABLE bruto.registro_json IS 'Item extraido de JSON/GeoJSON.';

CREATE TABLE IF NOT EXISTS bruto.feicao_origem (
feicao_bruta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
objeto_id uuid NOT NULL REFERENCES bruto.objeto_coletado(objeto_id) ON DELETE CASCADE,
identificador_origem text,
propriedades jsonb NOT NULL DEFAULT '{}'::jsonb,
geometria geometry(Geometry,4674),
srid_origem integer,
geometria_original text
);

COMMENT ON TABLE bruto.feicao_origem IS 'Feicao GIS bruta.';

CREATE TABLE IF NOT EXISTS bruto.arquivo_geoespacial (
arquivo_geo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
objeto_id uuid NOT NULL REFERENCES bruto.objeto_coletado(objeto_id) ON DELETE CASCADE,
tipo varchar(30) CHECK(tipo IN
 ('raster','nuvem_pontos','ortomosaico','mdt','mds','vetor','outro')),
uri text NOT NULL,
formato varchar(80),
srid integer,
resolucao_x numeric(20,8),
resolucao_y numeric(20,8),
bbox geometry(Polygon,4674),
tamanho_bytes bigint,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE bruto.arquivo_geoespacial IS 'Metadados de arquivos geoespaciais grandes.';

CREATE TABLE IF NOT EXISTS referencia.tipo_territorio (
tipo_territorio_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(50) NOT NULL UNIQUE,
nome varchar(120) NOT NULL,
nivel smallint NOT NULL,
descricao text
);

COMMENT ON TABLE referencia.tipo_territorio IS 'Tipos de recorte territorial.';

CREATE TABLE IF NOT EXISTS referencia.territorio (
territorio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo_territorio_id smallint NOT NULL REFERENCES referencia.tipo_territorio(tipo_territorio_id),
codigo_oficial varchar(80),
nome varchar(250) NOT NULL,
sigla varchar(30),
valido_desde date,
valido_ate date,
ativo boolean NOT NULL DEFAULT true,
centroide geometry(Point,4674),
geometria geometry(MultiPolygon,4674),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(tipo_territorio_id,codigo_oficial)
);

COMMENT ON TABLE referencia.territorio IS 'Dimensao territorial operacional extensivel.';

CREATE TABLE IF NOT EXISTS referencia.territorio_hierarquia (
territorio_pai_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
territorio_filho_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
tipo_relacao varchar(60) NOT NULL DEFAULT 'contem',
valido_desde date,
valido_ate date,
PRIMARY KEY(territorio_pai_id,territorio_filho_id,tipo_relacao)
);

COMMENT ON TABLE referencia.territorio_hierarquia IS 'Hierarquia temporal dos territorios.';

CREATE TABLE IF NOT EXISTS referencia.pais (
pais_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_iso2 char(2) UNIQUE,
codigo_iso3 char(3) UNIQUE,
nome varchar(150) NOT NULL
);

CREATE TABLE IF NOT EXISTS referencia.unidade_federativa (
uf_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_ibge char(2) NOT NULL UNIQUE,
sigla char(2) NOT NULL UNIQUE,
nome varchar(100) NOT NULL,
regiao varchar(30)
);

CREATE TABLE IF NOT EXISTS referencia.regiao_intermediaria (
regiao_intermediaria_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_ibge varchar(8) NOT NULL UNIQUE,
nome varchar(180) NOT NULL,
uf_id smallint NOT NULL REFERENCES referencia.unidade_federativa(uf_id)
);

CREATE TABLE IF NOT EXISTS referencia.regiao_imediata (
regiao_imediata_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_ibge varchar(10) NOT NULL UNIQUE,
nome varchar(180) NOT NULL,
regiao_intermediaria_id bigint REFERENCES referencia.regiao_intermediaria(regiao_intermediaria_id)
);

CREATE TABLE IF NOT EXISTS referencia.municipio (
municipio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_ibge char(7) NOT NULL UNIQUE,
nome varchar(180) NOT NULL,
uf_id smallint NOT NULL REFERENCES referencia.unidade_federativa(uf_id),
regiao_imediata_id bigint REFERENCES referencia.regiao_imediata(regiao_imediata_id),
regiao_intermediaria_id bigint REFERENCES referencia.regiao_intermediaria(regiao_intermediaria_id),
codigo_tse varchar(10),
codigo_siafi varchar(10),
capital boolean NOT NULL DEFAULT false,
area_km2 numeric(20,6),
latitude numeric(10,7),
longitude numeric(10,7),
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE referencia.municipio IS 'Cadastro mestre municipal com codigo IBGE.';

CREATE TABLE IF NOT EXISTS referencia.distrito (
distrito_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
codigo_ibge varchar(12) UNIQUE,
municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
nome varchar(180) NOT NULL,
sede boolean,
ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS referencia.consorcio_publico (
consorcio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
territorio_id bigint UNIQUE REFERENCES referencia.territorio(territorio_id),
cnpj varchar(14) UNIQUE,
nome varchar(300) NOT NULL,
sigla varchar(80),
tipo varchar(80),
area_atuacao varchar(120),
url_oficial text,
ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE referencia.consorcio_publico IS 'Consorcios de saude, infraestrutura, desenvolvimento etc.';

CREATE TABLE IF NOT EXISTS referencia.consorcio_municipio (
consorcio_id bigint NOT NULL REFERENCES referencia.consorcio_publico(consorcio_id),
municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
inicio_vinculo date NOT NULL DEFAULT '1900-01-01',
fim_vinculo date,
PRIMARY KEY(consorcio_id,municipio_id,inicio_vinculo)
);

CREATE TABLE IF NOT EXISTS referencia.periodo_referencia (
periodo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo varchar(30) NOT NULL CHECK(tipo IN
 ('data','semana','quinzena','mes','bimestre','trimestre','quadrimestre','semestre','ano','ano_letivo','ano_fiscal','safra','periodo_movel','censo','edicao','outro')),
codigo varchar(40) NOT NULL,
data_inicio date,
data_fim date,
ano smallint,
mes smallint CHECK(mes IS NULL OR mes BETWEEN 1 AND 12),
descricao varchar(200),
UNIQUE(tipo,codigo)
);

CREATE TABLE IF NOT EXISTS referencia.unidade_medida (
unidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(40) NOT NULL UNIQUE,
nome varchar(120) NOT NULL,
simbolo varchar(30),
grandeza varchar(80),
fator_si numeric(30,15)
);

CREATE TABLE IF NOT EXISTS referencia.moeda (
moeda_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_iso char(3) NOT NULL UNIQUE,
nome varchar(100) NOT NULL,
simbolo varchar(10),
casas_decimais smallint NOT NULL DEFAULT 2
);

CREATE TABLE IF NOT EXISTS referencia.cnae (
cnae_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(10) NOT NULL UNIQUE,
descricao varchar(500) NOT NULL,
nivel varchar(30),
codigo_pai varchar(10),
versao varchar(30),
ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS referencia.natureza_juridica (
natureza_juridica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(10) NOT NULL UNIQUE,
descricao varchar(300) NOT NULL
);

CREATE TABLE IF NOT EXISTS referencia.cbo (
cbo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(10) NOT NULL UNIQUE,
titulo varchar(300) NOT NULL,
descricao text
);

CREATE TABLE IF NOT EXISTS referencia.especialidade_saude (
especialidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_origem varchar(40),
nome varchar(250) NOT NULL,
grupo varchar(150),
ativo boolean NOT NULL DEFAULT true,
UNIQUE(codigo_origem,nome)
);

CREATE TABLE IF NOT EXISTS referencia.etapa_ensino (
etapa_ensino_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_inep varchar(30) UNIQUE,
nome varchar(180) NOT NULL,
nivel varchar(80)
);

CREATE TABLE IF NOT EXISTS referencia.tipo_ato_oficial (
tipo_ato_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(50) NOT NULL UNIQUE,
nome varchar(160) NOT NULL
);

CREATE TABLE IF NOT EXISTS referencia.tipo_obra (
tipo_obra_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(60) NOT NULL UNIQUE,
nome varchar(180) NOT NULL,
dominio varchar(100)
);

CREATE TABLE IF NOT EXISTS referencia.situacao_obra (
situacao_obra_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(60) NOT NULL UNIQUE,
nome varchar(150) NOT NULL,
ordem smallint
);

CREATE TABLE IF NOT EXISTS referencia.classe_uso_solo (
classe_uso_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(50) NOT NULL,
nome varchar(180) NOT NULL,
fonte_classificacao varchar(100) NOT NULL,
versao varchar(50),
classe_pai_id smallint REFERENCES referencia.classe_uso_solo(classe_uso_id),
UNIQUE(fonte_classificacao,versao,codigo)
);

CREATE TABLE IF NOT EXISTS nucleo.instituicao (
instituicao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo varchar(40) NOT NULL CHECK(tipo IN
 ('orgao_publico','empresa','osc','instituicao_ensino','estabelecimento_saude','consorcio','outro')),
nome varchar(400) NOT NULL,
nome_fantasia varchar(400),
sigla varchar(100),
cnpj varchar(14) UNIQUE,
esfera varchar(30),
poder varchar(30),
natureza varchar(120),
url_oficial text,
ativo boolean NOT NULL DEFAULT true,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE nucleo.instituicao IS 'Entidade institucional canonica.';

CREATE TABLE IF NOT EXISTS nucleo.endereco (
endereco_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
cep char(8),
logradouro varchar(300),
numero varchar(80),
complemento varchar(250),
bairro varchar(200),
distrito varchar(180),
latitude numeric(10,7),
longitude numeric(10,7),
geometria geometry(Point,4674),
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS nucleo.instituicao_endereco (
instituicao_id bigint NOT NULL REFERENCES nucleo.instituicao(instituicao_id),
endereco_id bigint NOT NULL REFERENCES nucleo.endereco(endereco_id),
tipo varchar(40) NOT NULL DEFAULT 'principal',
inicio_vigencia date,
fim_vigencia date,
PRIMARY KEY(instituicao_id,endereco_id,tipo)
);

CREATE TABLE IF NOT EXISTS nucleo.orgao_publico (
orgao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
instituicao_id bigint NOT NULL UNIQUE REFERENCES nucleo.instituicao(instituicao_id),
codigo_siorg varchar(30),
codigo_ug varchar(30),
codigo_origem varchar(100),
ente_territorio_id bigint REFERENCES referencia.territorio(territorio_id),
orgao_superior_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
tipo_orgao varchar(120),
esfera varchar(30),
poder varchar(30),
ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS nucleo.empresa (
empresa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
instituicao_id bigint UNIQUE REFERENCES nucleo.instituicao(instituicao_id),
cnpj_basico varchar(8) UNIQUE,
razao_social varchar(500),
natureza_juridica_id bigint REFERENCES referencia.natureza_juridica(natureza_juridica_id),
capital_social numeric(20,2),
porte varchar(50),
ente_federativo_responsavel varchar(200),
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS nucleo.estabelecimento_empresa (
estabelecimento_empresa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
empresa_id bigint NOT NULL REFERENCES nucleo.empresa(empresa_id),
cnpj varchar(14) NOT NULL UNIQUE,
identificador_matriz_filial smallint,
nome_fantasia varchar(500),
situacao_cadastral varchar(80),
data_situacao date,
inicio_atividade date,
cnae_principal_id bigint REFERENCES referencia.cnae(cnae_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
endereco_id bigint REFERENCES nucleo.endereco(endereco_id),
ativo boolean,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS nucleo.estabelecimento_cnae (
estabelecimento_empresa_id bigint NOT NULL REFERENCES nucleo.estabelecimento_empresa(estabelecimento_empresa_id),
cnae_id bigint NOT NULL REFERENCES referencia.cnae(cnae_id),
principal boolean NOT NULL DEFAULT false,
PRIMARY KEY(estabelecimento_empresa_id,cnae_id)
);

CREATE TABLE IF NOT EXISTS nucleo.estabelecimento_saude (
estabelecimento_saude_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
codigo_cnes varchar(20) NOT NULL UNIQUE,
nome varchar(400) NOT NULL,
tipo_unidade varchar(200),
natureza_juridica varchar(180),
esfera_administrativa varchar(100),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
endereco_id bigint REFERENCES nucleo.endereco(endereco_id),
atende_sus boolean,
ativo boolean NOT NULL DEFAULT true,
data_atualizacao date,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS nucleo.estabelecimento_saude_especialidade (
estabelecimento_saude_id bigint NOT NULL REFERENCES nucleo.estabelecimento_saude(estabelecimento_saude_id),
especialidade_id bigint NOT NULL REFERENCES referencia.especialidade_saude(especialidade_id),
atende_sus boolean,
quantidade integer,
periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
PRIMARY KEY(estabelecimento_saude_id,especialidade_id,periodo_id)
);

CREATE TABLE IF NOT EXISTS nucleo.leito_saude (
leito_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
estabelecimento_saude_id bigint NOT NULL REFERENCES nucleo.estabelecimento_saude(estabelecimento_saude_id),
codigo_tipo_leito varchar(30),
tipo_leito varchar(200) NOT NULL,
especialidade varchar(200),
quantidade_existente integer,
quantidade_sus integer,
uti boolean,
periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS nucleo.instituicao_ensino (
instituicao_ensino_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
codigo_origem varchar(40),
sistema_origem varchar(30) NOT NULL,
nome varchar(400) NOT NULL,
categoria varchar(180),
dependencia_administrativa varchar(100),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
endereco_id bigint REFERENCES nucleo.endereco(endereco_id),
rural boolean,
indigena boolean,
ativa boolean NOT NULL DEFAULT true,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(sistema_origem,codigo_origem)
);

CREATE TABLE IF NOT EXISTS nucleo.curso_superior (
curso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
instituicao_ensino_id bigint NOT NULL REFERENCES nucleo.instituicao_ensino(instituicao_ensino_id),
codigo_inep varchar(40),
nome varchar(400) NOT NULL,
grau varchar(100),
modalidade varchar(80),
area_cine varchar(200),
ativo boolean,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(instituicao_ensino_id,codigo_inep)
);

CREATE TABLE IF NOT EXISTS nucleo.projeto_infraestrutura (
projeto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_canonico uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
nome varchar(500) NOT NULL,
descricao text,
tipo_obra_id smallint REFERENCES referencia.tipo_obra(tipo_obra_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
orgao_responsavel_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
valor_previsto numeric(20,2),
data_inicio_prevista date,
data_fim_prevista date,
situacao_obra_id smallint REFERENCES referencia.situacao_obra(situacao_obra_id),
geometria geometry(Geometry,4674),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE nucleo.projeto_infraestrutura IS 'Projeto/obra canonico consolidado.';

CREATE TABLE IF NOT EXISTS nucleo.contrato_publico (
contrato_publico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_canonico uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
numero varchar(160),
orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
fornecedor_instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
objeto text,
valor_inicial numeric(20,2),
valor_atual numeric(20,2),
data_assinatura date,
vigencia_inicio date,
vigencia_fim date,
situacao varchar(100),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS nucleo.transferencia_publica (
transferencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_canonico uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
numero_instrumento varchar(160),
concedente_orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
beneficiario_instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
modalidade varchar(120),
objeto text,
valor_global numeric(20,2),
valor_repassado numeric(20,2),
data_inicio date,
data_fim date,
situacao varchar(100),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_tabela (
tabela_sidra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo_tabela varchar(30) NOT NULL UNIQUE,
nome varchar(500) NOT NULL,
pesquisa varchar(300),
periodicidade varchar(80),
assunto varchar(200),
ultima_atualizacao timestamptz,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_variavel (
variavel_sidra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tabela_sidra_id bigint NOT NULL REFERENCES integracao.ibge_sidra_tabela(tabela_sidra_id),
codigo_variavel varchar(50) NOT NULL,
nome varchar(500) NOT NULL,
unidade varchar(100),
UNIQUE(tabela_sidra_id,codigo_variavel)
);

CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_classificacao (
classificacao_sidra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tabela_sidra_id bigint NOT NULL REFERENCES integracao.ibge_sidra_tabela(tabela_sidra_id),
codigo_classificacao varchar(50) NOT NULL,
nome varchar(300) NOT NULL,
UNIQUE(tabela_sidra_id,codigo_classificacao)
);

CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_categoria (
categoria_sidra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
classificacao_sidra_id bigint NOT NULL REFERENCES integracao.ibge_sidra_classificacao(classificacao_sidra_id),
codigo_categoria varchar(80) NOT NULL,
nome varchar(400) NOT NULL,
categoria_pai_id bigint REFERENCES integracao.ibge_sidra_categoria(categoria_sidra_id),
UNIQUE(classificacao_sidra_id,codigo_categoria)
);

CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_observacao (
observacao_sidra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tabela_sidra_id bigint NOT NULL REFERENCES integracao.ibge_sidra_tabela(tabela_sidra_id),
variavel_sidra_id bigint REFERENCES integracao.ibge_sidra_variavel(variavel_sidra_id),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
valor_numerico numeric(30,10),
valor_texto text,
unidade varchar(100),
classificacoes jsonb NOT NULL DEFAULT '{}'::jsonb,
identificador_origem varchar(500),
lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE integracao.ibge_sidra_observacao IS 'Observacao generica SIDRA, apta a qualquer tabela/classificacao.';

CREATE TABLE IF NOT EXISTS integracao.ibge_localidade (
ibge_localidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo_localidade varchar(60) NOT NULL,
codigo_ibge varchar(20) NOT NULL,
nome varchar(300) NOT NULL,
codigo_pai varchar(20),
sigla_uf char(2),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
dados_origem jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(tipo_localidade,codigo_ibge)
);

CREATE TABLE IF NOT EXISTS integracao.ibge_malha_versao (
malha_versao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo_malha varchar(80) NOT NULL,
ano smallint NOT NULL,
escala varchar(50),
srid integer,
uri_arquivo text,
sha256 char(64),
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(tipo_malha,ano,sha256)
);

CREATE TABLE IF NOT EXISTS integracao.portal_dados_conjunto (
portal_conjunto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
identificador_origem varchar(300) NOT NULL,
titulo varchar(500) NOT NULL,
organizacao varchar(300),
descricao text,
tags text[],
licenca varchar(180),
criado_origem timestamptz,
modificado_origem timestamptz,
url_catalogo text,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,identificador_origem)
);

CREATE TABLE IF NOT EXISTS integracao.portal_dados_recurso (
portal_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
portal_conjunto_id bigint NOT NULL REFERENCES integracao.portal_dados_conjunto(portal_conjunto_id),
identificador_origem varchar(300),
nome varchar(500),
formato varchar(80),
url text,
tamanho_bytes bigint,
hash_origem varchar(200),
modificado_origem timestamptz,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(portal_conjunto_id,identificador_origem)
);

CREATE TABLE IF NOT EXISTS integracao.mt_despesa (
mt_despesa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
exercicio smallint NOT NULL,data_movimento date,orgao_origem varchar(250),
