estabelecimento_empresa_id bigint REFERENCES nucleo.estabelecimento_empresa(estabelecimento_empresa_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
cnae_id bigint REFERENCES referencia.cnae(cnae_id),
