tamanho_estabelecimento varchar(80),
quantidade_vinculos_ativos bigint,
massa_salarial numeric(24,4),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
objeto_bruto_id uuid REFERENCES bruto.objeto_coletado(objeto_id)
);

COMMENT ON TABLE integracao.rais_estabelecimento IS 'Estabelecimentos e estoque de vínculos da RAIS em escopo público.';

CREATE TABLE IF NOT EXISTS integracao.rais_trabalho_agregado (
rais_trabalho_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
