cbo_id bigint REFERENCES referencia.cbo(cbo_id),
sexo varchar(30),
faixa_etaria varchar(50),
grau_instrucao varchar(80),
tipo_vinculo varchar(80),
faixa_remuneracao varchar(80),
quantidade_vinculos bigint NOT NULL,
remuneracao_media numeric(18,2),
horas_contratuais_media numeric(12,4),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
objeto_bruto_id uuid REFERENCES bruto.objeto_coletado(objeto_id)
);

COMMENT ON TABLE integracao.rais_trabalho_agregado IS 'Indicadores agregados de vínculos da RAIS.';

CREATE TABLE IF NOT EXISTS integracao.incra_imovel_certificado (
