geometria geometry(MultiPolygon,4674),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
objeto_bruto_id uuid REFERENCES bruto.objeto_coletado(objeto_id)
);

COMMENT ON TABLE integracao.incra_assentamento IS 'Projetos de assentamento rural do INCRA.';

CREATE TABLE IF NOT EXISTS integracao.incra_territorio_quilombola (
