CREATE TABLE IF NOT EXISTS integracao.inpe_foco_queimada (
inpe_foco_queimada_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_foco varchar(160),
data_hora timestamptz NOT NULL,
satelite varchar(80),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
bioma varchar(80),
frp numeric(18,6),
risco_fogo numeric(12,6),
precipitacao numeric(12,4),
geometria geometry(Point,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
