);

COMMENT ON TABLE integracao.inpe_foco_queimada IS 'Focos de calor/queimadas do INPE.';

CREATE TABLE IF NOT EXISTS integracao.mapbiomas_classe (
mapbiomas_classe_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
colecao varchar(80) NOT NULL,
