UNIQUE(colecao,codigo_classe)
);

COMMENT ON TABLE integracao.mapbiomas_classe IS 'Legenda de classes de cobertura/uso para cada coleção MapBiomas.';

CREATE TABLE IF NOT EXISTS integracao.mapbiomas_estatistica_municipal (
mapbiomas_estatistica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
