produto varchar(120) NOT NULL,
ano smallint NOT NULL,
municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
mapbiomas_classe_id bigint REFERENCES integracao.mapbiomas_classe(mapbiomas_classe_id),
