area_ha numeric(24,8) NOT NULL,
percentual_territorio numeric(12,8),
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
objeto_bruto_id uuid REFERENCES bruto.objeto_coletado(objeto_id)
);

COMMENT ON TABLE integracao.mapbiomas_estatistica_municipal IS 'Estatísticas municipais por produto, ano, classe e coleção MapBiomas.';

CREATE TABLE IF NOT EXISTS integracao.mapbiomas_raster (
mapbiomas_raster_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
colecao varchar(80) NOT NULL,
produto varchar(120) NOT NULL,
ano smallint,
uri_objeto text NOT NULL,
formato varchar(50) NOT NULL DEFAULT 'GeoTIFF',
crs varchar(80),
resolucao_metros numeric(12,4),
largura_pixels integer,
altura_pixels integer,
bbox geometry(Polygon,4674),
checksum_sha256 char(64),
tamanho_bytes bigint,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(colecao,produto,ano,uri_objeto)
);

COMMENT ON TABLE integracao.mapbiomas_raster IS 'Catálogo dos rasters MapBiomas armazenados fora do PostgreSQL.';

CREATE TABLE IF NOT EXISTS geoespacial.camada (
camada_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
codigo varchar(120) NOT NULL UNIQUE,
nome varchar(300) NOT NULL,
descricao text,
dominio varchar(120),
tipo_geometria varchar(40),
srid integer NOT NULL DEFAULT 4674,
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
conjunto_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
publica boolean NOT NULL DEFAULT true,
estilo jsonb NOT NULL DEFAULT '{}'::jsonb,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE geoespacial.camada IS 'Catálogo de camadas geoespaciais consolidadas.';

CREATE TABLE IF NOT EXISTS geoespacial.versao_camada (
versao_camada_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
camada_id bigint NOT NULL REFERENCES geoespacial.camada(camada_id) ON DELETE CASCADE,
versao varchar(100) NOT NULL,
data_referencia date,
data_publicacao date,
data_ingestao timestamptz NOT NULL DEFAULT now(),
quantidade_feicoes bigint,
bbox geometry(Polygon,4674),
checksum varchar(128),
versao_recurso_id bigint REFERENCES catalogo.versao_recurso(versao_recurso_id),
ativo boolean NOT NULL DEFAULT true,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(camada_id,versao)
);

COMMENT ON TABLE geoespacial.versao_camada IS 'Versões de cada camada geográfica.';

CREATE TABLE IF NOT EXISTS geoespacial.feicao (
feicao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
camada_id bigint NOT NULL REFERENCES geoespacial.camada(camada_id),
versao_camada_id bigint REFERENCES geoespacial.versao_camada(versao_camada_id),
id_origem varchar(180),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
nome varchar(500),
categoria varchar(180),
geometria geometry(Geometry,4674) NOT NULL,
atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
valido_desde date,
valido_ate date,
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
objeto_bruto_id uuid REFERENCES bruto.objeto_coletado(objeto_id),
UNIQUE(versao_camada_id,id_origem)
);

COMMENT ON TABLE geoespacial.feicao IS 'Repositório vetorial consolidado para feições que não exigem tabela temática dedicada.';

CREATE TABLE IF NOT EXISTS geoespacial.municipio_geometria (
municipio_geometria_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
versao_camada_id bigint REFERENCES geoespacial.versao_camada(versao_camada_id),
ano_referencia smallint,
geometria geometry(MultiPolygon,4674) NOT NULL,
centroide geometry(Point,4674),
area_calculada_km2 numeric(24,8),
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
ativo boolean NOT NULL DEFAULT true,
UNIQUE(municipio_id,versao_camada_id)
);

COMMENT ON TABLE geoespacial.municipio_geometria IS 'Histórico de geometrias municipais.';

CREATE TABLE IF NOT EXISTS geoespacial.sistema_viario (
via_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
nome varchar(500),
tipo_via varchar(120),
jurisdicao varchar(80),
pavimentacao varchar(100),
situacao varchar(120),
extensao_km numeric(20,8),
geometria geometry(MultiLineString,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.sistema_viario IS 'Sistema viário consolidado, incluindo rodovias e vias/estradas quando disponíveis.';

CREATE TABLE IF NOT EXISTS geoespacial.hidrografia (
hidrografia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
nome varchar(500),
tipo varchar(120),
ordem_curso varchar(50),
bacia varchar(250),
sub_bacia varchar(250),
geometria geometry(Geometry,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.hidrografia IS 'Hidrografia consolidada.';

CREATE TABLE IF NOT EXISTS geoespacial.unidade_conservacao (
unidade_conservacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
nome varchar(500) NOT NULL,
categoria varchar(180),
grupo varchar(120),
esfera varchar(80),
ato_criacao varchar(300),
data_criacao date,
area_ha numeric(24,8),
geometria geometry(MultiPolygon,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.unidade_conservacao IS 'Unidades de conservação harmonizadas.';

CREATE TABLE IF NOT EXISTS geoespacial.territorio_tradicional (
territorio_tradicional_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
tipo varchar(80) NOT NULL CHECK(tipo IN ('indigena','quilombola','outro')),
nome varchar(500) NOT NULL,
fase_situacao varchar(180),
municipio_principal_id bigint REFERENCES referencia.municipio(municipio_id),
area_ha numeric(24,8),
geometria geometry(MultiPolygon,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.territorio_tradicional IS 'Terras indígenas, quilombolas e outros territórios tradicionais.';

CREATE TABLE IF NOT EXISTS geoespacial.imovel_fundiario (
imovel_fundiario_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
codigo_imovel varchar(180),
nome varchar(500),
tipo_cadastro varchar(80),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
situacao varchar(120),
area_ha numeric(24,8),
geometria geometry(MultiPolygon,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.imovel_fundiario IS 'Visão espacial consolidada de imóveis e parcelas fundiárias.';

CREATE TABLE IF NOT EXISTS geoespacial.assentamento_rural (
assentamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
id_origem varchar(180),
nome varchar(500) NOT NULL,
codigo varchar(120),
municipio_principal_id bigint REFERENCES referencia.municipio(municipio_id),
area_ha numeric(24,8),
capacidade_familias integer,
familias_assentadas integer,
situacao varchar(120),
geometria geometry(MultiPolygon,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE geoespacial.assentamento_rural IS 'Assentamentos rurais consolidados.';

CREATE TABLE IF NOT EXISTS geoespacial.empreendimento_estruturante (
empreendimento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
projeto_infraestrutura_id bigint REFERENCES nucleo.projeto_infraestrutura(projeto_id),
id_origem varchar(180),
nome varchar(600) NOT NULL,
tipo varchar(180) NOT NULL,
subtipo varchar(180),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
situacao varchar(120),
capacidade_valor numeric(24,8),
capacidade_unidade varchar(80),
geometria geometry(Geometry,4674) NOT NULL,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE geoespacial.empreendimento_estruturante IS 'Empreendimentos estruturantes públicos ou privados relevantes ao território.';

CREATE TABLE IF NOT EXISTS geoespacial.raster_catalogo (
raster_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
camada_id bigint REFERENCES geoespacial.camada(camada_id),
versao_camada_id bigint REFERENCES geoespacial.versao_camada(versao_camada_id),
nome varchar(500) NOT NULL,
produto varchar(180),
ano smallint,
data_referencia date,
uri_objeto text NOT NULL,
formato varchar(50) NOT NULL,
crs varchar(80),
resolucao_x numeric(20,8),
resolucao_y numeric(20,8),
largura_pixels bigint,
altura_pixels bigint,
bandas smallint,
tipo_pixel varchar(80),
nodata varchar(80),
bbox geometry(Polygon,4674),
checksum_sha256 char(64),
tamanho_bytes bigint,
licenca_id bigint REFERENCES catalogo.licenca_dado(licenca_id),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(uri_objeto,checksum_sha256)
);

COMMENT ON TABLE geoespacial.raster_catalogo IS 'Catálogo de rasters armazenados em object storage.';

CREATE TABLE IF NOT EXISTS geoespacial.nuvem_pontos_catalogo (
nuvem_pontos_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
municipio_id bigint REFERENCES referencia.municipio(municipio_id),
nome varchar(500) NOT NULL,
tipo varchar(80) DEFAULT 'LAS/LAZ',
data_levantamento date,
uri_objeto text NOT NULL,
crs varchar(80),
densidade_pontos_m2 numeric(20,8),
quantidade_pontos bigint,
bbox geometry(Polygon,4674),
checksum_sha256 char(64),
tamanho_bytes bigint,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(uri_objeto,checksum_sha256)
);

COMMENT ON TABLE geoespacial.nuvem_pontos_catalogo IS 'Catálogo preparado para nuvens de pontos e levantamentos VANT.';

CREATE TABLE IF NOT EXISTS documental.documento (
documento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
id_origem varchar(180),
tipo_documento varchar(120),
titulo varchar(1000),
descricao text,
numero varchar(160),
ano integer,
data_documento date,
data_publicacao timestamptz,
orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
url_origem text,
arquivo_id uuid REFERENCES controle.arquivo_coletado(arquivo_id) /*CORRIGIDO: era bigint contra uuid*/,
mime_type varchar(150),
checksum_sha256 char(64),
idioma varchar(20) DEFAULT 'pt-BR',
texto_integral text,
ocr_utilizado boolean NOT NULL DEFAULT false,
confianca_ocr numeric(8,5),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
criado_em timestamptz NOT NULL DEFAULT now(),
UNIQUE(fonte_id,id_origem)
);

COMMENT ON TABLE documental.documento IS 'Documentos oficiais e institucionais coletados de fontes da Fase 1.';

CREATE TABLE IF NOT EXISTS documental.pagina_documento (
pagina_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
documento_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
numero_pagina integer NOT NULL,
texto text,
confianca_ocr numeric(8,5),
imagem_uri text,
bbox_texto jsonb,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
UNIQUE(documento_id,numero_pagina)
);

COMMENT ON TABLE documental.pagina_documento IS 'Texto e metadados por página para documentos PDF/OCR.';

CREATE TABLE IF NOT EXISTS documental.publicacao_oficial (
publicacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
documento_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
tipo_ato_id bigint REFERENCES referencia.tipo_ato_oficial(tipo_ato_id),
orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
numero_ato varchar(160),
ano_ato integer,
data_ato date,
data_publicacao date,
ementa text,
texto text,
pagina_inicial integer,
pagina_final integer,
processo varchar(180),
valor numeric(24,4),
cnpj_cpf_mencionado varchar(32),
vetor_busca tsvector GENERATED ALWAYS AS (
 to_tsvector('portuguese',coalesce(ementa,'') || ' ' || coalesce(texto,''))
) STORED,
dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE documental.publicacao_oficial IS 'Atos individualizados dentro de diários oficiais.';

CREATE TABLE IF NOT EXISTS documental.anexo_documento (
anexo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
documento_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
nome varchar(500),
tipo varchar(120),
url_origem text,
uri_objeto text,
mime_type varchar(150),
checksum_sha256 char(64),
tamanho_bytes bigint,
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE documental.anexo_documento IS 'Anexos associados a documentos.';

CREATE TABLE IF NOT EXISTS documental.entidade_extraida (
entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
tipo varchar(80) NOT NULL,
valor_original text NOT NULL,
valor_normalizado text,
identificador_normalizado varchar(180),
empresa_id bigint REFERENCES nucleo.empresa(empresa_id),
orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
instituicao_id bigint REFERENCES nucleo.instituicao(instituicao_id),
territorio_id bigint REFERENCES referencia.territorio(territorio_id),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE documental.entidade_extraida IS 'Entidades identificadas por NLP/OCR nos documentos.';

CREATE TABLE IF NOT EXISTS documental.mencao_entidade (
mencao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
documento_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
pagina_id bigint REFERENCES documental.pagina_documento(pagina_id) ON DELETE CASCADE,
publicacao_id bigint REFERENCES documental.publicacao_oficial(publicacao_id) ON DELETE CASCADE,
entidade_id bigint NOT NULL REFERENCES documental.entidade_extraida(entidade_id),
inicio_caractere integer,
fim_caractere integer,
trecho text,
confianca numeric(8,5),
modelo_extracao varchar(120),
metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE documental.mencao_entidade IS 'Menções de entidades em documentos para rastreabilidade da extração.';

CREATE TABLE IF NOT EXISTS documental.relacionamento_documento (
relacionamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
documento_origem_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
documento_destino_id bigint NOT NULL REFERENCES documental.documento(documento_id) ON DELETE CASCADE,
tipo_relacao varchar(120) NOT NULL,
confianca numeric(8,5),
observacao text,
UNIQUE(documento_origem_id,documento_destino_id,tipo_relacao),
CHECK(documento_origem_id <> documento_destino_id)
);

COMMENT ON TABLE documental.relacionamento_documento IS 'Relações entre editais, contratos, aditivos, atas, leis e outros documentos.';

CREATE TABLE IF NOT EXISTS dw.dim_tempo (
