valido_desde date NOT NULL DEFAULT DATE '1900-01-01',
valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
versao_atual boolean NOT NULL DEFAULT true,
hash_atributos char(64),
UNIQUE(territorio_id,valido_desde)
);

COMMENT ON TABLE dw.dim_territorio IS 'Dimensão território SCD Tipo 2.';

CREATE TABLE IF NOT EXISTS dw.dim_fonte (
