CREATE OR REPLACE FUNCTION dw.preencher_dim_tempo(p_inicio date, p_fim date)
RETURNS void
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO dw.dim_tempo (
    tempo_id,data,ano,semestre,quadrimestre,trimestre,bimestre,mes,nome_mes,dia,
    dia_semana,nome_dia_semana,semana_ano,fim_mes,fim_trimestre,fim_ano
  )
  SELECT
    to_char(d,'YYYYMMDD')::integer,
    d::date,
    extract(year from d)::smallint,
    CASE WHEN extract(month from d) <= 6 THEN 1 ELSE 2 END::smallint,
    ceil(extract(month from d)/4.0)::smallint,
    extract(quarter from d)::smallint,
    ceil(extract(month from d)/2.0)::smallint,
    extract(month from d)::smallint,
    trim(to_char(d,'TMMonth')),
    extract(day from d)::smallint,
    extract(isodow from d)::smallint,
    trim(to_char(d,'TMDay')),
    extract(week from d)::smallint,
    (d = (date_trunc('month',d) + interval '1 month - 1 day')::date),
    (extract(month from d) IN (3,6,9,12) AND d = (date_trunc('month',d)+interval '1 month - 1 day')::date),
    (extract(month from d)=12 AND extract(day from d)=31)
  FROM generate_series(p_inicio::timestamp,p_fim::timestamp,interval '1 day') d
  ON CONFLICT (tempo_id) DO NOTHING;
END $$;

CREATE UNIQUE INDEX IF NOT EXISTS uq_fato_indicador_territorial
ON dw.fato_indicador_territorial(
  indicador_sk, territorio_sk,
  coalesce(tempo_id,-1), coalesce(periodo_id,-1),
  fonte_sk, revisao
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_conceito_fonte
ON semantico.conceito_fonte(
  conceito_id, fonte_id,
  coalesce(conjunto_id,0),
  coalesce(campo_origem,'')
);

CREATE OR REPLACE VIEW catalogo.v_inventario_fontes AS
SELECT
  f.fonte_id, f.codigo, f.nome, f.instituicao, f.prioridade, f.dificuldade,
  f.classificacao_confiabilidade, f.fase, f.ativo,
  count(DISTINCT c.conjunto_id) AS conjuntos,
  count(DISTINCT r.recurso_id) AS recursos,
  max(v.publicado_em) AS ultima_publicacao_catalogada,
  max(v.criado_em) AS ultima_versao_catalogada
FROM catalogo.fonte_dado f
LEFT JOIN catalogo.conjunto_dado c ON c.fonte_id=f.fonte_id
LEFT JOIN catalogo.recurso_fonte r ON r.conjunto_id=c.conjunto_id
LEFT JOIN catalogo.versao_recurso v ON v.recurso_id=r.recurso_id
GROUP BY f.fonte_id;

CREATE OR REPLACE VIEW controle.v_status_ultima_carga AS
SELECT DISTINCT ON (f.fonte_id)
  f.fonte_id, f.codigo AS fonte_codigo, f.nome AS fonte_nome,
  e.execucao_id, e.etapa, e.status, e.iniciado_em, e.finalizado_em,
  e.registros_lidos, e.registros_inseridos, e.registros_atualizados,
  e.registros_rejeitados, e.bytes_processados, e.mensagem
FROM controle.execucao_carga e
JOIN catalogo.recurso_fonte r ON r.recurso_id=e.recurso_id
JOIN catalogo.conjunto_dado c ON c.conjunto_id=r.conjunto_id
JOIN catalogo.fonte_dado f ON f.fonte_id=c.fonte_id
ORDER BY f.fonte_id, e.iniciado_em DESC;

CREATE OR REPLACE VIEW semantico.v_indicador_territorial AS
SELECT
  f.fato_indicador_id,
  di.codigo AS indicador_codigo, di.nome AS indicador_nome, di.dominio,
  dt.codigo_oficial AS territorio_codigo, dt.nome AS territorio_nome, dt.tipo_territorio,
  t.data, pr.codigo AS periodo_codigo,
  df.codigo AS fonte_codigo, df.nome AS fonte_nome,
  f.valor_numero, f.valor_texto, f.unidade, f.margem_erro,
  f.nivel_confianca, f.qualidade_score, f.revisao, f.publicado
FROM dw.fato_indicador_territorial f
JOIN dw.dim_indicador di ON di.indicador_sk=f.indicador_sk
JOIN dw.dim_territorio dt ON dt.territorio_sk=f.territorio_sk
JOIN dw.dim_fonte df ON df.fonte_sk=f.fonte_sk
LEFT JOIN dw.dim_tempo t ON t.tempo_id=f.tempo_id
LEFT JOIN referencia.periodo_referencia pr ON pr.periodo_id=f.periodo_id
WHERE f.publicado=true;

CREATE OR REPLACE VIEW semantico.v_perfil_municipio AS
SELECT
  m.municipio_id, m.codigo_ibge, m.nome AS municipio, uf.sigla AS uf,
  ri.nome AS regiao_imediata, rint.nome AS regiao_intermediaria,
  m.area_km2, m.latitude, m.longitude,
  count(DISTINCT es.estabelecimento_saude_id) AS estabelecimentos_saude,
  count(DISTINCT ie.instituicao_ensino_id) AS instituicoes_ensino,
  count(DISTINCT ee.estabelecimento_empresa_id) AS estabelecimentos_empresariais,
  count(DISTINCT pi.projeto_id) AS projetos_infraestrutura
FROM referencia.municipio m
JOIN referencia.unidade_federativa uf ON uf.uf_id=m.uf_id
LEFT JOIN referencia.regiao_imediata ri ON ri.regiao_imediata_id=m.regiao_imediata_id
LEFT JOIN referencia.regiao_intermediaria rint ON rint.regiao_intermediaria_id=m.regiao_intermediaria_id
LEFT JOIN nucleo.estabelecimento_saude es ON es.municipio_id=m.municipio_id AND es.ativo=true
LEFT JOIN nucleo.instituicao_ensino ie ON ie.municipio_id=m.municipio_id AND ie.ativa=true
LEFT JOIN nucleo.estabelecimento_empresa ee ON ee.municipio_id=m.municipio_id AND coalesce(ee.ativo,true)=true
LEFT JOIN nucleo.projeto_infraestrutura pi ON pi.municipio_id=m.municipio_id
GROUP BY m.municipio_id, m.codigo_ibge, m.nome, uf.sigla, ri.nome, rint.nome,
         m.area_km2, m.latitude, m.longitude;

