-- ============================================================================
-- REFINAMENTOS V2.0 - COBERTURA ANALÍTICA E RESILIÊNCIA A PERGUNTAS COMPLEXAS
-- ============================================================================

-- --------------------------------------------------------------------------
-- Funções auxiliares de identificadores e qualidade
-- --------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION referencia.normalizar_cnpj(valor text)
RETURNS varchar LANGUAGE sql IMMUTABLE AS $$
  SELECT NULLIF(regexp_replace(upper(coalesce(valor,'')), '[^0-9A-Z]', '', 'g'),'')::varchar;
$$;

CREATE OR REPLACE FUNCTION referencia.cnpj_formato_valido(valor text)
RETURNS boolean LANGUAGE sql IMMUTABLE AS $$
  SELECT valor IS NULL OR referencia.normalizar_cnpj(valor) ~ '^[0-9A-Z]{12}[0-9]{2}$';
$$;

-- --------------------------------------------------------------------------
-- CATÁLOGO: cobertura, limitações, composição e semântica de agregação
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS catalogo.cobertura_conjunto (
  cobertura_conjunto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conjunto_id bigint NOT NULL REFERENCES catalogo.conjunto_dado(conjunto_id) ON DELETE CASCADE,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  data_inicio date,
  data_fim date,
  granularidade_territorial varchar(120),
  granularidade_temporal varchar(120),
  percentual_cobertura numeric(7,4) CHECK(percentual_cobertura IS NULL OR percentual_cobertura BETWEEN 0 AND 100),
  status varchar(30) NOT NULL DEFAULT 'declarada' CHECK(status IN ('declarada','medida','parcial','indisponivel','desconhecida')),
  observacoes text,
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.cobertura_conjunto IS 'Cobertura temporal e territorial declarada/medida de cada conjunto.';

CREATE TABLE IF NOT EXISTS catalogo.limitacao_conjunto (
  limitacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conjunto_id bigint NOT NULL REFERENCES catalogo.conjunto_dado(conjunto_id) ON DELETE CASCADE,
  tipo varchar(60) NOT NULL CHECK(tipo IN ('metodologica','cobertura','atraso','privacidade','qualidade','licenca','comparabilidade','granularidade','outro')),
  severidade varchar(20) NOT NULL DEFAULT 'informativa' CHECK(severidade IN ('informativa','baixa','media','alta','critica')),
  descricao text NOT NULL,
  valido_desde date,
  valido_ate date,
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.limitacao_conjunto IS 'Limitações que a Xingú deve considerar antes de responder.';

CREATE TABLE IF NOT EXISTS catalogo.regra_agregacao_indicador (
  regra_agregacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id) ON DELETE CASCADE,
  eixo varchar(30) NOT NULL CHECK(eixo IN ('tempo','territorio','dimensao','fonte')),
  operacao varchar(40) NOT NULL CHECK(operacao IN ('soma','media','media_ponderada','ultimo','primeiro','maximo','minimo','recalcular_razao','nao_agregar','personalizada')),
  indicador_peso_id bigint REFERENCES catalogo.indicador(indicador_id),
  expressao text,
  observacoes text,
  UNIQUE(indicador_id,eixo)
);
COMMENT ON TABLE catalogo.regra_agregacao_indicador IS 'Evita somas/médias estatisticamente inválidas em tempo, território e dimensões.';

CREATE TABLE IF NOT EXISTS catalogo.indicador_componente (
  indicador_componente_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id) ON DELETE CASCADE,
  componente_indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  papel varchar(30) NOT NULL CHECK(papel IN ('numerador','denominador','multiplicador','peso','ajuste','componente')),
  fator numeric(30,10) NOT NULL DEFAULT 1,
  filtros jsonb NOT NULL DEFAULT '{}'::jsonb,
  obrigatorio boolean NOT NULL DEFAULT true,
  ordem smallint,
  observacoes text
);
COMMENT ON TABLE catalogo.indicador_componente IS 'Componentes reproduzíveis de taxas, razões, índices e indicadores derivados.';

CREATE TABLE IF NOT EXISTS catalogo.indicador_dimensao (
  indicador_dimensao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id) ON DELETE CASCADE,
  codigo_dimensao varchar(120) NOT NULL,
  nome_dimensao varchar(200) NOT NULL,
  obrigatoria boolean NOT NULL DEFAULT false,
  filtravel boolean NOT NULL DEFAULT true,
  agrupavel boolean NOT NULL DEFAULT true,
  dominio_padronizado_codigo varchar(120),
  valor_padrao varchar(200),
  observacoes text,
  UNIQUE(indicador_id,codigo_dimensao)
);
COMMENT ON TABLE catalogo.indicador_dimensao IS 'Dimensões analíticas permitidas/necessárias por indicador.';

CREATE TABLE IF NOT EXISTS catalogo.regra_disponibilidade_indicador (
  regra_disponibilidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id) ON DELETE CASCADE,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  atraso_esperado_dias integer,
  dado_inicial_provisorio boolean NOT NULL DEFAULT false,
  fechamento_esperado_dias integer,
  revisavel boolean NOT NULL DEFAULT true,
  politica_revisao text,
  UNIQUE(indicador_id,fonte_id)
);

-- --------------------------------------------------------------------------
-- CONTROLE: frescor, cobertura, contrato de schema e reconciliação mult fonte
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS controle.cobertura_carga (
  cobertura_carga_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_id uuid NOT NULL REFERENCES controle.execucao_carga(execucao_id) ON DELETE CASCADE,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  data_inicio date,
  data_fim date,
  registros_esperados bigint,
  registros_lidos bigint,
  registros_carregados bigint,
  percentual_completude numeric(7,4) CHECK(percentual_completude IS NULL OR percentual_completude BETWEEN 0 AND 100),
  lacunas jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS controle.monitoramento_frescor (
  monitoramento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  publicado_mais_recente_em timestamptz,
  coletado_mais_recente_em timestamptz,
  atraso_horas numeric(16,4),
  sla_horas numeric(16,4),
  status varchar(30) NOT NULL CHECK(status IN ('em_dia','atrasado','indisponivel','desconhecido')),
  verificado_em timestamptz NOT NULL DEFAULT now(),
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS controle.teste_contrato_dado (
  teste_contrato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  codigo varchar(160) NOT NULL,
  nome varchar(300) NOT NULL,
  tipo varchar(40) NOT NULL CHECK(tipo IN ('schema','campo','tipo','dominio','chave','volume','semantica','geometria','arquivo')),
  severidade varchar(20) NOT NULL DEFAULT 'alta' CHECK(severidade IN ('baixa','media','alta','critica')),
  regra jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(recurso_id,codigo)
);

CREATE TABLE IF NOT EXISTS controle.resultado_teste_contrato (
  resultado_teste_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_id uuid NOT NULL REFERENCES controle.execucao_carga(execucao_id) ON DELETE CASCADE,
  teste_contrato_id bigint NOT NULL REFERENCES controle.teste_contrato_dado(teste_contrato_id),
  status varchar(20) NOT NULL CHECK(status IN ('aprovado','reprovado','alerta','nao_executado')),
  valor_observado jsonb,
  mensagem text,
  executado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS controle.reconciliacao_fonte (
  reconciliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  fonte_a_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  fonte_b_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  valor_a numeric(30,10),
  valor_b numeric(30,10),
  diferenca_absoluta numeric(30,10),
  diferenca_percentual numeric(20,8),
  tolerancia_percentual numeric(20,8),
  status varchar(30) NOT NULL CHECK(status IN ('coerente','divergente','inconclusivo','esperado')),
  motivo_esperado text,
  analisado_em timestamptz NOT NULL DEFAULT now(),
  CHECK(fonte_a_id <> fonte_b_id)
);

CREATE TABLE IF NOT EXISTS controle.discrepancia_dado (
  discrepancia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  reconciliacao_id bigint REFERENCES controle.reconciliacao_fonte(reconciliacao_id) ON DELETE SET NULL,
  severidade varchar(20) NOT NULL CHECK(severidade IN ('baixa','media','alta','critica')),
  descricao text NOT NULL,
  causa_identificada text,
  acao_corretiva text,
  status varchar(30) NOT NULL DEFAULT 'aberta' CHECK(status IN ('aberta','em_analise','justificada','corrigida','aceita')),
  aberto_em timestamptz NOT NULL DEFAULT now(),
  resolvido_em timestamptz
);

CREATE TABLE IF NOT EXISTS controle.incidente_dado (
  incidente_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
  severidade varchar(20) NOT NULL CHECK(severidade IN ('baixa','media','alta','critica')),
  tipo varchar(60) NOT NULL,
  titulo varchar(300) NOT NULL,
  descricao text,
  impacto text,
  iniciado_em timestamptz NOT NULL,
  encerrado_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'aberto' CHECK(status IN ('aberto','monitorando','mitigado','encerrado'))
);

CREATE TABLE IF NOT EXISTS controle.historico_revisao (
  revisao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  tabela_origem varchar(300) NOT NULL,
  chave_origem varchar(600) NOT NULL,
  versao_anterior_id bigint REFERENCES catalogo.versao_recurso(versao_recurso_id),
  versao_nova_id bigint REFERENCES catalogo.versao_recurso(versao_recurso_id),
  hash_anterior char(64),
  hash_novo char(64),
  campos_alterados jsonb NOT NULL DEFAULT '{}'::jsonb,
  motivo text,
  detectado_em timestamptz NOT NULL DEFAULT now()
);

-- --------------------------------------------------------------------------
-- REFERÊNCIA: domínios, classificações hierárquicas, idade, status e papéis
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS referencia.dominio_padronizado (
  dominio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(120) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  descricao text,
  permite_hierarquia boolean NOT NULL DEFAULT false,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS referencia.valor_dominio (
  valor_dominio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  dominio_id bigint NOT NULL REFERENCES referencia.dominio_padronizado(dominio_id) ON DELETE CASCADE,
  codigo varchar(120) NOT NULL,
  nome varchar(300) NOT NULL,
  codigo_pai varchar(120),
  ordem integer,
  valido_desde date,
  valido_ate date,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(dominio_id,codigo)
);

CREATE TABLE IF NOT EXISTS referencia.mapeamento_valor_origem (
  mapeamento_valor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id),
  dominio_id bigint NOT NULL REFERENCES referencia.dominio_padronizado(dominio_id),
  valor_origem varchar(500) NOT NULL,
  valor_dominio_id bigint NOT NULL REFERENCES referencia.valor_dominio(valor_dominio_id),
  valido_desde date,
  valido_ate date,
  UNIQUE(fonte_id,recurso_id,dominio_id,valor_origem,valido_desde)
);

CREATE TABLE IF NOT EXISTS referencia.sistema_classificacao (
  sistema_classificacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(120) NOT NULL,
  nome varchar(300) NOT NULL,
  versao varchar(100) NOT NULL DEFAULT 'ATUAL',
  instituicao_responsavel varchar(300),
  hierarquico boolean NOT NULL DEFAULT true,
  valido_desde date,
  valido_ate date,
  url_referencia text,
  UNIQUE(codigo,versao)
);

CREATE TABLE IF NOT EXISTS referencia.item_classificacao (
  item_classificacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sistema_classificacao_id bigint NOT NULL REFERENCES referencia.sistema_classificacao(sistema_classificacao_id) ON DELETE CASCADE,
  codigo varchar(120) NOT NULL,
  nome varchar(600) NOT NULL,
  nivel varchar(80),
  codigo_pai varchar(120),
  ordem integer,
  valido_desde date NOT NULL DEFAULT DATE '1900-01-01',
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  ativo boolean NOT NULL DEFAULT true,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(sistema_classificacao_id,codigo,valido_desde)
);

CREATE TABLE IF NOT EXISTS referencia.item_classificacao_hierarquia (
  item_pai_id bigint NOT NULL REFERENCES referencia.item_classificacao(item_classificacao_id) ON DELETE CASCADE,
  item_filho_id bigint NOT NULL REFERENCES referencia.item_classificacao(item_classificacao_id) ON DELETE CASCADE,
  distancia smallint NOT NULL DEFAULT 1 CHECK(distancia > 0),
  valido_desde date,
  valido_ate date,
  PRIMARY KEY(item_pai_id,item_filho_id,distancia)
);

CREATE TABLE IF NOT EXISTS referencia.mapeamento_classificacao (
  mapeamento_classificacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  item_origem_id bigint NOT NULL REFERENCES referencia.item_classificacao(item_classificacao_id),
  item_destino_id bigint NOT NULL REFERENCES referencia.item_classificacao(item_classificacao_id),
  tipo varchar(40) NOT NULL CHECK(tipo IN ('equivalente','aproximado','mais_amplo','mais_especifico','substituido_por')),
  peso numeric(12,8),
  observacoes text,
  UNIQUE(item_origem_id,item_destino_id,tipo)
);

CREATE TABLE IF NOT EXISTS referencia.faixa_etaria (
  faixa_etaria_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  idade_min_dias integer,
  idade_max_dias integer,
  grupo varchar(120),
  ordem integer,
  eh_fetal boolean NOT NULL DEFAULT false,
  eh_neonatal_precoce boolean NOT NULL DEFAULT false,
  eh_neonatal_tardia boolean NOT NULL DEFAULT false,
  eh_pos_neonatal boolean NOT NULL DEFAULT false,
  eh_menor_1_ano boolean NOT NULL DEFAULT false,
  eh_menor_5_anos boolean NOT NULL DEFAULT false,
  CHECK(idade_min_dias IS NULL OR idade_min_dias >= 0),
  CHECK(idade_max_dias IS NULL OR idade_min_dias IS NULL OR idade_max_dias >= idade_min_dias)
);

CREATE TABLE IF NOT EXISTS referencia.causa_evitavel (
  causa_evitavel_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(400) NOT NULL,
  classificacao_referencia varchar(200),
  versao varchar(80),
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.classificacao_causa_evitavel (
  causa_evitavel_id bigint NOT NULL REFERENCES referencia.causa_evitavel(causa_evitavel_id) ON DELETE CASCADE,
  item_classificacao_id bigint NOT NULL REFERENCES referencia.item_classificacao(item_classificacao_id) ON DELETE CASCADE,
  valido_desde date,
  valido_ate date,
  PRIMARY KEY(causa_evitavel_id,item_classificacao_id)
);

CREATE TABLE IF NOT EXISTS referencia.tipo_papel_territorio (
  papel_territorio_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.tipo_papel_entidade (
  papel_entidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.status_dado (
  status_dado_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  ordem smallint,
