  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.tipo_agregacao (
  tipo_agregacao_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  descricao text
);

-- --------------------------------------------------------------------------
-- NÚCLEO: resolução de entidades entre fontes e mudanças de nome/identificador
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS nucleo.entidade (
  entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tipo varchar(80) NOT NULL,
  nome_exibicao varchar(500) NOT NULL,
  territorio_principal_id bigint REFERENCES referencia.territorio(territorio_id),
  valido_desde date,
  valido_ate date,
  ativo boolean NOT NULL DEFAULT true,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS nucleo.identificador_entidade (
  identificador_entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entidade_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id) ON DELETE CASCADE,
  sistema varchar(120) NOT NULL,
  tipo varchar(80) NOT NULL,
  valor varchar(300) NOT NULL,
  valor_normalizado varchar(300) NOT NULL,
  principal boolean NOT NULL DEFAULT false,
  valido_desde date NOT NULL DEFAULT DATE '1900-01-01',
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  UNIQUE(sistema,tipo,valor_normalizado,valido_desde)
);

CREATE TABLE IF NOT EXISTS nucleo.nome_entidade (
  nome_entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entidade_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id) ON DELETE CASCADE,
  nome varchar(600) NOT NULL,
  tipo varchar(50) NOT NULL DEFAULT 'alias',
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  valido_desde date,
  valido_ate date,
  principal boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS nucleo.correspondencia_entidade (
  correspondencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  tabela_origem varchar(300) NOT NULL,
  chave_origem varchar(600) NOT NULL,
  entidade_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id),
  metodo varchar(80) NOT NULL CHECK(metodo IN ('identificador_exato','regra','fuzzy','geoespacial','manual','ia')),
  pontuacao numeric(8,6) CHECK(pontuacao IS NULL OR pontuacao BETWEEN 0 AND 1),
  status varchar(30) NOT NULL DEFAULT 'aceita' CHECK(status IN ('proposta','aceita','rejeitada','revisar')),
  revisado_por varchar(200),
  revisado_em timestamptz,
  UNIQUE(fonte_id,tabela_origem,chave_origem,entidade_id)
);

CREATE TABLE IF NOT EXISTS nucleo.relacao_entidade (
  relacao_entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entidade_origem_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id),
  entidade_destino_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id),
  tipo_relacao varchar(120) NOT NULL,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  valido_desde date NOT NULL DEFAULT DATE '1900-01-01',
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK(entidade_origem_id <> entidade_destino_id),
  UNIQUE(entidade_origem_id,entidade_destino_id,tipo_relacao,valido_desde)
);

ALTER TABLE nucleo.instituicao ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.orgao_publico ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.empresa ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.estabelecimento_empresa ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.estabelecimento_saude ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.instituicao_ensino ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);
ALTER TABLE nucleo.projeto_infraestrutura ADD COLUMN IF NOT EXISTS entidade_id bigint UNIQUE REFERENCES nucleo.entidade(entidade_id);

-- CNPJ canônico alfanumérico
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_consorcio_cnpj_formato') THEN ALTER TABLE referencia.consorcio_publico ADD CONSTRAINT ck_consorcio_cnpj_formato CHECK(referencia.cnpj_formato_valido(cnpj)) NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_instituicao_cnpj_formato') THEN ALTER TABLE nucleo.instituicao ADD CONSTRAINT ck_instituicao_cnpj_formato CHECK(referencia.cnpj_formato_valido(cnpj)) NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_estabelecimento_cnpj_formato') THEN ALTER TABLE nucleo.estabelecimento_empresa ADD CONSTRAINT ck_estabelecimento_cnpj_formato CHECK(referencia.cnpj_formato_valido(cnpj)) NOT VALID; END IF;
END $$;

-- --------------------------------------------------------------------------
-- PROVENIÊNCIA UNIVERSAL NAS 78 TABELAS DE INTEGRAÇÃO
-- --------------------------------------------------------------------------
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='integracao' LOOP
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS versao_recurso_id bigint REFERENCES catalogo.versao_recurso(versao_recurso_id)', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS lote_id uuid REFERENCES controle.lote_ingestao(lote_id)', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS objeto_bruto_padrao_id uuid REFERENCES bruto.objeto_coletado(objeto_id)', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS chave_origem_padrao varchar(600)', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS hash_registro char(64)', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS publicado_origem_em timestamptz', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS atualizado_origem_em timestamptz', r.tablename);
    EXECUTE format('ALTER TABLE integracao.%I ADD COLUMN IF NOT EXISTS coletado_em timestamptz NOT NULL DEFAULT now()', r.tablename);
  END LOOP;
END $$;

-- --------------------------------------------------------------------------
-- INTEGRAÇÃO: estruturas específicas para dimensões variáveis e históricos
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS integracao.ibge_sidra_observacao_categoria (
  observacao_sidra_id bigint NOT NULL REFERENCES integracao.ibge_sidra_observacao(observacao_sidra_id) ON DELETE CASCADE,
  classificacao_sidra_id bigint REFERENCES integracao.ibge_sidra_classificacao(classificacao_sidra_id),
  categoria_sidra_id bigint REFERENCES integracao.ibge_sidra_categoria(categoria_sidra_id),
  classificacao_codigo varchar(80),
  categoria_codigo varchar(120),
  categoria_nome varchar(500),
  ordem smallint,
  PRIMARY KEY(observacao_sidra_id,classificacao_codigo,categoria_codigo)
);
COMMENT ON TABLE integracao.ibge_sidra_observacao_categoria IS 'Normalização das classificações variáveis do SIDRA; JSON continua preservado na origem.';

CREATE TABLE IF NOT EXISTS integracao.siconfi_msc_dimensao (
  siconfi_msc_id bigint NOT NULL REFERENCES integracao.siconfi_msc(siconfi_msc_id) ON DELETE CASCADE,
  ordem smallint NOT NULL,
  nome_dimensao varchar(160),
  valor_dimensao varchar(500),
  codigo_dimensao varchar(160),
  PRIMARY KEY(siconfi_msc_id,ordem)
);
COMMENT ON TABLE integracao.siconfi_msc_dimensao IS 'Informações complementares da MSC sem pressupor número fixo de ICs.';

CREATE TABLE IF NOT EXISTS integracao.siconfi_demonstrativo_celula (
  siconfi_celula_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  tipo_demonstrativo varchar(20) NOT NULL CHECK(tipo_demonstrativo IN ('DCA','RREO','RGF','OUTRO')),
  codigo_ente varchar(30) NOT NULL,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  exercicio smallint NOT NULL,
  periodo_codigo varchar(40),
  anexo_codigo varchar(120),
  linha_codigo varchar(300),
  linha_nome varchar(600),
  coluna_codigo varchar(300),
  coluna_nome varchar(600),
  valor numeric(30,8),
  unidade varchar(80),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(fonte_id,tipo_demonstrativo,codigo_ente,exercicio,periodo_codigo,anexo_codigo,linha_codigo,coluna_codigo)
);

CREATE TABLE IF NOT EXISTS integracao.pncp_historico_situacao (
  pncp_historico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  pncp_contratacao_id bigint REFERENCES integracao.pncp_contratacao(pncp_contratacao_id) ON DELETE CASCADE,
  pncp_contrato_id bigint REFERENCES integracao.pncp_contrato(pncp_contrato_id) ON DELETE CASCADE,
  situacao varchar(160) NOT NULL,
  valido_desde timestamptz NOT NULL,
  valido_ate timestamptz,
  motivo text,
  CHECK(num_nonnulls(pncp_contratacao_id,pncp_contrato_id)=1)
);

CREATE TABLE IF NOT EXISTS integracao.pncp_aditivo_contrato (
