  pncp_contrato_id bigint NOT NULL REFERENCES integracao.pncp_contrato(pncp_contrato_id) ON DELETE CASCADE,
  identificador_origem varchar(180),
  numero_aditivo varchar(160),
  tipo varchar(120),
  data_assinatura date,
  valor_acrescimo numeric(24,4),
  valor_supressao numeric(24,4),
  nova_vigencia_fim date,
  objeto text,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(pncp_contrato_id,identificador_origem)
);

CREATE TABLE IF NOT EXISTS integracao.transferegov_historico_situacao (
  historico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  transferegov_instrumento_id bigint NOT NULL REFERENCES integracao.transferegov_instrumento(transferegov_instrumento_id) ON DELETE CASCADE,
  situacao varchar(160) NOT NULL,
  data_referencia date NOT NULL,
  valor_liberado numeric(24,4),
