);

CREATE TABLE IF NOT EXISTS integracao.obrasgov_historico_situacao (
  historico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  obrasgov_obra_id bigint NOT NULL REFERENCES integracao.obrasgov_obra(obrasgov_obra_id) ON DELETE CASCADE,
