);

CREATE TABLE IF NOT EXISTS integracao.rfb_historico_situacao_estabelecimento (
  historico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rfb_estabelecimento_id bigint NOT NULL REFERENCES integracao.rfb_estabelecimento(rfb_estabelecimento_id) ON DELETE CASCADE,
  situacao_cadastral varchar(40),
  motivo_situacao varchar(40),
