);

CREATE TABLE IF NOT EXISTS integracao.inpe_metadado_produto (
  inpe_metadado_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto varchar(80) NOT NULL,
  versao varchar(120),
  bioma varchar(120),
  data_referencia date,
  metodologia_uri text,
  resolucao_metros numeric(14,4),
  sistema_referencia varchar(100),
  status varchar(80),
  licenca text,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(produto,versao,bioma,data_referencia)
);

CREATE TABLE IF NOT EXISTS integracao.mapbiomas_transicao_municipal (
  transicao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  colecao varchar(80) NOT NULL,
  ano_inicial smallint NOT NULL,
  ano_final smallint NOT NULL,
  classe_origem_codigo varchar(50) NOT NULL,
  classe_destino_codigo varchar(50) NOT NULL,
  area_ha numeric(24,8) NOT NULL,
  percentual_territorio numeric(12,8),
  UNIQUE(municipio_id,colecao,ano_inicial,ano_final,classe_origem_codigo,classe_destino_codigo)
);

-- CNPJ RFB alfanumérico: validação por componentes após mudança de tipo
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_empresa_cnpj_basico') THEN ALTER TABLE integracao.rfb_empresa ADD CONSTRAINT ck_rfb_empresa_cnpj_basico CHECK(cnpj_basico ~ '^[0-9A-Z]{8}$') NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_estab_cnpj_basico') THEN ALTER TABLE integracao.rfb_estabelecimento ADD CONSTRAINT ck_rfb_estab_cnpj_basico CHECK(cnpj_basico ~ '^[0-9A-Z]{8}$') NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_estab_cnpj_ordem') THEN ALTER TABLE integracao.rfb_estabelecimento ADD CONSTRAINT ck_rfb_estab_cnpj_ordem CHECK(cnpj_ordem ~ '^[0-9A-Z]{4}$') NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_estab_cnpj_dv') THEN ALTER TABLE integracao.rfb_estabelecimento ADD CONSTRAINT ck_rfb_estab_cnpj_dv CHECK(cnpj_dv ~ '^[0-9]{2}$') NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_socio_cnpj_basico') THEN ALTER TABLE integracao.rfb_socio ADD CONSTRAINT ck_rfb_socio_cnpj_basico CHECK(cnpj_basico ~ '^[0-9A-Z]{8}$') NOT VALID; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_rfb_simples_cnpj_basico') THEN ALTER TABLE integracao.rfb_simples ADD CONSTRAINT ck_rfb_simples_cnpj_basico CHECK(cnpj_basico ~ '^[0-9A-Z]{8}$') NOT VALID; END IF;
END $$;

-- --------------------------------------------------------------------------
-- GEOESPACIAL: relações espaciais, precisão, cobertura e estatísticas zonais
-- --------------------------------------------------------------------------
ALTER TABLE geoespacial.feicao ADD COLUMN IF NOT EXISTS data_referencia date;
ALTER TABLE geoespacial.feicao ADD COLUMN IF NOT EXISTS valido_desde date;
ALTER TABLE geoespacial.feicao ADD COLUMN IF NOT EXISTS valido_ate date;
ALTER TABLE geoespacial.feicao ADD COLUMN IF NOT EXISTS precisao_metros numeric(18,6);
ALTER TABLE geoespacial.feicao ADD COLUMN IF NOT EXISTS metodo_posicionamento varchar(120);

CREATE TABLE IF NOT EXISTS geoespacial.geocodificacao (
  geocodificacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  endereco_id bigint REFERENCES nucleo.endereco(endereco_id),
  entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  ponto geometry(Point,4674) NOT NULL,
  metodo varchar(80) NOT NULL,
  pontuacao_confianca numeric(8,6) CHECK(pontuacao_confianca IS NULL OR pontuacao_confianca BETWEEN 0 AND 1),
  precisao_metros numeric(18,6),
  resultado_bruto jsonb NOT NULL DEFAULT '{}'::jsonb,
  geocodificado_em timestamptz NOT NULL DEFAULT now(),
  CHECK(num_nonnulls(endereco_id,entidade_id)>=1)
);

CREATE TABLE IF NOT EXISTS geoespacial.relacao_espacial (
  relacao_espacial_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  feicao_origem_id bigint NOT NULL REFERENCES geoespacial.feicao(feicao_id) ON DELETE CASCADE,
  feicao_destino_id bigint NOT NULL REFERENCES geoespacial.feicao(feicao_id) ON DELETE CASCADE,
  tipo_relacao varchar(60) NOT NULL CHECK(tipo_relacao IN ('intersecta','contem','contido_em','toca','proximo','cruza','sobrepoe')),
  area_intersecao_ha numeric(24,8),
  percentual_origem numeric(12,8),
  percentual_destino numeric(12,8),
  distancia_metros numeric(24,6),
  geometria_intersecao geometry(Geometry,4674),
  calculado_em timestamptz NOT NULL DEFAULT now(),
  versao_calculo varchar(80),
  CHECK(feicao_origem_id <> feicao_destino_id),
  UNIQUE(feicao_origem_id,feicao_destino_id,tipo_relacao,versao_calculo)
);

CREATE TABLE IF NOT EXISTS geoespacial.estatistica_zonal_raster (
  estatistica_zonal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  raster_id bigint NOT NULL REFERENCES geoespacial.raster_catalogo(raster_id) ON DELETE CASCADE,
  territorio_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
  classe_codigo varchar(120),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  contagem_pixels bigint,
  area_ha numeric(30,8),
  minimo numeric(30,10),
  maximo numeric(30,10),
  media numeric(30,10),
  soma numeric(30,10),
  desvio_padrao numeric(30,10),
  percentual_cobertura numeric(12,8),
  calculado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(raster_id,territorio_id,classe_codigo,periodo_id)
);

CREATE TABLE IF NOT EXISTS geoespacial.cobertura_territorial_recurso (
  cobertura_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  geometria_cobertura geometry(MultiPolygon,4674),
  percentual_cobertura numeric(12,8),
  data_referencia date,
  observacoes text
);

CREATE TABLE IF NOT EXISTS geoespacial.validacao_geometria (
  validacao_geometria_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  camada_id bigint REFERENCES geoespacial.camada(camada_id),
  feicao_id bigint REFERENCES geoespacial.feicao(feicao_id) ON DELETE CASCADE,
  valida boolean NOT NULL,
  motivo text,
  geometria_corrigida geometry(Geometry,4674),
  area_antes numeric(30,8),
  area_depois numeric(30,8),
  validado_em timestamptz NOT NULL DEFAULT now()
);

-- --------------------------------------------------------------------------
-- DOCUMENTAL: versão, trecho, tabela e valor extraído com confiança/citação
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS documental.versao_documento (
