  capitulo_codigo varchar(20),
  capitulo_nome varchar(400),
  grupo_codigo varchar(20),
  grupo_nome varchar(400),
  categoria_codigo varchar(20),
  categoria_nome varchar(400),
  causa_evitavel_id bigint REFERENCES referencia.causa_evitavel(causa_evitavel_id),
  versao_cid varchar(80) NOT NULL DEFAULT 'ATUAL',
  UNIQUE(codigo_cid,versao_cid)
);

CREATE TABLE IF NOT EXISTS dw.dim_cbo (
  cbo_sk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
