  codigo varchar(20) NOT NULL,
  titulo varchar(400),
  familia varchar(200),
  grande_grupo varchar(200),
  versao varchar(80) NOT NULL DEFAULT 'ATUAL',
  UNIQUE(codigo,versao)
);

CREATE TABLE IF NOT EXISTS dw.dim_procedimento_saude (
  procedimento_sk bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(30) NOT NULL,
  nome varchar(600),
  grupo varchar(300),
  subgrupo varchar(300),
  forma_organizacao varchar(300),
  complexidade varchar(100),
  versao varchar(80) NOT NULL DEFAULT 'ATUAL',
  valido_desde date,
  valido_ate date,
  UNIQUE(codigo,versao)
);

CREATE TABLE IF NOT EXISTS dw.fato_observacao (
  observacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  chave_observacao char(64) NOT NULL UNIQUE,
  indicador_sk bigint NOT NULL REFERENCES dw.dim_indicador(indicador_sk),
  territorio_principal_sk bigint REFERENCES dw.dim_territorio(territorio_sk),
  tempo_id integer REFERENCES dw.dim_tempo(tempo_id),
  periodo_sk bigint REFERENCES dw.dim_periodo(periodo_sk),
  fonte_sk bigint NOT NULL REFERENCES dw.dim_fonte(fonte_sk),
  metodologia_sk bigint REFERENCES dw.dim_metodologia(metodologia_sk),
  unidade_sk bigint REFERENCES dw.dim_unidade_medida(unidade_sk),
  status_dado_sk smallint REFERENCES dw.dim_status_dado(status_dado_sk),
  valor_numero numeric(38,12),
  valor_texto text,
  valor_booleano boolean,
  numerador numeric(38,12),
  denominador numeric(38,12),
  multiplicador numeric(30,10),
  erro_padrao numeric(30,12),
  intervalo_confianca_inferior numeric(38,12),
  intervalo_confianca_superior numeric(38,12),
  tamanho_amostra bigint,
  cobertura_percentual numeric(12,8),
  completude_percentual numeric(12,8),
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  provisorio boolean NOT NULL DEFAULT false,
  suprimido boolean NOT NULL DEFAULT false,
  motivo_supressao text,
  revisao varchar(120) NOT NULL DEFAULT 'atual',
  data_referencia date,
  publicado_em timestamptz,
  coletado_em timestamptz,
  lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
  granularidade_origem varchar(160),
  regra_agregacao varchar(80),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK(num_nonnulls(valor_numero,valor_texto,valor_booleano)>=1 OR (numerador IS NOT NULL AND denominador IS NOT NULL))
);
COMMENT ON TABLE dw.fato_observacao IS 'Fato universal de cauda longa; complementa, não substitui, os fatos tipados.';

CREATE TABLE IF NOT EXISTS dw.fato_observacao_dimensao (
  observacao_dimensao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  observacao_id bigint NOT NULL REFERENCES dw.fato_observacao(observacao_id) ON DELETE CASCADE,
