  classe_destino_sk bigint REFERENCES dw.dim_uso_solo(uso_solo_sk),
  area_ha numeric(30,8) NOT NULL,
  percentual_territorio numeric(12,8),
  colecao varchar(80),
  revisao varchar(80) NOT NULL DEFAULT 'atual'
);

-- Link opcional de todos os fatos tipados a uma observação universal.
DO $$
DECLARE r record;
BEGIN
  FOR r IN SELECT tablename FROM pg_tables WHERE schemaname='dw' AND tablename LIKE 'fato_%' AND tablename NOT IN ('fato_observacao','fato_observacao_dimensao') LOOP
    EXECUTE format('ALTER TABLE dw.%I ADD COLUMN IF NOT EXISTS observacao_id bigint REFERENCES dw.fato_observacao(observacao_id)', r.tablename);
  END LOOP;
END $$;

