-- --------------------------------------------------------------------------
-- SEMÂNTICO: banco de perguntas difíceis, planejamento e avaliação da Xingú
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS semantico.pergunta_teste (
  pergunta_teste_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(120) NOT NULL UNIQUE,
  dominio varchar(120) NOT NULL,
  pergunta text NOT NULL,
  nivel_dificuldade varchar(20) NOT NULL CHECK(nivel_dificuldade IN ('media','alta','muito_alta')),
