  observacoes text,
  criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS semantico.pergunta_fonte (
  pergunta_teste_id bigint NOT NULL REFERENCES semantico.pergunta_teste(pergunta_teste_id) ON DELETE CASCADE,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  papel varchar(30) NOT NULL DEFAULT 'principal' CHECK(papel IN ('principal','complementar','denominador','validacao','contexto')),
  obrigatoria boolean NOT NULL DEFAULT true,
  PRIMARY KEY(pergunta_teste_id,fonte_id,papel)
);

CREATE TABLE IF NOT EXISTS semantico.pergunta_requisito (
  pergunta_requisito_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  pergunta_teste_id bigint NOT NULL REFERENCES semantico.pergunta_teste(pergunta_teste_id) ON DELETE CASCADE,
  tipo varchar(40) NOT NULL CHECK(tipo IN ('dimensao','fato','indicador','classificacao','territorio','periodo','qualidade','privacidade','geoespacial','documental')),
  codigo varchar(200) NOT NULL,
  descricao text,
  obrigatorio boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS semantico.mapeamento_termo_indicador (
  mapeamento_termo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  termo varchar(300) NOT NULL,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  contexto varchar(300),
  prioridade smallint NOT NULL DEFAULT 1,
  UNIQUE(termo,indicador_id,contexto)
);

CREATE TABLE IF NOT EXISTS semantico.ambiguidade_termo (
  ambiguidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  termo varchar(300) NOT NULL,
  dominio varchar(120),
  interpretacao varchar(500) NOT NULL,
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  regra_desambiguacao text,
  precisa_perguntar boolean NOT NULL DEFAULT false
);

CREATE TABLE IF NOT EXISTS semantico.plano_consulta (
  plano_consulta_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  texto_pergunta text NOT NULL,
  intencao jsonb NOT NULL DEFAULT '{}'::jsonb,
  indicadores jsonb NOT NULL DEFAULT '[]'::jsonb,
  territorios jsonb NOT NULL DEFAULT '[]'::jsonb,
  periodos jsonb NOT NULL DEFAULT '[]'::jsonb,
  filtros jsonb NOT NULL DEFAULT '{}'::jsonb,
  fontes_selecionadas jsonb NOT NULL DEFAULT '[]'::jsonb,
  sql_planejado text,
  limitacoes_detectadas jsonb NOT NULL DEFAULT '[]'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS semantico.citacao_resposta (
  citacao_resposta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plano_consulta_id uuid REFERENCES semantico.plano_consulta(plano_consulta_id) ON DELETE CASCADE,
  evidencia_id bigint REFERENCES semantico.evidencia(evidencia_id),
  observacao_id bigint REFERENCES dw.fato_observacao(observacao_id),
  documento_id bigint REFERENCES documental.documento(documento_id),
  trecho_documento_id bigint REFERENCES documental.trecho_documento(trecho_documento_id),
  texto_suporte text,
  ordem smallint
);

CREATE TABLE IF NOT EXISTS semantico.avaliacao_resposta (
  avaliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plano_consulta_id uuid NOT NULL REFERENCES semantico.plano_consulta(plano_consulta_id) ON DELETE CASCADE,
  cobertura numeric(8,6),
  precisao numeric(8,6),
  atualidade numeric(8,6),
  rastreabilidade numeric(8,6),
  coerencia numeric(8,6),
  resposta_deve_ser_recusada boolean NOT NULL DEFAULT false,
  motivo_recusa text,
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb,
  avaliado_em timestamptz NOT NULL DEFAULT now()
);

-- --------------------------------------------------------------------------
-- SEGURANÇA/PRIVACIDADE: impedir que perguntas difíceis virem vazamento de dado
-- --------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS seguranca.classificacao_sensibilidade (
  classificacao_sensibilidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  nivel smallint NOT NULL CHECK(nivel BETWEEN 0 AND 5),
  descricao text
);

CREATE TABLE IF NOT EXISTS seguranca.politica_divulgacao (
  politica_divulgacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(120) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  classificacao_sensibilidade_id smallint REFERENCES seguranca.classificacao_sensibilidade(classificacao_sensibilidade_id),
  tamanho_minimo_celula bigint,
  arredondamento_base integer,
  permitir_detalhe_individual boolean NOT NULL DEFAULT false,
  regra_suprimir_zeros boolean NOT NULL DEFAULT false,
  regra text,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS seguranca.conjunto_classificacao (
  conjunto_id bigint NOT NULL REFERENCES catalogo.conjunto_dado(conjunto_id) ON DELETE CASCADE,
  classificacao_sensibilidade_id smallint NOT NULL REFERENCES seguranca.classificacao_sensibilidade(classificacao_sensibilidade_id),
  politica_divulgacao_id bigint REFERENCES seguranca.politica_divulgacao(politica_divulgacao_id),
  justificativa text,
  PRIMARY KEY(conjunto_id,classificacao_sensibilidade_id)
);

CREATE TABLE IF NOT EXISTS seguranca.evento_acesso (
  evento_acesso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  usuario_referencia varchar(300),
  perfil varchar(120),
  recurso varchar(500) NOT NULL,
  finalidade varchar(300),
  quantidade_registros bigint,
  filtros jsonb,
  permitido boolean NOT NULL,
  motivo text,
  ocorrido_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS seguranca.regra_mascaramento (
  regra_mascaramento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tabela varchar(300) NOT NULL,
  coluna varchar(300) NOT NULL,
  classificacao_sensibilidade_id smallint REFERENCES seguranca.classificacao_sensibilidade(classificacao_sensibilidade_id),
  estrategia varchar(80) NOT NULL CHECK(estrategia IN ('hash','parcial','nulo','agregacao','tokenizacao','generalizacao','nenhuma')),
  expressao text,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(tabela,coluna)
);

-- --------------------------------------------------------------------------
-- Índices adicionais de resiliência e desempenho analítico
-- --------------------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_cobertura_conjunto_conjunto_data ON catalogo.cobertura_conjunto(conjunto_id,data_inicio,data_fim);
CREATE INDEX IF NOT EXISTS idx_limitacao_conjunto_ativa ON catalogo.limitacao_conjunto(conjunto_id,severidade) WHERE ativo=true;
CREATE INDEX IF NOT EXISTS idx_reconciliacao_indicador_periodo ON controle.reconciliacao_fonte(indicador_id,territorio_id,periodo_id);
CREATE INDEX IF NOT EXISTS idx_frescor_recurso_data ON controle.monitoramento_frescor(recurso_id,verificado_em DESC);
CREATE INDEX IF NOT EXISTS idx_item_classificacao_codigo ON referencia.item_classificacao(sistema_classificacao_id,codigo);
CREATE INDEX IF NOT EXISTS idx_item_classificacao_nome_trgm ON referencia.item_classificacao USING gin(nome gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_identificador_entidade_valor ON nucleo.identificador_entidade(sistema,tipo,valor_normalizado);
CREATE INDEX IF NOT EXISTS idx_nome_entidade_trgm ON nucleo.nome_entidade USING gin(nome gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_correspondencia_entidade_origem ON nucleo.correspondencia_entidade(fonte_id,tabela_origem,chave_origem);
CREATE INDEX IF NOT EXISTS idx_relacao_espacial_origem ON geoespacial.relacao_espacial(feicao_origem_id,tipo_relacao);
CREATE INDEX IF NOT EXISTS idx_relacao_espacial_destino ON geoespacial.relacao_espacial(feicao_destino_id,tipo_relacao);
CREATE INDEX IF NOT EXISTS idx_relacao_espacial_geom ON geoespacial.relacao_espacial USING gist(geometria_intersecao);
CREATE INDEX IF NOT EXISTS idx_estatistica_zonal_terr_periodo ON geoespacial.estatistica_zonal_raster(territorio_id,periodo_id);
CREATE INDEX IF NOT EXISTS idx_trecho_documento_busca ON documental.trecho_documento USING gin(vetor_busca);
CREATE INDEX IF NOT EXISTS idx_valor_extraido_campo ON documental.valor_extraido(nome_campo,territorio_id);
CREATE INDEX IF NOT EXISTS idx_obs_ind_terr_periodo ON dw.fato_observacao(indicador_sk,territorio_principal_sk,periodo_sk);
CREATE INDEX IF NOT EXISTS idx_obs_fonte_publicacao ON dw.fato_observacao(fonte_sk,publicado_em DESC);
CREATE INDEX IF NOT EXISTS idx_obs_status_provisorio ON dw.fato_observacao(status_dado_sk,provisorio) WHERE suprimido=false;
CREATE INDEX IF NOT EXISTS idx_obs_dim_codigo_valor ON dw.fato_observacao_dimensao(codigo_dimensao,valor_codigo);
CREATE INDEX IF NOT EXISTS idx_mortalidade_idade_causa_periodo ON dw.fato_mortalidade(territorio_sk,periodo_sk,idade_sk,causa_obito_sk);
CREATE INDEX IF NOT EXISTS idx_transicao_solo_terr_periodos ON dw.fato_transicao_uso_solo(territorio_sk,periodo_inicial_sk,periodo_final_sk);
CREATE INDEX IF NOT EXISTS idx_pergunta_teste_dominio_status ON semantico.pergunta_teste(dominio,status_cobertura);
CREATE INDEX IF NOT EXISTS idx_mapeamento_termo_trgm ON semantico.mapeamento_termo_indicador USING gin(termo gin_trgm_ops);

