-- Regras fundamentais de agregação dos indicadores derivados
INSERT INTO catalogo.regra_agregacao_indicador(indicador_id,eixo,operacao,expressao,observacoes)
SELECT indicador_id,'territorio','recalcular_razao','SUM(numerador)/NULLIF(SUM(denominador),0)*multiplicador','Taxas devem ser recalculadas a partir dos componentes, nunca pela média simples.'
FROM catalogo.indicador WHERE codigo IN ('TAXA_MORTALIDADE_INFANTIL','TAXA_MORTALIDADE_NEONATAL_PRECOCE','TAXA_MORTALIDADE_NEONATAL','LEITOS_UTI_POR_10_MIL')
ON CONFLICT(indicador_id,eixo) DO UPDATE SET operacao=EXCLUDED.operacao,expressao=EXCLUDED.expressao,observacoes=EXCLUDED.observacoes;

-- Metodologia inicial para TMI (versionável)
INSERT INTO catalogo.metodologia_indicador(indicador_id,versao,descricao,formula,criterios_inclusao,criterios_exclusao,fonte_metodologica,valido_desde)
SELECT indicador_id,'1.0','Taxa de mortalidade infantil por residência.','(óbitos de menores de 1 ano residentes / nascidos vivos de mães residentes) * 1000','Óbitos com idade menor de 1 ano; território por residência.','Registros fora do critério etário ou sem território compatível.','SIM + SINASC / definição epidemiológica operacional ITMT',DATE '1900-01-01'
FROM catalogo.indicador WHERE codigo='TAXA_MORTALIDADE_INFANTIL'
ON CONFLICT(indicador_id,versao) DO NOTHING;

