SET TIME ZONE 'America/Cuiaba';


-- REFERENCIAS E CLASSIFICACOES TRANSVERSAIS

CREATE TABLE IF NOT EXISTS referencia.tipo_periodicidade (
  tipo_periodicidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  duracao_aproximada interval,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.tipo_estimativa (
  tipo_estimativa_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  observado boolean NOT NULL DEFAULT false,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.cenario_analitico (
  cenario_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(120) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  tipo varchar(80),
  descricao text,
  valido_desde date,
  valido_ate date,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS referencia.modal_transporte (
  modal_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(120) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.tipo_rede_transporte (
  tipo_rede_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  modal_id smallint REFERENCES referencia.modal_transporte(modal_id)
);

CREATE TABLE IF NOT EXISTS referencia.natureza_criminal (
  natureza_criminal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  grupo varchar(160),
  subgrupo varchar(160),
  versao_classificacao varchar(80),
  valido_desde date,
  valido_ate date,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.tipo_unidade_prisional (
  tipo_unidade_prisional_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL
);

