-- Refinamento do fato universal para dados subdiarios, estimativas e cenarios.
ALTER TABLE dw.fato_observacao
  ADD COLUMN IF NOT EXISTS instante_inicio timestamptz,
  ADD COLUMN IF NOT EXISTS instante_fim timestamptz,
  ADD COLUMN IF NOT EXISTS resolucao_temporal varchar(80),
  ADD COLUMN IF NOT EXISTS tipo_estimativa_id smallint REFERENCES referencia.tipo_estimativa(tipo_estimativa_id),
  ADD COLUMN IF NOT EXISTS cenario_id bigint REFERENCES referencia.cenario_analitico(cenario_id),
  ADD COLUMN IF NOT EXISTS coeficiente_variacao numeric(20,12),
  ADD COLUMN IF NOT EXISTS universo_estimado numeric(38,12),
  ADD COLUMN IF NOT EXISTS data_homologacao timestamptz,
  ADD COLUMN IF NOT EXISTS status_revisao varchar(80),
  ADD COLUMN IF NOT EXISTS versao_classificacao varchar(120),
  ADD COLUMN IF NOT EXISTS precisao_espacial_m numeric(20,6);

ALTER TABLE dw.fato_observacao
  DROP CONSTRAINT IF EXISTS ck_fato_observacao_intervalo;
ALTER TABLE dw.fato_observacao
  ADD CONSTRAINT ck_fato_observacao_intervalo
  CHECK(instante_fim IS NULL OR instante_inicio IS NULL OR instante_fim >= instante_inicio);


