  revisao varchar(120) NOT NULL DEFAULT 'atual',
  provisorio boolean NOT NULL DEFAULT false,
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS dw.fato_atendimento_suas (
  registro_fato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_sk bigint REFERENCES dw.dim_territorio(territorio_sk),
  tempo_id integer REFERENCES dw.dim_tempo(tempo_id),
  fonte_sk bigint NOT NULL REFERENCES dw.dim_fonte(fonte_sk),
  equipamento_suas_sk bigint REFERENCES dw.dim_equipamento_suas(equipamento_suas_sk),
  servico varchar(300),
  atendimentos bigint,
  familias bigint,
  pessoas bigint,
  lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
  revisao varchar(120) NOT NULL DEFAULT 'atual',
  provisorio boolean NOT NULL DEFAULT false,
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS dw.fato_beneficio_social_f2 (
  registro_fato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_sk bigint REFERENCES dw.dim_territorio(territorio_sk),
  tempo_id integer REFERENCES dw.dim_tempo(tempo_id),
  fonte_sk bigint NOT NULL REFERENCES dw.dim_fonte(fonte_sk),
  beneficio varchar(220),
  beneficiarios bigint,
  familias bigint,
  valor_pago numeric(30,4),
  lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
  revisao varchar(120) NOT NULL DEFAULT 'atual',
  provisorio boolean NOT NULL DEFAULT false,
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS dw.fato_financiamento_suas (
  registro_fato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_sk bigint REFERENCES dw.dim_territorio(territorio_sk),
  tempo_id integer REFERENCES dw.dim_tempo(tempo_id),
  fonte_sk bigint NOT NULL REFERENCES dw.dim_fonte(fonte_sk),
  bloco_programa varchar(200),
  tipo_repasse varchar(120),
  valor numeric(30,4),
  lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
  revisao varchar(120) NOT NULL DEFAULT 'atual',
  provisorio boolean NOT NULL DEFAULT false,
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS dw.fato_osc (
  registro_fato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_sk bigint REFERENCES dw.dim_territorio(territorio_sk),
  tempo_id integer REFERENCES dw.dim_tempo(tempo_id),
  fonte_sk bigint NOT NULL REFERENCES dw.dim_fonte(fonte_sk),
  entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  area_atuacao varchar(250),
  osc_ativas bigint,
  recursos_publicos numeric(30,4),
  lote_id uuid REFERENCES controle.lote_ingestao(lote_id),
  revisao varchar(120) NOT NULL DEFAULT 'atual',
  provisorio boolean NOT NULL DEFAULT false,
  qualidade_geral numeric(8,6) CHECK(qualidade_geral IS NULL OR qualidade_geral BETWEEN 0 AND 1),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);


