-- Visoes semanticas de apoio.
CREATE OR REPLACE VIEW semantico.v_capacidade_analitica_f2 AS
SELECT c.capacidade_id,c.codigo,c.area,c.pergunta_modelo,c.status,c.condicoes,
       count(l.limite_resposta_id) AS limites_catalogados
FROM semantico.capacidade_analitica c
LEFT JOIN semantico.limite_resposta l ON l.capacidade_id=c.capacidade_id
GROUP BY c.capacidade_id;

CREATE OR REPLACE VIEW controle.v_discrepancias_f2 AS
SELECT cc.*, fa.codigo AS fonte_a, fb.codigo AS fonte_b
FROM controle.consistencia_cruzada cc
LEFT JOIN catalogo.fonte_dado fa ON fa.fonte_id=cc.fonte_a_id
LEFT JOIN catalogo.fonte_dado fb ON fb.fonte_id=cc.fonte_b_id
WHERE cc.status IS DISTINCT FROM 'conciliado';


