-- ===== FASE 3 REFINADA R1 =====
-- Plataforma ITMT - Fase 3 Refinada R1

-- Municipalização dos 142 municípios + consórcios e governança local

-- Gerado em 28/08/2026

CREATE SCHEMA IF NOT EXISTS municipal;



ALTER TABLE IF EXISTS referencia.consorcio_publico ALTER COLUMN cnpj TYPE varchar(32);

ALTER TABLE IF EXISTS nucleo.instituicao ALTER COLUMN cnpj TYPE varchar(32);

ALTER TABLE IF EXISTS nucleo.empresa ALTER COLUMN cnpj_basico TYPE varchar(32);

ALTER TABLE IF EXISTS nucleo.estabelecimento_empresa ALTER COLUMN cnpj TYPE varchar(32);

ALTER TABLE IF EXISTS dw.dim_empresa ALTER COLUMN cnpj_basico TYPE varchar(32);



CREATE TABLE IF NOT EXISTS catalogo.tipo_fonte_municipal (
  tipo_fonte_municipal_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(220) NOT NULL,
  dominio varchar(120) NOT NULL,
  metodo_preferencial varchar(100),
  periodicidade_esperada varchar(80),
  prioridade varchar(5) NOT NULL DEFAULT 'P1',
  descricao text,
  ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE catalogo.tipo_fonte_municipal IS 'Tipos de fontes esperadas para cada município.';



CREATE TABLE IF NOT EXISTS catalogo.fonte_municipal (
  fonte_municipal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  tipo_fonte_municipal_id smallint NOT NULL REFERENCES catalogo.tipo_fonte_municipal(tipo_fonte_municipal_id),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  nome varchar(300),
  url text,
  url_api text,
  status varchar(30) NOT NULL DEFAULT 'a_descobrir' CHECK(status IN ('a_descobrir','ativa','instavel','indisponivel','substituida','descontinuada','nao_se_aplica')),
  autoridade_fonte varchar(40) DEFAULT 'primaria',
  inicio_vigencia date,
  fim_vigencia date,
  ultima_verificacao timestamptz,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(municipio_id,tipo_fonte_municipal_id,inicio_vigencia)
);

COMMENT ON TABLE catalogo.fonte_municipal IS 'Instância municipal de cada tipo de fonte, com vigência e status.';



CREATE TABLE IF NOT EXISTS catalogo.perfil_integracao_municipal (
  perfil_integracao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  tipo_acesso varchar(80),
  paginacao jsonb NOT NULL DEFAULT '{}'::jsonb,
  autenticacao varchar(120),
  parser varchar(120),
  estrategia_delta varchar(200),
  regras_rate_limit jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE catalogo.perfil_integracao_municipal IS 'Perfis reutilizáveis de integração para famílias de portais municipais.';



CREATE TABLE IF NOT EXISTS catalogo.sistema_fornecedor_municipal (
  sistema_fornecedor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nome_fornecedor varchar(250) NOT NULL,
  nome_sistema varchar(250),
  produto varchar(250),
  url_fornecedor text,
  familia_tecnologica varchar(120),
  observacoes text,
  UNIQUE(nome_fornecedor,nome_sistema,produto)
);

COMMENT ON TABLE catalogo.sistema_fornecedor_municipal IS 'Catálogo de fornecedores/plataformas usados pelos municípios.';



CREATE TABLE IF NOT EXISTS catalogo.implantacao_sistema_municipal (
  implantacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  sistema_fornecedor_id bigint NOT NULL REFERENCES catalogo.sistema_fornecedor_municipal(sistema_fornecedor_id),
  tipo_fonte_municipal_id smallint REFERENCES catalogo.tipo_fonte_municipal(tipo_fonte_municipal_id),
  inicio_vigencia date NOT NULL,
  fim_vigencia date,
  url_base text,
  versao varchar(100),
  perfil_integracao_id bigint REFERENCES catalogo.perfil_integracao_municipal(perfil_integracao_id),
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(municipio_id,sistema_fornecedor_id,inicio_vigencia)
);

COMMENT ON TABLE catalogo.implantacao_sistema_municipal IS 'Histórico de sistemas/fornecedores adotados por município.';



CREATE TABLE IF NOT EXISTS catalogo.endpoint_municipal (
  endpoint_municipal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_municipal_id bigint NOT NULL REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  perfil_integracao_id bigint REFERENCES catalogo.perfil_integracao_municipal(perfil_integracao_id),
  nome varchar(240) NOT NULL,
  url text NOT NULL,
  metodo_http varchar(10) DEFAULT 'GET',
  tipo_recurso varchar(50),
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  cabecalhos jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  inicio_vigencia date,
  fim_vigencia date,
  UNIQUE(fonte_municipal_id,url,inicio_vigencia)
);

COMMENT ON TABLE catalogo.endpoint_municipal IS 'Endpoints e recursos concretos dos portais municipais.';



CREATE TABLE IF NOT EXISTS catalogo.obrigacao_transparencia_municipal (
  obrigacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  base_legal text,
  periodicidade_esperada varchar(80),
  tipo_fonte_municipal_id smallint REFERENCES catalogo.tipo_fonte_municipal(tipo_fonte_municipal_id),
  descricao text,
  ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE catalogo.obrigacao_transparencia_municipal IS 'Obrigações de transparência/publicação monitoráveis.';



CREATE TABLE IF NOT EXISTS catalogo.expectativa_publicacao_local (
  expectativa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  obrigacao_id bigint NOT NULL REFERENCES catalogo.obrigacao_transparencia_municipal(obrigacao_id),
  aplicavel boolean NOT NULL DEFAULT true,
  justificativa_nao_aplicavel text,
  inicio_vigencia date NOT NULL DEFAULT DATE '1900-01-01',
  fim_vigencia date,
  UNIQUE(municipio_id,obrigacao_id,inicio_vigencia)
);

COMMENT ON TABLE catalogo.expectativa_publicacao_local IS 'Matriz de obrigações esperadas por município.';



CREATE TABLE IF NOT EXISTS catalogo.cobertura_fonte_municipal (
  cobertura_fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_municipal_id bigint NOT NULL REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  campo_semantico varchar(200) NOT NULL,
  data_inicio date,
  data_fim date,
  granularidade varchar(100),
  completude_pct numeric(7,4),
  status varchar(30) DEFAULT 'desconhecido',
  observacoes text,
  UNIQUE(fonte_municipal_id,campo_semantico,data_inicio,data_fim)
);

COMMENT ON TABLE catalogo.cobertura_fonte_municipal IS 'Cobertura histórica e granularidade por campo/fonte.';



CREATE TABLE IF NOT EXISTS catalogo.autoridade_fonte_local (
  autoridade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(150) NOT NULL,
  peso_prioridade numeric(8,4) NOT NULL DEFAULT 1,
  descricao text
);

COMMENT ON TABLE catalogo.autoridade_fonte_local IS 'Classificação de autoridade de fontes locais e agregadoras.';



CREATE TABLE IF NOT EXISTS controle.monitoramento_portal_municipal (
  monitoramento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_municipal_id bigint NOT NULL REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  verificado_em timestamptz NOT NULL DEFAULT now(),
  status_http integer,
  tempo_resposta_ms integer,
  conteudo_hash char(64),
  certificado_valido boolean,
  observacao text
);

COMMENT ON TABLE controle.monitoramento_portal_municipal IS 'Monitoramento de disponibilidade e mudança dos portais municipais.';



CREATE TABLE IF NOT EXISTS controle.disponibilidade_endpoint_municipal (
  disponibilidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  endpoint_municipal_id bigint NOT NULL REFERENCES catalogo.endpoint_municipal(endpoint_municipal_id),
  inicio_indisponibilidade timestamptz NOT NULL,
  fim_indisponibilidade timestamptz,
  causa varchar(200),
  impacto varchar(200),
  confirmado boolean DEFAULT false
);

COMMENT ON TABLE controle.disponibilidade_endpoint_municipal IS 'Janelas de indisponibilidade de endpoints municipais.';



CREATE TABLE IF NOT EXISTS controle.mudanca_fornecedor_municipal (
  mudanca_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  tipo_fonte_municipal_id smallint REFERENCES catalogo.tipo_fonte_municipal(tipo_fonte_municipal_id),
  implantacao_anterior_id bigint REFERENCES catalogo.implantacao_sistema_municipal(implantacao_id),
  implantacao_nova_id bigint REFERENCES catalogo.implantacao_sistema_municipal(implantacao_id),
  detectado_em timestamptz NOT NULL DEFAULT now(),
  impacto_schema jsonb NOT NULL DEFAULT '{}'::jsonb,
  status_migracao varchar(40)
);

COMMENT ON TABLE controle.mudanca_fornecedor_municipal IS 'Mudanças de fornecedor/plataforma e impacto no ETL.';



CREATE TABLE IF NOT EXISTS controle.qualidade_fonte_municipal (
  qualidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_municipal_id bigint NOT NULL REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  completude numeric(7,4),
  pontualidade numeric(7,4),
  consistencia numeric(7,4),
  unicidade numeric(7,4),
  validade numeric(7,4),
  nota_geral numeric(7,4),
  calculado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE controle.qualidade_fonte_municipal IS 'Score multidimensional de qualidade por fonte municipal.';



CREATE TABLE IF NOT EXISTS controle.lacuna_publicacao_municipal (
  lacuna_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  obrigacao_id bigint REFERENCES catalogo.obrigacao_transparencia_municipal(obrigacao_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  tipo_lacuna varchar(60) NOT NULL,
  detectado_em timestamptz NOT NULL DEFAULT now(),
  resolvido_em timestamptz,
  observacao text
);

COMMENT ON TABLE controle.lacuna_publicacao_municipal IS 'Ausência de publicação não é tratada como valor zero.';



CREATE TABLE IF NOT EXISTS controle.divergencia_municipal (
  divergencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  fonte_a_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  fonte_b_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  valor_a numeric(30,10),
  valor_b numeric(30,10),
  diferenca_absoluta numeric(30,10),
  diferenca_percentual numeric(20,8),
  tolerancia numeric(20,8),
  status varchar(40),
  justificativa text
);

COMMENT ON TABLE controle.divergencia_municipal IS 'Divergência local entre fonte municipal e fontes agregadoras.';



CREATE TABLE IF NOT EXISTS controle.reconciliacao_municipal (
  reconciliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  divergencia_id bigint NOT NULL REFERENCES controle.divergencia_municipal(divergencia_id),
  fonte_preferida_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  criterio varchar(240),
  decisao varchar(80),
  responsavel varchar(160),
  decidido_em timestamptz,
  evidencia text
);

COMMENT ON TABLE controle.reconciliacao_municipal IS 'Decisão auditável para divergências municipais.';



CREATE TABLE IF NOT EXISTS controle.atraso_obrigacao_municipal (
  atraso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  obrigacao_id bigint NOT NULL REFERENCES catalogo.obrigacao_transparencia_municipal(obrigacao_id),
  data_prevista date,
  data_publicacao date,
  dias_atraso integer,
  status varchar(30),
  observacao text
);

COMMENT ON TABLE controle.atraso_obrigacao_municipal IS 'Pontualidade de obrigações de transparência.';



CREATE TABLE IF NOT EXISTS controle.auditoria_publicacao_municipal (
  auditoria_publicacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_municipal_id bigint REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  url text,
  publicado_em timestamptz,
  coletado_em timestamptz NOT NULL DEFAULT now(),
  hash_conteudo char(64),
  assinatura_valida boolean,
  imutabilidade_confirmada boolean,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE controle.auditoria_publicacao_municipal IS 'Auditoria de publicações locais.';



CREATE TABLE IF NOT EXISTS controle.cobertura_municipal (
  cobertura_municipal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  fontes_esperadas integer,
  fontes_ativas integer,
  fontes_com_dado integer,
  cobertura_pct numeric(7,4),
  calculado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(municipio_id,periodo_id)
);

COMMENT ON TABLE controle.cobertura_municipal IS 'Cobertura global de dados por município e período.';



CREATE TABLE IF NOT EXISTS referencia.tipo_unidade_administrativa_municipal (
  tipo_unidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  nivel smallint,
  descricao text
);

COMMENT ON TABLE referencia.tipo_unidade_administrativa_municipal IS 'Tipos de secretarias, departamentos, autarquias, fundações e fundos.';



CREATE TABLE IF NOT EXISTS referencia.tipo_norma_municipal (
  tipo_norma_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  hierarquia smallint,
  descricao text
);

COMMENT ON TABLE referencia.tipo_norma_municipal IS 'Classificação das normas municipais.';



CREATE TABLE IF NOT EXISTS referencia.situacao_norma_municipal (
  situacao_norma_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(120) NOT NULL,
  ativa boolean
);

COMMENT ON TABLE referencia.situacao_norma_municipal IS 'Situação jurídica da norma.';



CREATE TABLE IF NOT EXISTS referencia.tipo_plano_municipal (
  tipo_plano_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  dominio varchar(100),
  periodicidade_legal varchar(100)
);

COMMENT ON TABLE referencia.tipo_plano_municipal IS 'Tipos de PPA, Plano Diretor e planos setoriais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_conselho_municipal (
  tipo_conselho_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  dominio varchar(100)
);

COMMENT ON TABLE referencia.tipo_conselho_municipal IS 'Tipos de conselhos municipais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_fundo_municipal (
  tipo_fundo_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  dominio varchar(100)
);

COMMENT ON TABLE referencia.tipo_fundo_municipal IS 'Tipos de fundos municipais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_tributo_municipal (
  tipo_tributo_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(150) NOT NULL,
  categoria varchar(80),
  base_constitucional text
);

COMMENT ON TABLE referencia.tipo_tributo_municipal IS 'IPTU, ISSQN, ITBI, taxas e contribuições locais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_servico_municipal (
  tipo_servico_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(220) NOT NULL,
  area varchar(120),
  servico_digital boolean
);

COMMENT ON TABLE referencia.tipo_servico_municipal IS 'Catálogo de serviços públicos municipais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_equipamento_urbano (
  tipo_equipamento_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  area varchar(100)
);

COMMENT ON TABLE referencia.tipo_equipamento_urbano IS 'Equipamentos urbanos e comunitários.';



CREATE TABLE IF NOT EXISTS referencia.tipo_via_municipal (
  tipo_via_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(150) NOT NULL,
  urbana boolean,
  rural boolean
);

COMMENT ON TABLE referencia.tipo_via_municipal IS 'Tipos de vias urbanas e rurais locais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_pavimento (
  tipo_pavimento_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(150) NOT NULL,
  permeavel boolean
);

COMMENT ON TABLE referencia.tipo_pavimento IS 'Tipos de revestimento/pavimento.';



CREATE TABLE IF NOT EXISTS referencia.tipo_obra_municipal (
  tipo_obra_municipal_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  setor varchar(100)
);

COMMENT ON TABLE referencia.tipo_obra_municipal IS 'Tipos locais de obra.';



CREATE TABLE IF NOT EXISTS referencia.tipo_licenca_municipal (
  tipo_licenca_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  dominio varchar(100)
);

COMMENT ON TABLE referencia.tipo_licenca_municipal IS 'Licenças urbanísticas, ambientais e econômicas.';



CREATE TABLE IF NOT EXISTS referencia.tipo_risco_municipal (
  tipo_risco_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  grupo varchar(100)
);

COMMENT ON TABLE referencia.tipo_risco_municipal IS 'Riscos de inundação, deslizamento, incêndio e outros.';



CREATE TABLE IF NOT EXISTS referencia.tipo_proposicao_legislativa (
  tipo_proposicao_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL
);

COMMENT ON TABLE referencia.tipo_proposicao_legislativa IS 'Tipos de proposições legislativas municipais.';



CREATE TABLE IF NOT EXISTS referencia.tipo_votacao_legislativa (
  tipo_votacao_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  nominal boolean
);

COMMENT ON TABLE referencia.tipo_votacao_legislativa IS 'Tipos de votação da Câmara.';



CREATE TABLE IF NOT EXISTS referencia.papel_municipio_consorcio (
  papel_consorcio_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  descricao text
);

COMMENT ON TABLE referencia.papel_municipio_consorcio IS 'Papéis de município em consórcio público.';



CREATE TABLE IF NOT EXISTS municipal.perfil_municipio (
  perfil_municipio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL UNIQUE REFERENCES referencia.municipio(municipio_id),
  url_prefeitura text,
  email_institucional text,
  telefone_institucional varchar(80),
  endereco_sede text,
  horario_atendimento varchar(200),
  data_instalacao date,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE municipal.perfil_municipio IS 'Perfil institucional local.';



CREATE TABLE IF NOT EXISTS municipal.estrutura_administrativa (
  estrutura_administrativa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  nome varchar(250) NOT NULL,
  inicio_vigencia date NOT NULL,
  fim_vigencia date,
  norma_municipal_id bigint,
  organograma_uri text,
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(municipio_id,inicio_vigencia,nome)
);

COMMENT ON TABLE municipal.estrutura_administrativa IS 'Versões da estrutura administrativa municipal.';



CREATE TABLE IF NOT EXISTS municipal.unidade_administrativa (
  unidade_administrativa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  estrutura_administrativa_id bigint NOT NULL REFERENCES municipal.estrutura_administrativa(estrutura_administrativa_id),
  unidade_pai_id bigint REFERENCES municipal.unidade_administrativa(unidade_administrativa_id),
  tipo_unidade_id smallint REFERENCES referencia.tipo_unidade_administrativa_municipal(tipo_unidade_id),
  orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
  codigo_origem varchar(100),
  nome varchar(300) NOT NULL,
  sigla varchar(80),
  inicio_vigencia date,
  fim_vigencia date,
  ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE municipal.unidade_administrativa IS 'Secretarias e unidades locais com hierarquia e vigência.';



CREATE TABLE IF NOT EXISTS municipal.gestor_unidade (
  gestor_unidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  unidade_administrativa_id bigint NOT NULL REFERENCES municipal.unidade_administrativa(unidade_administrativa_id),
  nome_publico varchar(300) NOT NULL,
  cargo varchar(200),
  inicio_gestao date,
  fim_gestao date,
  fonte_municipal_id bigint REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  dados_adicionais jsonb NOT NULL DEFAULT '{}'::jsonb
);

COMMENT ON TABLE municipal.gestor_unidade IS 'Histórico público de responsáveis por unidades.';



CREATE TABLE IF NOT EXISTS municipal.mandato_executivo (
  mandato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  inicio_mandato date NOT NULL,
  fim_mandato date NOT NULL,
  prefeito_nome varchar(300) NOT NULL,
  vice_prefeito_nome varchar(300),
  situacao varchar(80),
  fonte_municipal_id bigint REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  UNIQUE(municipio_id,inicio_mandato)
);

COMMENT ON TABLE municipal.mandato_executivo IS 'Mandatos do Executivo municipal.';



CREATE TABLE IF NOT EXISTS municipal.quadro_pessoal_resumo (
  quadro_pessoal_resumo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  unidade_administrativa_id bigint REFERENCES municipal.unidade_administrativa(unidade_administrativa_id),
  tipo_vinculo varchar(100),
  quantidade bigint,
  custo_bruto numeric(30,4),
  custo_encargos numeric(30,4),
  fonte_municipal_id bigint REFERENCES catalogo.fonte_municipal(fonte_municipal_id),
  UNIQUE(municipio_id,periodo_id,unidade_administrativa_id,tipo_vinculo)
);

COMMENT ON TABLE municipal.quadro_pessoal_resumo IS 'Quadro agregado de pessoal, sem expor dados desnecessários.';



CREATE TABLE IF NOT EXISTS municipal.concurso_publico (
  concurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  municipio_id bigint NOT NULL REFERENCES referencia.municipio(municipio_id),
  numero_edital varchar(100),
  ano smallint,
  orgao_id bigint REFERENCES nucleo.orgao_publico(orgao_id),
  cargo varchar(220),
  vagas integer,
  cadastro_reserva integer,
  data_publicacao date,
  status varchar(80),
  documento_id bigint,
