INSERT INTO catalogo.fonte_municipal(municipio_id,tipo_fonte_municipal_id,nome,status,autoridade_fonte,inicio_vigencia)
SELECT m.municipio_id,t.tipo_fonte_municipal_id,m.nome || ' - ' || t.nome,'a_descobrir','primaria',DATE '2025-01-01'
FROM referencia.municipio m JOIN referencia.unidade_federativa uf ON uf.uf_id=m.uf_id CROSS JOIN catalogo.tipo_fonte_municipal t
WHERE uf.sigla='MT' ON CONFLICT DO NOTHING;



