-- ============================================================================
-- PLATAFORMA ITMT - FASE 4 REFINADA R1
-- Dados privados, institucionais e conveniados
-- PostgreSQL 16+ / PostGIS 3+
-- Data: 2026-08-28
-- ============================================================================

CREATE SCHEMA IF NOT EXISTS parceria;

-- Refinamento regressivo de identificadores cadastrais.

ALTER TABLE IF EXISTS nucleo.instituicao ALTER COLUMN cnpj TYPE varchar(24);

ALTER TABLE IF EXISTS nucleo.empresa ALTER COLUMN cnpj_basico TYPE varchar(24);

ALTER TABLE IF EXISTS dw.dim_empresa ALTER COLUMN cnpj_basico TYPE varchar(24);

CREATE TABLE IF NOT EXISTS catalogo.tipo_parceiro_dado (
  tipo_parceiro_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  descricao text,
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.tipo_parceiro_dado IS 'Tipos de parceiro de dados.';

CREATE TABLE IF NOT EXISTS catalogo.classificacao_acesso_parceiro (
  classificacao_acesso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  permite_uso_interno boolean NOT NULL DEFAULT true,
  permite_publicacao boolean NOT NULL DEFAULT false,
  permite_redistribuicao boolean NOT NULL DEFAULT false,
  permite_treinamento_ia boolean NOT NULL DEFAULT false,
  descricao text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.classificacao_acesso_parceiro IS 'Classificação declarativa de acesso e uso de dados conveniados.';

CREATE TABLE IF NOT EXISTS catalogo.finalidade_uso_dado (
  finalidade_uso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  descricao text,
  categoria varchar(100),
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.finalidade_uso_dado IS 'Finalidades autorizáveis para uso de dados parceiros.';

CREATE TABLE IF NOT EXISTS catalogo.nivel_granularidade_publicavel (
  nivel_granularidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  ordem smallint NOT NULL,
  descricao text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.nivel_granularidade_publicavel IS 'Níveis de granularidade que podem ser publicados.';

CREATE TABLE IF NOT EXISTS catalogo.modelo_licenciamento_parceria (
  modelo_licenciamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(250) NOT NULL,
  permite_derivados boolean,
  exige_atribuicao boolean,
  exige_aprovacao_publicacao boolean,
  descricao text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.modelo_licenciamento_parceria IS 'Modelos de licenciamento aplicáveis a dados parceiros.';

CREATE TABLE IF NOT EXISTS catalogo.regra_precedencia_fonte (
  regra_precedencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  dominio varchar(160) NOT NULL,
  tipo_medida varchar(160),
  fonte_preferencial_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  fonte_secundaria_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  criterio text NOT NULL,
  valido_desde date,
  valido_ate date,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.regra_precedencia_fonte IS 'Regras para escolher/explicar fontes públicas e privadas concorrentes.';

CREATE TABLE IF NOT EXISTS catalogo.politica_derivacao_dado (
  politica_derivacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  nome varchar(250) NOT NULL,
  classificacao_acesso_id bigint REFERENCES catalogo.classificacao_acesso_parceiro(classificacao_acesso_id),
  permite_agregacao boolean NOT NULL DEFAULT true,
  permite_modelagem boolean NOT NULL DEFAULT true,
  permite_benchmark boolean NOT NULL DEFAULT false,
  permite_embedding boolean NOT NULL DEFAULT false,
  permite_cache boolean NOT NULL DEFAULT false,
  regra text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.politica_derivacao_dado IS 'Política sobre produtos derivados de dados parceiros.';

CREATE TABLE IF NOT EXISTS catalogo.dependencia_dado_conveniado (
  dependencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  conjunto_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
  obrigatorio boolean NOT NULL DEFAULT true,
  alternativa_publica_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
  descricao text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.dependencia_dado_conveniado IS 'Dependências de indicadores em dados conveniados e alternativas públicas.';

CREATE TABLE IF NOT EXISTS catalogo.registro_fonte_parceira (
  registro_fonte_parceira_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  tipo_parceiro_id bigint REFERENCES catalogo.tipo_parceiro_dado(tipo_parceiro_id),
  status varchar(40) NOT NULL DEFAULT 'candidato',
  prioridade varchar(10),
  observacoes text,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.registro_fonte_parceira IS 'Registro da fonte parceira dentro da Fase 4.';

CREATE TABLE IF NOT EXISTS catalogo.campo_publicacao_parceiro (
  campo_publicacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campo_fonte_id bigint REFERENCES catalogo.campo_fonte(campo_fonte_id),
