-- ITMT FASE 5 REFINADA R1 - DADOS PRÓPRIOS

CREATE SCHEMA IF NOT EXISTS producao;

CREATE SCHEMA IF NOT EXISTS levantamento;

CREATE SCHEMA IF NOT EXISTS midia;

CREATE SCHEMA IF NOT EXISTS campo;

CREATE SCHEMA IF NOT EXISTS pesquisa;

CREATE TABLE IF NOT EXISTS referencia.tipo_origem_dado (
  tipo_origem_dado_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(60) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.tipo_origem_dado IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.sistema_referencia_geodesica (
  sistema_referencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo_epsg integer,
  nome varchar(250) NOT NULL,
  datum_horizontal varchar(180),
  wkt text,
  vigente boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE referencia.sistema_referencia_geodesica IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.datum_vertical (
  datum_vertical_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) UNIQUE,
  nome varchar(250) NOT NULL,
  descricao text,
  epoca_referencia numeric(10,4),
  vigente boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE referencia.datum_vertical IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.modelo_geoide (
  modelo_geoide_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) UNIQUE,
  nome varchar(250) NOT NULL,
  versao varchar(80),
  datum_vertical_id bigint REFERENCES referencia.datum_vertical(datum_vertical_id),
  uri_grade text,
  checksum_sha256 char(64),
  vigente boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE referencia.modelo_geoide IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.tipo_produto_geoespacial (
  tipo_produto_geoespacial_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  categoria varchar(100),
  descricao text
);
COMMENT ON TABLE referencia.tipo_produto_geoespacial IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.tipo_consentimento (
  tipo_consentimento_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.tipo_consentimento IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.status_consentimento (
  status_consentimento_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(120) NOT NULL,
  terminal boolean NOT NULL DEFAULT false
);
COMMENT ON TABLE referencia.status_consentimento IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.tipo_qualidade_geoespacial (
  tipo_qualidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  unidade_padrao varchar(80),
  descricao text
);
COMMENT ON TABLE referencia.tipo_qualidade_geoespacial IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.tipo_deteccao_privacidade (
  tipo_deteccao_privacidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  sensibilidade_padrao varchar(40),
  descricao text
);
COMMENT ON TABLE referencia.tipo_deteccao_privacidade IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS referencia.tipo_nao_resposta (
  tipo_nao_resposta_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  categoria varchar(80),
  descricao text
);
COMMENT ON TABLE referencia.tipo_nao_resposta IS 'Referência transversal da Fase 5.';


CREATE TABLE IF NOT EXISTS catalogo.padrao_tecnico_fase5 (
  padrao_tecnico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  versao varchar(80),
  categoria varchar(100) NOT NULL,
  url_referencia text,
  obrigatorio boolean NOT NULL DEFAULT false,
  observacoes text,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.padrao_tecnico_fase5 IS 'Padrões técnicos adotados na produção própria.';


CREATE TABLE IF NOT EXISTS catalogo.perfil_produto_proprio (
  perfil_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  tipo_produto_geoespacial_id smallint REFERENCES referencia.tipo_produto_geoespacial(tipo_produto_geoespacial_id),
  formato_preferencial varchar(80),
  requisitos jsonb NOT NULL DEFAULT '{}'::jsonb,
  criterios_aceite jsonb NOT NULL DEFAULT '{}'::jsonb,
  politica_publicacao jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.perfil_produto_proprio IS 'Perfil técnico de produto.';


CREATE TABLE IF NOT EXISTS catalogo.regra_derivacao_produto (
  regra_derivacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  perfil_origem_id bigint REFERENCES catalogo.perfil_produto_proprio(perfil_produto_id),
  perfil_destino_id bigint REFERENCES catalogo.perfil_produto_proprio(perfil_produto_id),
  nome varchar(300) NOT NULL,
  processo text NOT NULL,
  parametros_padrao jsonb NOT NULL DEFAULT '{}'::jsonb,
  exige_validacao_humana boolean NOT NULL DEFAULT true,
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.regra_derivacao_produto IS 'Derivação reproduzível entre produtos.';


CREATE TABLE IF NOT EXISTS catalogo.criterio_aceite_produto (
  criterio_aceite_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  perfil_produto_id bigint REFERENCES catalogo.perfil_produto_proprio(perfil_produto_id),
  codigo varchar(120) NOT NULL,
  nome varchar(250) NOT NULL,
  expressao_regra text,
  severidade varchar(30),
  obrigatorio boolean NOT NULL DEFAULT true,
  UNIQUE(perfil_produto_id,codigo)
);
COMMENT ON TABLE catalogo.criterio_aceite_produto IS 'Critérios objetivos de aceite.';


CREATE TABLE IF NOT EXISTS producao.programa_producao (
  programa_producao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  descricao text,
  tipo varchar(100) NOT NULL,
  inicio date,
  fim_previsto date,
  fim_real date,
  responsavel_entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  status varchar(50) NOT NULL DEFAULT 'planejado',
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE producao.programa_producao IS 'Programa de produção própria.';


CREATE TABLE IF NOT EXISTS producao.campanha_producao (
  campanha_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  programa_producao_id bigint NOT NULL REFERENCES producao.programa_producao(programa_producao_id),
  codigo varchar(120) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  inicio_previsto timestamptz,
  fim_previsto timestamptz,
  inicio_real timestamptz,
  fim_real timestamptz,
  status varchar(50) NOT NULL DEFAULT 'planejada',
  objetivo text,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE producao.campanha_producao IS 'Campanha temporal de coleta.';


CREATE TABLE IF NOT EXISTS producao.equipamento (
  equipamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo_patrimonio varchar(100) UNIQUE,
  tipo varchar(100) NOT NULL,
  fabricante varchar(160),
  modelo varchar(160),
  numero_serie varchar(180),
  firmware varchar(100),
  status varchar(50),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE producao.equipamento IS 'Equipamento de campo.';


CREATE TABLE IF NOT EXISTS producao.sensor (
  sensor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tipo varchar(100) NOT NULL,
  fabricante varchar(160),
  modelo varchar(160),
  numero_serie varchar(180),
  resolucao varchar(120),
  distancia_focal_mm numeric(12,6),
  tamanho_pixel_um numeric(12,6),
  espectro varchar(120),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE producao.sensor IS 'Sensor de captura.';


CREATE TABLE IF NOT EXISTS producao.sessao_captura (
  sessao_captura_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint NOT NULL REFERENCES producao.campanha_producao(campanha_id),
  tipo varchar(80) NOT NULL,
  inicio timestamptz NOT NULL,
  fim timestamptz,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  geom geometry(Geometry,4674),
  condicoes jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(50),
  hash_manifesto char(64)
);
COMMENT ON TABLE producao.sessao_captura IS 'Sessão atômica de captura.';


CREATE TABLE IF NOT EXISTS producao.artefato_bruto (
  artefato_bruto_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sessao_captura_id bigint REFERENCES producao.sessao_captura(sessao_captura_id),
  tipo varchar(100) NOT NULL,
  nome_arquivo varchar(700),
  uri_objeto text NOT NULL,
  mime_type varchar(160),
  tamanho_bytes bigint,
  checksum_sha256 char(64) NOT NULL,
  capturado_em timestamptz,
  geom geometry(Geometry,4674),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  preservacao_permanente boolean NOT NULL DEFAULT false,
  UNIQUE(uri_objeto,checksum_sha256)
);
COMMENT ON TABLE producao.artefato_bruto IS 'Artefato original imutável.';


CREATE TABLE IF NOT EXISTS producao.artefato_derivado (
  artefato_derivado_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo varchar(100) NOT NULL,
  nome varchar(600),
  uri_objeto text NOT NULL,
  mime_type varchar(160),
  tamanho_bytes bigint,
  checksum_sha256 char(64) NOT NULL,
  gerado_em timestamptz NOT NULL DEFAULT now(),
  geom geometry(Geometry,4674),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(uri_objeto,checksum_sha256)
);
COMMENT ON TABLE producao.artefato_derivado IS 'Artefato derivado.';


CREATE TABLE IF NOT EXISTS producao.produto_proprio (
  produto_proprio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint REFERENCES producao.campanha_producao(campanha_id),
  perfil_produto_id bigint REFERENCES catalogo.perfil_produto_proprio(perfil_produto_id),
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(500) NOT NULL,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  tipo varchar(100) NOT NULL,
  status varchar(50) NOT NULL DEFAULT 'em_producao',
  nivel_acesso varchar(40) NOT NULL DEFAULT 'publico',
  descricao text,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE producao.produto_proprio IS 'Produto lógico próprio.';


CREATE TABLE IF NOT EXISTS producao.versao_produto_proprio (
  versao_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_proprio_id bigint NOT NULL REFERENCES producao.produto_proprio(produto_proprio_id),
  versao varchar(100) NOT NULL,
  artefato_derivado_id uuid REFERENCES producao.artefato_derivado(artefato_derivado_id),
  raster_id bigint REFERENCES geoespacial.raster_catalogo(raster_id),
  nuvem_pontos_id bigint REFERENCES geoespacial.nuvem_pontos_catalogo(nuvem_pontos_id),
  valido_desde timestamptz,
  valido_ate timestamptz,
  publicado_em timestamptz,
  status_qualidade varchar(50),
  checksum_manifesto char(64),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(produto_proprio_id,versao)
);
COMMENT ON TABLE producao.versao_produto_proprio IS 'Versão física do produto.';


CREATE TABLE IF NOT EXISTS producao.cadeia_custodia (
  cadeia_custodia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  artefato_bruto_id uuid REFERENCES producao.artefato_bruto(artefato_bruto_id),
  artefato_derivado_id uuid REFERENCES producao.artefato_derivado(artefato_derivado_id),
  evento varchar(100) NOT NULL,
  ocorrido_em timestamptz NOT NULL DEFAULT now(),
  ator_entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  origem_uri text,
  destino_uri text,
  checksum_antes char(64),
  checksum_depois char(64),
  assinatura_digital text,
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE producao.cadeia_custodia IS 'Cadeia de custódia auditável.';


CREATE TABLE IF NOT EXISTS levantamento.marco_geodesico (
  marco_geodesico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  codigo varchar(120) NOT NULL UNIQUE,
  geom geometry(PointZ,4674) NOT NULL,
  altura_elipsoidal_m numeric(20,8),
  altura_ortometrica_m numeric(20,8),
  sistema_referencia_id bigint REFERENCES referencia.sistema_referencia_geodesica(sistema_referencia_id),
  datum_vertical_id bigint REFERENCES referencia.datum_vertical(datum_vertical_id),
  modelo_geoide_id bigint REFERENCES referencia.modelo_geoide(modelo_geoide_id),
  estabilidade varchar(80),
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE levantamento.marco_geodesico IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.ponto_controle (
  ponto_controle_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint REFERENCES producao.campanha_producao(campanha_id),
  codigo varchar(120) NOT NULL,
  tipo varchar(50) NOT NULL,
  geom geometry(PointZ,4674) NOT NULL,
  sigma_x_m numeric(20,8),
  sigma_y_m numeric(20,8),
  sigma_z_m numeric(20,8),
  usado_ajuste boolean NOT NULL DEFAULT true,
  UNIQUE(campanha_id,codigo)
);
COMMENT ON TABLE levantamento.ponto_controle IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.missao_voo (
  missao_voo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint NOT NULL REFERENCES producao.campanha_producao(campanha_id),
  sessao_captura_id bigint REFERENCES producao.sessao_captura(sessao_captura_id),
  codigo varchar(120) NOT NULL UNIQUE,
  inicio timestamptz,
  fim timestamptz,
  area_planejada geometry(MultiPolygon,4674),
  trajetoria geometry(MultiLineStringZ,4674),
  altura_agl_m numeric(12,4),
  status varchar(50),
  condicoes_meteorologicas jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE levantamento.missao_voo IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.imagem_aerea (
  imagem_aerea_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  missao_voo_id bigint NOT NULL REFERENCES levantamento.missao_voo(missao_voo_id),
  artefato_bruto_id uuid NOT NULL REFERENCES producao.artefato_bruto(artefato_bruto_id),
  sensor_id bigint REFERENCES producao.sensor(sensor_id),
  capturada_em timestamptz,
  geom geometry(PointZ,4674),
  yaw numeric(12,6),
  pitch numeric(12,6),
  roll numeric(12,6),
  qualidade varchar(50)
);
COMMENT ON TABLE levantamento.imagem_aerea IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.processamento_fotogrametrico (
  processamento_fotogrametrico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint REFERENCES producao.campanha_producao(campanha_id),
  software varchar(180) NOT NULL,
  versao varchar(100),
  inicio timestamptz,
  fim timestamptz,
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  hardware jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(50),
  log_uri text,
  hash_configuracao char(64)
);
COMMENT ON TABLE levantamento.processamento_fotogrametrico IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.ortomosaico (
  ortomosaico_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_produto_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  raster_id bigint NOT NULL REFERENCES geoespacial.raster_catalogo(raster_id),
  processamento_fotogrametrico_id bigint REFERENCES levantamento.processamento_fotogrametrico(processamento_fotogrametrico_id),
  gsd_cm numeric(12,6),
  area_km2 numeric(24,8),
  cobertura_nuvem_percentual numeric(8,4),
  radiometria_status varchar(60)
);
COMMENT ON TABLE levantamento.ortomosaico IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.modelo_elevacao (
  modelo_elevacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_produto_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  raster_id bigint NOT NULL REFERENCES geoespacial.raster_catalogo(raster_id),
  tipo varchar(30) NOT NULL,
  resolucao_m numeric(12,6),
  datum_vertical_id bigint REFERENCES referencia.datum_vertical(datum_vertical_id),
  modelo_geoide_id bigint REFERENCES referencia.modelo_geoide(modelo_geoide_id)
);
COMMENT ON TABLE levantamento.modelo_elevacao IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.nuvem_pontos (
  nuvem_pontos_f5_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_produto_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  nuvem_pontos_id bigint NOT NULL REFERENCES geoespacial.nuvem_pontos_catalogo(nuvem_pontos_id),
  origem varchar(80),
  densidade_media numeric(20,8),
  espacamento_m numeric(20,8),
  classificada boolean,
  formato_logico varchar(50)
);
COMMENT ON TABLE levantamento.nuvem_pontos IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.acuracia_posicional (
  acuracia_posicional_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_produto_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  tipo_qualidade_id smallint REFERENCES referencia.tipo_qualidade_geoespacial(tipo_qualidade_id),
  metodo varchar(160),
  nivel_confianca numeric(8,4),
  rmse_m numeric(20,10),
  erro_max_m numeric(20,10),
  percentil95_m numeric(20,10),
  amostra_pontos integer,
  resultado_classe varchar(120),
  aprovado boolean
);
COMMENT ON TABLE levantamento.acuracia_posicional IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.comparacao_temporal (
  comparacao_temporal_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_anterior_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  produto_posterior_id bigint NOT NULL REFERENCES producao.versao_produto_proprio(versao_produto_id),
  metodo varchar(180) NOT NULL,
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  executado_em timestamptz,
  modelo_ia varchar(180),
  versao_modelo varchar(100)
);
COMMENT ON TABLE levantamento.comparacao_temporal IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS levantamento.mudanca_detectada (
  mudanca_detectada_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  comparacao_temporal_id bigint NOT NULL REFERENCES levantamento.comparacao_temporal(comparacao_temporal_id),
  tipo varchar(120),
  geom geometry(Geometry,4674) NOT NULL,
  magnitude numeric(30,10),
  unidade varchar(80),
  confianca numeric(8,6),
  status_validacao varchar(50) NOT NULL DEFAULT 'pendente',
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE levantamento.mudanca_detectada IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS midia.arquivo_midia (
  arquivo_midia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  sessao_captura_id bigint REFERENCES producao.sessao_captura(sessao_captura_id),
  artefato_bruto_id uuid REFERENCES producao.artefato_bruto(artefato_bruto_id),
  artefato_derivado_id uuid REFERENCES producao.artefato_derivado(artefato_derivado_id),
  tipo varchar(50) NOT NULL,
  duracao_seg numeric(20,6),
  largura_px integer,
  altura_px integer,
  capturado_em timestamptz,
  geom geometry(Point,4674),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE midia.arquivo_midia IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS midia.rota_360 (
  rota_360_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  campanha_id bigint REFERENCES producao.campanha_producao(campanha_id),
  codigo varchar(120) NOT NULL UNIQUE,
  nome varchar(300),
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  inicio timestamptz,
  fim timestamptz,
  trajeto geometry(MultiLineString,4674),
  distancia_km numeric(20,6),
  status varchar(50)
);
COMMENT ON TABLE midia.rota_360 IS 'Tabela crítica refinada da Fase 5.';


CREATE TABLE IF NOT EXISTS midia.panorama_360 (
  panorama_360_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  rota_360_id bigint NOT NULL REFERENCES midia.rota_360(rota_360_id),
  arquivo_midia_id bigint REFERENCES midia.arquivo_midia(arquivo_midia_id),
  sequencia bigint,
  capturado_em timestamptz,
  geom geometry(PointZ,4674) NOT NULL,
  rumo_graus numeric(12,6),
  qualidade numeric(8,6),
  publicavel boolean NOT NULL DEFAULT false
);
