  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  campanha_id bigint REFERENCES producao.campanha_producao(campanha_id),
  codigo varchar(180),
  nome varchar(500),
  inicio timestamptz,
  fim timestamptz,
  status varchar(60),
