-- ITMT CORE R2 - Revisão Consolidada Fases 1-5
-- Evolução aditiva e retrocompatível sobre o R1.


CREATE TABLE IF NOT EXISTS referencia.tipo_medida (
  tipo_medida_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  categoria varchar(80),
  aditividade_padrao varchar(40),
  descricao text
);
COMMENT ON TABLE referencia.tipo_medida IS 'Semântica da medida: contagem, taxa, razão, índice, estoque, fluxo, média etc.';


CREATE TABLE IF NOT EXISTS referencia.natureza_valor (
  natureza_valor_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  observado boolean NOT NULL DEFAULT false,
  estimado boolean NOT NULL DEFAULT false,
  descricao text
);
COMMENT ON TABLE referencia.natureza_valor IS 'Distingue observado, declarado, estimado, modelado, projetado, imputado e derivado.';


CREATE TABLE IF NOT EXISTS referencia.tipo_incerteza (
  tipo_incerteza_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.tipo_incerteza IS 'Tipos de incerteza estatística, amostral, instrumental, espacial e de modelo.';


CREATE TABLE IF NOT EXISTS referencia.papel_tempo (
  papel_tempo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.papel_tempo IS 'Papéis temporais de uma observação: evento, competência, referência, publicação, coleta e ingestão.';


CREATE TABLE IF NOT EXISTS referencia.granularidade_analitica (
  granularidade_analitica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(200) NOT NULL,
  eixo varchar(60) NOT NULL,
  ordem smallint,
  descricao text
);
COMMENT ON TABLE referencia.granularidade_analitica IS 'Granularidade semântica comparável em território, tempo, entidade e dimensão.';


CREATE TABLE IF NOT EXISTS referencia.tipo_evidencia (
  tipo_evidencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(220) NOT NULL,
  forca_padrao smallint,
  descricao text
);
COMMENT ON TABLE referencia.tipo_evidencia IS 'Classes de evidência: registro oficial, documento, medição, imagem, estimativa, declaração etc.';


CREATE TABLE IF NOT EXISTS referencia.tipo_relacao_semantica (
  tipo_relacao_semantica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(220) NOT NULL,
  direcional boolean NOT NULL DEFAULT true,
  transitiva boolean NOT NULL DEFAULT false,
  descricao text
);
COMMENT ON TABLE referencia.tipo_relacao_semantica IS 'Relações da ontologia e do grafo semântico.';


CREATE TABLE IF NOT EXISTS referencia.tipo_decisao_politica (
  tipo_decisao_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  permite boolean NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.tipo_decisao_politica IS 'Decisões uniformes do motor de políticas: permitir, negar, agregar, mascarar, exigir aprovação.';


CREATE TABLE IF NOT EXISTS referencia.tipo_transformacao (
  tipo_transformacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(220) NOT NULL,
  deterministica boolean,
  descricao text
);
COMMENT ON TABLE referencia.tipo_transformacao IS 'Tipos de transformação de dados e modelos.';


CREATE TABLE IF NOT EXISTS referencia.nivel_evidencia (
  nivel_evidencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  ordem smallint NOT NULL,
  descricao text
);
COMMENT ON TABLE referencia.nivel_evidencia IS 'Nível de evidência utilizado na resposta da Xingú.';


CREATE TABLE IF NOT EXISTS referencia.versao_territorio (
  versao_territorio_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
  versao varchar(80) NOT NULL,
  valido_desde date NOT NULL,
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  geometria geometry(MultiPolygon,4674),
  centroide geometry(Point,4674),
  area_km2 numeric(30,10),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  checksum_geometria char(64),
  motivo_mudanca text,
  UNIQUE(territorio_id,versao),
  CHECK(valido_ate>=valido_desde)
);
COMMENT ON TABLE referencia.versao_territorio IS 'Versão temporal da geometria e atributos territoriais; a identidade territorial permanece estável.';


CREATE TABLE IF NOT EXISTS referencia.territorio_hierarquia_versao (
  territorio_hierarquia_versao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  territorio_pai_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
  territorio_filho_id bigint NOT NULL REFERENCES referencia.territorio(territorio_id),
  tipo_relacao varchar(80) NOT NULL,
  valido_desde date NOT NULL,
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  UNIQUE(territorio_pai_id,territorio_filho_id,tipo_relacao,valido_desde),
  CHECK(territorio_pai_id<>territorio_filho_id),
  CHECK(valido_ate>=valido_desde)
);
COMMENT ON TABLE referencia.territorio_hierarquia_versao IS 'Histórico de pertencimento territorial, incluindo mudanças de região/consórcio/limites.';


CREATE TABLE IF NOT EXISTS nucleo.versao_entidade (
  versao_entidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entidade_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id),
  versao varchar(80) NOT NULL,
  valido_desde date NOT NULL,
  valido_ate date NOT NULL DEFAULT DATE '9999-12-31',
  nome_exibicao varchar(500),
  territorio_principal_id bigint REFERENCES referencia.territorio(territorio_id),
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  hash_atributos char(64),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  UNIQUE(entidade_id,versao),
  CHECK(valido_ate>=valido_desde)
);
COMMENT ON TABLE nucleo.versao_entidade IS 'SCD temporal de atributos da entidade mestre.';


CREATE TABLE IF NOT EXISTS nucleo.evento_identidade_entidade (
  evento_identidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  entidade_origem_id bigint NOT NULL REFERENCES nucleo.entidade(entidade_id),
  entidade_destino_id bigint REFERENCES nucleo.entidade(entidade_id),
  tipo varchar(50) NOT NULL,
  ocorrido_em timestamptz NOT NULL,
  efetivo_desde date,
  motivo text,
  decisao_correspondencia_id bigint,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK(entidade_destino_id IS NULL OR entidade_origem_id<>entidade_destino_id)
);
COMMENT ON TABLE nucleo.evento_identidade_entidade IS 'Histórico de fusão, cisão, substituição, desativação e correção de identidades.';


CREATE TABLE IF NOT EXISTS catalogo.produto_dado (
  produto_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(140) NOT NULL UNIQUE,
  nome varchar(350) NOT NULL,
  descricao text,
  dominio varchar(120) NOT NULL,
  camada varchar(60) NOT NULL,
  proprietario_entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  responsavel_tecnico varchar(250),
  criticidade varchar(30) NOT NULL DEFAULT 'media',
  publicavel boolean NOT NULL DEFAULT true,
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE catalogo.produto_dado IS 'Unidade governada de entrega de dados: bruto, padronizado, curado, DW, semântico ou produto próprio.';


CREATE TABLE IF NOT EXISTS catalogo.versao_produto_dado (
  versao_produto_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  versao varchar(100) NOT NULL,
  schema_hash char(64),
  conteudo_hash char(64),
  valido_desde timestamptz,
  valido_ate timestamptz,
  publicado_em timestamptz,
  status varchar(50) NOT NULL DEFAULT 'rascunho',
  compatibilidade varchar(30),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(produto_dado_id,versao)
);
COMMENT ON TABLE catalogo.versao_produto_dado IS 'Versão de Data Product com contrato e compatibilidade explícitos.';


CREATE TABLE IF NOT EXISTS catalogo.produto_dado_fonte (
  produto_dado_fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  conjunto_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
  papel varchar(40) NOT NULL DEFAULT 'principal',
  prioridade smallint NOT NULL DEFAULT 1,
  valido_desde date,
  valido_ate date,
  UNIQUE(produto_dado_id,fonte_id,conjunto_id,papel,valido_desde)
);
COMMENT ON TABLE catalogo.produto_dado_fonte IS 'Fontes que alimentam cada Data Product.';


CREATE TABLE IF NOT EXISTS catalogo.dependencia_produto_dado (
  dependencia_produto_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_origem_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  produto_destino_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  tipo_dependencia varchar(60) NOT NULL,
  obrigatoria boolean NOT NULL DEFAULT true,
  descricao text,
  CHECK(produto_origem_id<>produto_destino_id),
  UNIQUE(produto_origem_id,produto_destino_id,tipo_dependencia)
);
COMMENT ON TABLE catalogo.dependencia_produto_dado IS 'DAG de dependências entre produtos de dados.';


CREATE TABLE IF NOT EXISTS catalogo.mapa_tabela_produto (
  mapa_tabela_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  schema_tabela varchar(120) NOT NULL,
  nome_tabela varchar(180) NOT NULL,
  papel varchar(60) NOT NULL,
  chave_logica varchar(300),
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(produto_dado_id,schema_tabela,nome_tabela,papel)
);
COMMENT ON TABLE catalogo.mapa_tabela_produto IS 'Relaciona Data Products às tabelas físicas/lógicas sem acoplar a semântica à tabela.';


CREATE TABLE IF NOT EXISTS catalogo.contrato_dado_core (
  contrato_dado_core_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  tipo varchar(60) NOT NULL,
  proprietario varchar(250),
  status varchar(50) NOT NULL DEFAULT 'ativo',
  valido_desde date,
  valido_ate date,
  documento_uri text,
  observacoes text
);
COMMENT ON TABLE catalogo.contrato_dado_core IS 'Contrato técnico universal do Data Product; complementa contratos jurídicos de parceria.';


CREATE TABLE IF NOT EXISTS catalogo.versao_contrato_dado_core (
  versao_contrato_core_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  contrato_dado_core_id bigint NOT NULL REFERENCES catalogo.contrato_dado_core(contrato_dado_core_id),
  versao varchar(80) NOT NULL,
  schema_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  schema_hash char(64),
  compatibilidade_retroativa boolean,
  compatibilidade_futura boolean,
  breaking_change boolean NOT NULL DEFAULT false,
  publicado_em timestamptz,
  valido_desde timestamptz,
  valido_ate timestamptz,
  UNIQUE(contrato_dado_core_id,versao)
);
COMMENT ON TABLE catalogo.versao_contrato_dado_core IS 'Versionamento formal do contrato de dados.';


CREATE TABLE IF NOT EXISTS catalogo.contrato_campo_core (
  contrato_campo_core_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_contrato_core_id bigint NOT NULL REFERENCES catalogo.versao_contrato_dado_core(versao_contrato_core_id),
  caminho varchar(500) NOT NULL,
  nome_logico varchar(250),
  tipo_dado varchar(120) NOT NULL,
  obrigatorio boolean NOT NULL DEFAULT false,
  chave_natural boolean NOT NULL DEFAULT false,
  sensivel boolean NOT NULL DEFAULT false,
  unidade_id bigint REFERENCES referencia.unidade_medida(unidade_id),
  classificacao_id bigint REFERENCES referencia.sistema_classificacao(sistema_classificacao_id),
  regra_validacao text,
  descricao text,
  UNIQUE(versao_contrato_core_id,caminho)
);
COMMENT ON TABLE catalogo.contrato_campo_core IS 'Contrato campo-a-campo comum a APIs, arquivos, parceiros e dados próprios.';


CREATE TABLE IF NOT EXISTS catalogo.regra_compatibilidade_schema (
  regra_compatibilidade_schema_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  contrato_dado_core_id bigint NOT NULL REFERENCES catalogo.contrato_dado_core(contrato_dado_core_id),
  tipo_mudanca varchar(100) NOT NULL,
  permitida boolean NOT NULL,
  acao varchar(100) NOT NULL,
  descricao text
);
COMMENT ON TABLE catalogo.regra_compatibilidade_schema IS 'Políticas de schema evolution e breaking changes.';


CREATE TABLE IF NOT EXISTS catalogo.evento_schema_core (
  evento_schema_core_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  versao_anterior_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  versao_nova_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  detectado_em timestamptz NOT NULL DEFAULT now(),
  tipo varchar(100) NOT NULL,
  breaking_change boolean NOT NULL DEFAULT false,
  diferencas jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(50) NOT NULL DEFAULT 'aberto'
);
COMMENT ON TABLE catalogo.evento_schema_core IS 'Mudanças de schema observadas em qualquer fase.';


CREATE TABLE IF NOT EXISTS catalogo.politica_frescor_produto (
  politica_frescor_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  frequencia_esperada interval,
  atraso_alerta interval,
  atraso_critico interval,
  campo_referencia varchar(180),
  regra text,
  valido_desde date,
  valido_ate date
);
COMMENT ON TABLE catalogo.politica_frescor_produto IS 'Política de atualização/frescor por produto.';


CREATE TABLE IF NOT EXISTS catalogo.sla_produto_dado (
  sla_produto_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  metrica varchar(120) NOT NULL,
  alvo numeric(30,10),
  unidade varchar(80),
  janela varchar(80),
  severidade_falha varchar(30),
  valido_desde date,
  valido_ate date
);
COMMENT ON TABLE catalogo.sla_produto_dado IS 'SLA técnico comum a fontes públicas, privadas, municipais e próprias.';


CREATE TABLE IF NOT EXISTS catalogo.perfil_qualidade_produto (
  perfil_qualidade_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  codigo varchar(120) NOT NULL,
  nome varchar(250) NOT NULL,
  versao varchar(80) NOT NULL,
  limiar_aprovacao numeric(8,6),
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(produto_dado_id,codigo,versao)
);
COMMENT ON TABLE catalogo.perfil_qualidade_produto IS 'Perfil de qualidade esperado por Data Product.';


CREATE TABLE IF NOT EXISTS catalogo.perfil_qualidade_produto_regra (
  perfil_qualidade_produto_regra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  perfil_qualidade_produto_id bigint NOT NULL REFERENCES catalogo.perfil_qualidade_produto(perfil_qualidade_produto_id),
  regra_qualidade_id bigint REFERENCES controle.regra_qualidade(regra_id),
  codigo varchar(140) NOT NULL,
  dimensao_qualidade varchar(80),
  peso numeric(12,8) NOT NULL DEFAULT 1,
  obrigatoria boolean NOT NULL DEFAULT true,
  limite jsonb,
  UNIQUE(perfil_qualidade_produto_id,codigo)
);
COMMENT ON TABLE catalogo.perfil_qualidade_produto_regra IS 'Regras ponderadas do perfil de qualidade.';


CREATE TABLE IF NOT EXISTS catalogo.indicador_versao (
  indicador_versao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  versao varchar(80) NOT NULL,
  nome varchar(300),
  descricao text,
  formula text,
  tipo_medida_id bigint REFERENCES referencia.tipo_medida(tipo_medida_id),
  natureza_valor_id bigint REFERENCES referencia.natureza_valor(natureza_valor_id),
  unidade_id bigint REFERENCES referencia.unidade_medida(unidade_id),
  periodicidade_id smallint REFERENCES referencia.tipo_periodicidade(tipo_periodicidade_id),
  granularidade_territorial_id bigint REFERENCES referencia.granularidade_analitica(granularidade_analitica_id),
  granularidade_temporal_id bigint REFERENCES referencia.granularidade_analitica(granularidade_analitica_id),
  valido_desde date,
  valido_ate date,
  publicado boolean NOT NULL DEFAULT true,
  UNIQUE(indicador_id,versao)
);
COMMENT ON TABLE catalogo.indicador_versao IS 'Definição versionada do indicador para comparabilidade histórica.';


CREATE TABLE IF NOT EXISTS catalogo.indicador_relacao (
  indicador_relacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_origem_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  indicador_destino_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  tipo_relacao varchar(80) NOT NULL,
  expressao text,
  valido_desde date,
  valido_ate date,
  CHECK(indicador_origem_id<>indicador_destino_id),
  UNIQUE(indicador_origem_id,indicador_destino_id,tipo_relacao,valido_desde)
);
COMMENT ON TABLE catalogo.indicador_relacao IS 'Relações derivado-de, denominador-de, substitui, comparável-com e decompõe-em.';


CREATE TABLE IF NOT EXISTS catalogo.indicador_papel_fonte (
  indicador_papel_fonte_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  papel varchar(50) NOT NULL,
  prioridade smallint,
  condicao_uso text,
  valido_desde date,
  valido_ate date,
  UNIQUE(indicador_id,fonte_id,papel,valido_desde)
);
COMMENT ON TABLE catalogo.indicador_papel_fonte IS 'Fonte como numerador, denominador, oficial, alternativa, validação ou contexto.';


CREATE TABLE IF NOT EXISTS catalogo.indicador_compatibilidade (
  indicador_compatibilidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_versao_a_id bigint NOT NULL REFERENCES catalogo.indicador_versao(indicador_versao_id),
  indicador_versao_b_id bigint NOT NULL REFERENCES catalogo.indicador_versao(indicador_versao_id),
  nivel varchar(40) NOT NULL,
  metodo_conversao text,
  quebra_serie boolean NOT NULL DEFAULT false,
  justificativa text,
  CHECK(indicador_versao_a_id<>indicador_versao_b_id),
  UNIQUE(indicador_versao_a_id,indicador_versao_b_id)
);
COMMENT ON TABLE catalogo.indicador_compatibilidade IS 'Compatibilidade entre versões/metodologias de indicador.';


CREATE TABLE IF NOT EXISTS catalogo.dimensao_analitica_versao (
  dimensao_analitica_versao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  dimensao_analitica_id bigint NOT NULL REFERENCES catalogo.dimensao_analitica(dimensao_analitica_id),
  versao varchar(80) NOT NULL,
  classificacao_id bigint REFERENCES referencia.sistema_classificacao(sistema_classificacao_id),
  valido_desde date,
  valido_ate date,
  descricao text,
  UNIQUE(dimensao_analitica_id,versao)
);
COMMENT ON TABLE catalogo.dimensao_analitica_versao IS 'Versão da dimensão/classificação usada na análise.';


CREATE TABLE IF NOT EXISTS controle.objeto_dado (
  objeto_dado_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  produto_dado_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  schema_tabela varchar(120),
  nome_tabela varchar(180),
  chave_registro text,
  hash_registro char(64),
  validade_negocio_inicio timestamptz,
  validade_negocio_fim timestamptz,
  validade_sistema_inicio timestamptz NOT NULL DEFAULT now(),
  validade_sistema_fim timestamptz,
  classificacao_sensibilidade_id smallint REFERENCES seguranca.classificacao_sensibilidade(classificacao_sensibilidade_id),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(schema_tabela,nome_tabela,chave_registro,hash_registro)
);
COMMENT ON TABLE controle.objeto_dado IS 'Identidade universal para qualquer registro/artefato lógico referenciado por linhagem, evidência e políticas.';


CREATE TABLE IF NOT EXISTS controle.objeto_dado_relacao (
  objeto_dado_relacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  objeto_origem_id uuid NOT NULL REFERENCES controle.objeto_dado(objeto_dado_id),
  objeto_destino_id uuid NOT NULL REFERENCES controle.objeto_dado(objeto_dado_id),
  tipo_relacao varchar(80) NOT NULL,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK(objeto_origem_id<>objeto_destino_id),
  UNIQUE(objeto_origem_id,objeto_destino_id,tipo_relacao)
);
COMMENT ON TABLE controle.objeto_dado_relacao IS 'Grafo universal de relações entre objetos de dados.';


CREATE TABLE IF NOT EXISTS controle.versao_codigo_transformacao (
  versao_codigo_transformacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(140) NOT NULL,
  nome varchar(300) NOT NULL,
  repositorio_uri text,
  commit_hash varchar(160),
  imagem_container varchar(500),
  digest_container varchar(200),
  versao varchar(100),
  linguagem varchar(80),
  criado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(codigo,commit_hash,digest_container)
);
COMMENT ON TABLE controle.versao_codigo_transformacao IS 'Código/versionamento reproduzível para ETL, ELT, cálculo, modelo e transformação.';


CREATE TABLE IF NOT EXISTS controle.execucao_transformacao (
  execucao_transformacao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  tipo_transformacao_id bigint REFERENCES referencia.tipo_transformacao(tipo_transformacao_id),
  versao_codigo_transformacao_id bigint REFERENCES controle.versao_codigo_transformacao(versao_codigo_transformacao_id),
  execucao_carga_id uuid REFERENCES controle.execucao_carga(execucao_id),
  produto_destino_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(40) NOT NULL DEFAULT 'iniciada',
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  semente bigint,
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb,
  log_uri text,
  hash_execucao char(64)
);
COMMENT ON TABLE controle.execucao_transformacao IS 'Execução genérica comum a todas as fases e tipos de processamento.';


CREATE TABLE IF NOT EXISTS controle.entrada_transformacao (
  entrada_transformacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_transformacao_id uuid NOT NULL REFERENCES controle.execucao_transformacao(execucao_transformacao_id) ON DELETE CASCADE,
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  produto_dado_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  papel varchar(80),
  ordem integer
);
COMMENT ON TABLE controle.entrada_transformacao IS 'Entradas materiais/lógicas de uma transformação.';


CREATE TABLE IF NOT EXISTS controle.saida_transformacao (
  saida_transformacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_transformacao_id uuid NOT NULL REFERENCES controle.execucao_transformacao(execucao_transformacao_id) ON DELETE CASCADE,
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  produto_dado_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  papel varchar(80),
  ordem integer
);
COMMENT ON TABLE controle.saida_transformacao IS 'Saídas materiais/lógicas de uma transformação.';


CREATE TABLE IF NOT EXISTS controle.dependencia_execucao_transformacao (
  dependencia_execucao_transformacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_origem_id uuid NOT NULL REFERENCES controle.execucao_transformacao(execucao_transformacao_id),
  execucao_destino_id uuid NOT NULL REFERENCES controle.execucao_transformacao(execucao_transformacao_id),
  tipo varchar(80),
  CHECK(execucao_origem_id<>execucao_destino_id),
  UNIQUE(execucao_origem_id,execucao_destino_id)
);
COMMENT ON TABLE controle.dependencia_execucao_transformacao IS 'DAG de execuções para análise de impacto.';


CREATE TABLE IF NOT EXISTS controle.linhagem_objeto_r2 (
  linhagem_objeto_r2_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  objeto_origem_id uuid NOT NULL REFERENCES controle.objeto_dado(objeto_dado_id),
  objeto_destino_id uuid NOT NULL REFERENCES controle.objeto_dado(objeto_dado_id),
  execucao_transformacao_id uuid REFERENCES controle.execucao_transformacao(execucao_transformacao_id),
  transformacao text,
  criado_em timestamptz NOT NULL DEFAULT now(),
  CHECK(objeto_origem_id<>objeto_destino_id),
  UNIQUE(objeto_origem_id,objeto_destino_id,execucao_transformacao_id)
);
COMMENT ON TABLE controle.linhagem_objeto_r2 IS 'Linhagem objeto-a-objeto sem depender de nomes de tabela em texto.';


CREATE TABLE IF NOT EXISTS controle.linhagem_coluna (
  linhagem_coluna_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_transformacao_id uuid REFERENCES controle.execucao_transformacao(execucao_transformacao_id),
  produto_origem_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  campo_origem varchar(500),
  produto_destino_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  campo_destino varchar(500) NOT NULL,
  expressao_transformacao text,
  tipo varchar(80),
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE controle.linhagem_coluna IS 'Linhagem de campo/coluna, necessária para explicar numeradores, denominadores e transformações.';


CREATE TABLE IF NOT EXISTS controle.grupo_reconciliacao (
  grupo_reconciliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  dimensoes jsonb NOT NULL DEFAULT '{}'::jsonb,
  motivo varchar(160),
  status varchar(50) NOT NULL DEFAULT 'aberto',
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE controle.grupo_reconciliacao IS 'Grupo universal de valores potencialmente equivalentes entre fontes/fases.';


CREATE TABLE IF NOT EXISTS controle.valor_reconciliacao (
  valor_reconciliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  grupo_reconciliacao_id bigint NOT NULL REFERENCES controle.grupo_reconciliacao(grupo_reconciliacao_id) ON DELETE CASCADE,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  observacao_id bigint REFERENCES dw.fato_observacao(observacao_id),
  valor_numero numeric(38,12),
  valor_texto text,
  unidade_id bigint REFERENCES referencia.unidade_medida(unidade_id),
  metodologia_id bigint REFERENCES catalogo.metodologia_indicador(metodologia_id),
  status_dado_id smallint REFERENCES referencia.status_dado(status_dado_id),
  qualidade numeric(8,6),
  data_referencia date,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE controle.valor_reconciliacao IS 'Cada versão concorrente de um valor em um grupo de reconciliação.';


CREATE TABLE IF NOT EXISTS controle.regra_reconciliacao_unificada (
  regra_reconciliacao_unificada_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  dominio varchar(120),
  codigo varchar(120) NOT NULL,
  descricao text,
  criterio_equivalencia text,
  tolerancia_absoluta numeric(38,12),
  tolerancia_percentual numeric(20,10),
  estrategia_decisao varchar(80),
  exige_humano boolean NOT NULL DEFAULT false,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(indicador_id,dominio,codigo)
);
COMMENT ON TABLE controle.regra_reconciliacao_unificada IS 'Regra única para municipal, público×privado, próprio×externo e múltiplas fontes.';


CREATE TABLE IF NOT EXISTS controle.decisao_reconciliacao (
  decisao_reconciliacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  grupo_reconciliacao_id bigint NOT NULL REFERENCES controle.grupo_reconciliacao(grupo_reconciliacao_id),
  regra_reconciliacao_unificada_id bigint REFERENCES controle.regra_reconciliacao_unificada(regra_reconciliacao_unificada_id),
  valor_escolhido_id bigint REFERENCES controle.valor_reconciliacao(valor_reconciliacao_id),
  decisao varchar(80) NOT NULL,
  justificativa text NOT NULL,
  decidido_por varchar(250),
  decidido_em timestamptz NOT NULL DEFAULT now(),
  confianca numeric(8,6),
  publicavel boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE controle.decisao_reconciliacao IS 'Decisão explícita ou manutenção da divergência; nunca escolhe silenciosamente.';


CREATE TABLE IF NOT EXISTS controle.avaliacao_qualidade_produto (
  avaliacao_qualidade_produto_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_versao_id bigint NOT NULL REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  perfil_qualidade_produto_id bigint REFERENCES catalogo.perfil_qualidade_produto(perfil_qualidade_produto_id),
  avaliado_em timestamptz NOT NULL DEFAULT now(),
  pontuacao numeric(8,6),
  aprovado boolean,
  registros_avaliados bigint,
  resumo jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE controle.avaliacao_qualidade_produto IS 'Avaliação global de qualidade por versão de Data Product.';


CREATE TABLE IF NOT EXISTS controle.avaliacao_qualidade_metrica (
  avaliacao_qualidade_metrica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  avaliacao_qualidade_produto_id bigint NOT NULL REFERENCES controle.avaliacao_qualidade_produto(avaliacao_qualidade_produto_id) ON DELETE CASCADE,
  codigo varchar(140) NOT NULL,
  dimensao_qualidade varchar(80),
  valor numeric(30,12),
  limite numeric(30,12),
  resultado varchar(40),
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(avaliacao_qualidade_produto_id,codigo)
);
COMMENT ON TABLE controle.avaliacao_qualidade_metrica IS 'Métricas de completude, validade, unicidade, consistência, atualidade e representatividade.';


CREATE TABLE IF NOT EXISTS controle.anomalia_dado_r2 (
  anomalia_dado_r2_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_versao_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  tipo varchar(120) NOT NULL,
  severidade varchar(30) NOT NULL,
  detectada_em timestamptz NOT NULL DEFAULT now(),
  metodo varchar(120),
  score numeric(20,10),
  descricao text,
  status varchar(50) NOT NULL DEFAULT 'aberta',
  resolvida_em timestamptz
);
COMMENT ON TABLE controle.anomalia_dado_r2 IS 'Anomalias de dados independentemente da origem.';


CREATE TABLE IF NOT EXISTS controle.drift_dado (
  drift_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  campo varchar(300),
  periodo_base_inicio date,
  periodo_base_fim date,
  periodo_atual_inicio date,
  periodo_atual_fim date,
  metrica varchar(120),
  valor numeric(30,12),
  limite numeric(30,12),
  detectado_em timestamptz NOT NULL DEFAULT now(),
  status varchar(50)
);
COMMENT ON TABLE controle.drift_dado IS 'Drift estatístico/conceitual que pode indicar mudança real ou quebra de pipeline.';


CREATE TABLE IF NOT EXISTS controle.incidente_qualidade_r2 (
  incidente_qualidade_r2_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint REFERENCES catalogo.produto_dado(produto_dado_id),
  avaliacao_qualidade_produto_id bigint REFERENCES controle.avaliacao_qualidade_produto(avaliacao_qualidade_produto_id),
  tipo varchar(120),
  severidade varchar(30),
  aberto_em timestamptz NOT NULL DEFAULT now(),
  detectado_por varchar(100),
  descricao text,
  impacto jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(50) NOT NULL DEFAULT 'aberto',
  encerrado_em timestamptz
);
COMMENT ON TABLE controle.incidente_qualidade_r2 IS 'Incidente transversal de qualidade.';


CREATE TABLE IF NOT EXISTS controle.impacto_linhagem (
  impacto_linhagem_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  evento_origem_tipo varchar(80) NOT NULL,
  evento_origem_id varchar(200) NOT NULL,
  produto_dado_id bigint REFERENCES catalogo.produto_dado(produto_dado_id),
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  capacidade_id bigint REFERENCES semantico.capacidade_analitica(capacidade_id),
  nivel_impacto varchar(30),
  descricao text,
  calculado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE controle.impacto_linhagem IS 'Impacto downstream de schema, fonte, contrato, produto ou transformação.';


CREATE TABLE IF NOT EXISTS controle.monitoramento_produto_dado (
  monitoramento_produto_dado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  verificado_em timestamptz NOT NULL DEFAULT now(),
  ultima_referencia timestamptz,
  ultima_publicacao timestamptz,
  ultima_ingestao timestamptz,
  atraso interval,
  status_frescor varchar(50),
  status_qualidade varchar(50),
  status_disponibilidade varchar(50),
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE controle.monitoramento_produto_dado IS 'Healthcheck consolidado de Data Products.';


CREATE TABLE IF NOT EXISTS seguranca.sujeito_politica (
  sujeito_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tipo varchar(80) NOT NULL,
  referencia varchar(300) NOT NULL,
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(tipo,referencia)
);
COMMENT ON TABLE seguranca.sujeito_politica IS 'Sujeito lógico para ABAC: usuário, agente Xingú, serviço, organização ou função.';


CREATE TABLE IF NOT EXISTS seguranca.recurso_protegido (
  recurso_protegido_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tipo varchar(80) NOT NULL,
  referencia varchar(500) NOT NULL,
  produto_dado_id bigint REFERENCES catalogo.produto_dado(produto_dado_id),
  classificacao_sensibilidade_id smallint REFERENCES seguranca.classificacao_sensibilidade(classificacao_sensibilidade_id),
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(tipo,referencia)
);
COMMENT ON TABLE seguranca.recurso_protegido IS 'Recurso governado por políticas de acesso/publicação.';


CREATE TABLE IF NOT EXISTS seguranca.politica_acesso_abac (
  politica_acesso_abac_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(140) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  descricao text,
  efeito_padrao varchar(30) NOT NULL DEFAULT 'negar',
  prioridade integer NOT NULL DEFAULT 100,
  valido_desde timestamptz,
  valido_ate timestamptz,
  ativo boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE seguranca.politica_acesso_abac IS 'Política transversal baseada em atributos e finalidade.';


CREATE TABLE IF NOT EXISTS seguranca.regra_politica_acesso (
  regra_politica_acesso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_acesso_abac_id bigint NOT NULL REFERENCES seguranca.politica_acesso_abac(politica_acesso_abac_id) ON DELETE CASCADE,
  ordem integer NOT NULL,
  acao varchar(80) NOT NULL,
  condicao_sujeito jsonb NOT NULL DEFAULT '{}'::jsonb,
  condicao_recurso jsonb NOT NULL DEFAULT '{}'::jsonb,
  condicao_ambiente jsonb NOT NULL DEFAULT '{}'::jsonb,
  condicao_finalidade jsonb NOT NULL DEFAULT '{}'::jsonb,
  decisao_tipo_id bigint REFERENCES referencia.tipo_decisao_politica(tipo_decisao_politica_id),
  obrigacoes jsonb NOT NULL DEFAULT '[]'::jsonb
);
COMMENT ON TABLE seguranca.regra_politica_acesso IS 'Regras ABAC declarativas e auditáveis.';


CREATE TABLE IF NOT EXISTS seguranca.vinculo_recurso_politica (
  vinculo_recurso_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_protegido_id bigint NOT NULL REFERENCES seguranca.recurso_protegido(recurso_protegido_id),
  politica_acesso_abac_id bigint NOT NULL REFERENCES seguranca.politica_acesso_abac(politica_acesso_abac_id),
  valido_desde timestamptz,
  valido_ate timestamptz,
  UNIQUE(recurso_protegido_id,politica_acesso_abac_id,valido_desde)
);
COMMENT ON TABLE seguranca.vinculo_recurso_politica IS 'Políticas aplicáveis a um recurso.';


CREATE TABLE IF NOT EXISTS seguranca.contexto_avaliacao_politica (
  contexto_politica_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  sujeito_politica_id bigint REFERENCES seguranca.sujeito_politica(sujeito_politica_id),
  finalidade_id bigint REFERENCES seguranca.finalidade_tratamento(finalidade_id),
  plano_consulta_id uuid REFERENCES semantico.plano_consulta(plano_consulta_id),
  ambiente_dado_id smallint REFERENCES seguranca.ambiente_dado(ambiente_dado_id),
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  criado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE seguranca.contexto_avaliacao_politica IS 'Contexto completo para a avaliação de políticas.';


CREATE TABLE IF NOT EXISTS seguranca.avaliacao_politica (
  avaliacao_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  contexto_politica_id uuid NOT NULL REFERENCES seguranca.contexto_avaliacao_politica(contexto_politica_id),
  recurso_protegido_id bigint NOT NULL REFERENCES seguranca.recurso_protegido(recurso_protegido_id),
  acao varchar(80) NOT NULL,
  decisao_tipo_id bigint NOT NULL REFERENCES referencia.tipo_decisao_politica(tipo_decisao_politica_id),
  politica_acesso_abac_id bigint REFERENCES seguranca.politica_acesso_abac(politica_acesso_abac_id),
  regra_politica_acesso_id bigint REFERENCES seguranca.regra_politica_acesso(regra_politica_acesso_id),
  avaliado_em timestamptz NOT NULL DEFAULT now(),
  motivo text,
  obrigacoes jsonb NOT NULL DEFAULT '[]'::jsonb
);
COMMENT ON TABLE seguranca.avaliacao_politica IS 'Resultado auditável do motor de políticas.';


CREATE TABLE IF NOT EXISTS seguranca.obrigacao_politica (
  obrigacao_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  avaliacao_politica_id bigint NOT NULL REFERENCES seguranca.avaliacao_politica(avaliacao_politica_id) ON DELETE CASCADE,
  tipo varchar(80) NOT NULL,
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  cumprida boolean NOT NULL DEFAULT false,
  cumprida_em timestamptz,
  evidencia text
);
COMMENT ON TABLE seguranca.obrigacao_politica IS 'Obrigações como agregar, mascarar, registrar, exigir aprovação ou sala limpa.';


CREATE TABLE IF NOT EXISTS seguranca.decisao_divulgacao (
  decisao_divulgacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  contexto_politica_id uuid REFERENCES seguranca.contexto_avaliacao_politica(contexto_politica_id),
  recurso_protegido_id bigint REFERENCES seguranca.recurso_protegido(recurso_protegido_id),
  decisao_tipo_id bigint REFERENCES referencia.tipo_decisao_politica(tipo_decisao_politica_id),
  granularidade_solicitada varchar(160),
  granularidade_autorizada varchar(160),
  regra_minimo_celula_id bigint REFERENCES seguranca.regra_minimo_celula(regra_minimo_celula_id),
  politica_divulgacao_id bigint REFERENCES seguranca.politica_divulgacao(politica_divulgacao_id),
  decidido_em timestamptz NOT NULL DEFAULT now(),
  justificativa text
);
COMMENT ON TABLE seguranca.decisao_divulgacao IS 'Decisão única para divulgação em qualquer fase.';


CREATE TABLE IF NOT EXISTS seguranca.decisao_uso_ia (
  decisao_uso_ia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  contexto_politica_id uuid REFERENCES seguranca.contexto_avaliacao_politica(contexto_politica_id),
  recurso_protegido_id bigint REFERENCES seguranca.recurso_protegido(recurso_protegido_id),
  operacao varchar(80) NOT NULL,
  modelo varchar(200),
  provedor varchar(160),
  decisao_tipo_id bigint REFERENCES referencia.tipo_decisao_politica(tipo_decisao_politica_id),
  modelo_local_obrigatorio boolean,
  decidido_em timestamptz NOT NULL DEFAULT now(),
  justificativa text
);
COMMENT ON TABLE seguranca.decisao_uso_ia IS 'Decisão sobre inferência, embedding, treinamento e envio a modelo externo.';


CREATE TABLE IF NOT EXISTS seguranca.evidencia_autorizacao (
  evidencia_autorizacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  avaliacao_politica_id bigint REFERENCES seguranca.avaliacao_politica(avaliacao_politica_id),
  tipo varchar(100) NOT NULL,
  referencia text NOT NULL,
  valido_desde timestamptz,
  valido_ate timestamptz,
  checksum char(64),
  descricao text
);
COMMENT ON TABLE seguranca.evidencia_autorizacao IS 'Evidência jurídica/contratual/consentimento que sustentou a decisão.';


CREATE TABLE IF NOT EXISTS dw.observacao_incerteza (
  observacao_incerteza_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  observacao_id bigint NOT NULL REFERENCES dw.fato_observacao(observacao_id) ON DELETE CASCADE,
  tipo_incerteza_id bigint NOT NULL REFERENCES referencia.tipo_incerteza(tipo_incerteza_id),
  valor numeric(30,12),
  unidade_id bigint REFERENCES referencia.unidade_medida(unidade_id),
  nivel_confianca numeric(8,6),
  limite_inferior numeric(38,12),
  limite_superior numeric(38,12),
  metodo varchar(180),
  origem varchar(120),
  UNIQUE(observacao_id,tipo_incerteza_id,metodo)
);
COMMENT ON TABLE dw.observacao_incerteza IS 'Decompõe incerteza amostral, instrumental, espacial, de modelo e revisão.';


CREATE TABLE IF NOT EXISTS dw.observacao_qualidade_detalhe (
  observacao_qualidade_detalhe_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  observacao_id bigint NOT NULL REFERENCES dw.fato_observacao(observacao_id) ON DELETE CASCADE,
  dimensao varchar(80) NOT NULL,
  valor numeric(8,6),
  resultado varchar(50),
  regra varchar(180),
  descricao text,
  UNIQUE(observacao_id,dimensao,regra)
);
COMMENT ON TABLE dw.observacao_qualidade_detalhe IS 'Qualidade por dimensão da observação universal.';


CREATE TABLE IF NOT EXISTS dw.observacao_revisao (
  observacao_revisao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  observacao_id bigint NOT NULL REFERENCES dw.fato_observacao(observacao_id) ON DELETE CASCADE,
  revisao varchar(120) NOT NULL,
  observacao_anterior_id bigint REFERENCES dw.fato_observacao(observacao_id),
  motivo varchar(180),
  publicada_em timestamptz,
  delta_valor numeric(38,12),
  breaking_change boolean NOT NULL DEFAULT false,
  UNIQUE(observacao_id,revisao)
);
COMMENT ON TABLE dw.observacao_revisao IS 'Histórico explícito de revisões sem sobrescrever silenciosamente valores.';


CREATE TABLE IF NOT EXISTS documental.ato_normativo (
  ato_normativo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  documento_id bigint REFERENCES documental.documento(documento_id),
  tipo_ato varchar(100) NOT NULL,
  numero varchar(160),
  jurisdicao_territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  orgao_entidade_id bigint REFERENCES nucleo.entidade(entidade_id),
  ementa text,
  publicado_em date,
  vigente_desde date,
  vigente_ate date,
  situacao varchar(80),
  ato_substituto_id bigint REFERENCES documental.ato_normativo(ato_normativo_id),
  UNIQUE(tipo_ato,numero,jurisdicao_territorio_id,publicado_em)
);
COMMENT ON TABLE documental.ato_normativo IS 'Norma/ato universal para responder o que estava vigente em determinada data.';


CREATE TABLE IF NOT EXISTS documental.dispositivo_ato_normativo (
  dispositivo_ato_normativo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ato_normativo_id bigint NOT NULL REFERENCES documental.ato_normativo(ato_normativo_id) ON DELETE CASCADE,
  codigo varchar(160),
  tipo varchar(80),
  ordem integer,
  texto text NOT NULL,
  vigente_desde date,
  vigente_ate date,
  UNIQUE(ato_normativo_id,codigo,vigente_desde)
);
COMMENT ON TABLE documental.dispositivo_ato_normativo IS 'Dispositivos normativos versionados.';


CREATE TABLE IF NOT EXISTS documental.relacao_ato_normativo (
  relacao_ato_normativo_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ato_origem_id bigint NOT NULL REFERENCES documental.ato_normativo(ato_normativo_id),
  ato_destino_id bigint NOT NULL REFERENCES documental.ato_normativo(ato_normativo_id),
  tipo_relacao varchar(80) NOT NULL,
  efetivo_em date,
  descricao text,
  CHECK(ato_origem_id<>ato_destino_id),
  UNIQUE(ato_origem_id,ato_destino_id,tipo_relacao,efetivo_em)
);
COMMENT ON TABLE documental.relacao_ato_normativo IS 'Revoga, altera, regulamenta, suspende, consolida ou substitui outro ato.';


CREATE TABLE IF NOT EXISTS semantico.ontologia (
  ontologia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  descricao text,
  dominio varchar(120),
  ativo boolean NOT NULL DEFAULT true
);
COMMENT ON TABLE semantico.ontologia IS 'Ontologia controlada da Xingú para desacoplar linguagem natural do schema físico.';


CREATE TABLE IF NOT EXISTS semantico.versao_ontologia (
  versao_ontologia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ontologia_id bigint NOT NULL REFERENCES semantico.ontologia(ontologia_id),
  versao varchar(80) NOT NULL,
  valido_desde timestamptz,
  valido_ate timestamptz,
  schema_hash char(64),
  publicado_em timestamptz,
  UNIQUE(ontologia_id,versao)
);
COMMENT ON TABLE semantico.versao_ontologia IS 'Versão da ontologia utilizada em cada plano/resposta.';


CREATE TABLE IF NOT EXISTS semantico.conceito_ontologia (
  conceito_ontologia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_ontologia_id bigint NOT NULL REFERENCES semantico.versao_ontologia(versao_ontologia_id),
  codigo varchar(160) NOT NULL,
  nome varchar(300) NOT NULL,
  tipo varchar(80),
  descricao text,
  conceito_legado_id bigint REFERENCES semantico.conceito(conceito_id),
  atributos jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(versao_ontologia_id,codigo)
);
COMMENT ON TABLE semantico.conceito_ontologia IS 'Conceito semanticamente versionado.';


CREATE TABLE IF NOT EXISTS semantico.relacao_conceito (
  relacao_conceito_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conceito_origem_id bigint NOT NULL REFERENCES semantico.conceito_ontologia(conceito_ontologia_id),
  conceito_destino_id bigint NOT NULL REFERENCES semantico.conceito_ontologia(conceito_ontologia_id),
  tipo_relacao_semantica_id bigint REFERENCES referencia.tipo_relacao_semantica(tipo_relacao_semantica_id),
  peso numeric(8,6),
  condicao text,
  CHECK(conceito_origem_id<>conceito_destino_id),
  UNIQUE(conceito_origem_id,conceito_destino_id,tipo_relacao_semantica_id)
);
COMMENT ON TABLE semantico.relacao_conceito IS 'Arestas do conhecimento semântico.';


CREATE TABLE IF NOT EXISTS semantico.conceito_indicador (
  conceito_indicador_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conceito_ontologia_id bigint NOT NULL REFERENCES semantico.conceito_ontologia(conceito_ontologia_id),
  indicador_id bigint NOT NULL REFERENCES catalogo.indicador(indicador_id),
  papel varchar(80),
  prioridade smallint,
  condicao text,
  UNIQUE(conceito_ontologia_id,indicador_id,papel)
);
COMMENT ON TABLE semantico.conceito_indicador IS 'Liga linguagem/ontologia a indicadores concretos.';


CREATE TABLE IF NOT EXISTS semantico.conceito_dimensao (
  conceito_dimensao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  conceito_ontologia_id bigint NOT NULL REFERENCES semantico.conceito_ontologia(conceito_ontologia_id),
  dimensao_analitica_id bigint NOT NULL REFERENCES catalogo.dimensao_analitica(dimensao_analitica_id),
  papel varchar(80),
  UNIQUE(conceito_ontologia_id,dimensao_analitica_id,papel)
);
COMMENT ON TABLE semantico.conceito_dimensao IS 'Liga conceitos a dimensões/filtros.';


CREATE TABLE IF NOT EXISTS semantico.plano_consulta_etapa (
  plano_consulta_etapa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plano_consulta_id uuid NOT NULL REFERENCES semantico.plano_consulta(plano_consulta_id) ON DELETE CASCADE,
  ordem integer NOT NULL,
  tipo varchar(80) NOT NULL,
  descricao text,
  entrada jsonb NOT NULL DEFAULT '{}'::jsonb,
  saida_esperada jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(50),
  UNIQUE(plano_consulta_id,ordem)
);
COMMENT ON TABLE semantico.plano_consulta_etapa IS 'Plano executável passo a passo em vez de SQL monolítico.';


CREATE TABLE IF NOT EXISTS semantico.plano_consulta_recurso (
  plano_consulta_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plano_consulta_id uuid NOT NULL REFERENCES semantico.plano_consulta(plano_consulta_id) ON DELETE CASCADE,
  produto_dado_id bigint REFERENCES catalogo.produto_dado(produto_dado_id),
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  papel varchar(60),
  obrigatorio boolean NOT NULL DEFAULT true,
  prioridade smallint
);
COMMENT ON TABLE semantico.plano_consulta_recurso IS 'Recursos semânticos selecionados para responder.';


CREATE TABLE IF NOT EXISTS semantico.plano_consulta_politica (
  plano_consulta_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  plano_consulta_id uuid NOT NULL REFERENCES semantico.plano_consulta(plano_consulta_id) ON DELETE CASCADE,
  avaliacao_politica_id bigint REFERENCES seguranca.avaliacao_politica(avaliacao_politica_id),
  acao varchar(80),
  resultado varchar(80),
  obrigacoes jsonb NOT NULL DEFAULT '[]'::jsonb
);
COMMENT ON TABLE semantico.plano_consulta_politica IS 'Políticas avaliadas durante o planejamento/execução da resposta.';


CREATE TABLE IF NOT EXISTS semantico.execucao_consulta (
  execucao_consulta_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  plano_consulta_id uuid NOT NULL REFERENCES semantico.plano_consulta(plano_consulta_id),
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(50),
  usuario_referencia varchar(300),
  agente_xingu varchar(160),
  versao_ontologia_id bigint REFERENCES semantico.versao_ontologia(versao_ontologia_id),
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb
);
COMMENT ON TABLE semantico.execucao_consulta IS 'Execução concreta de um plano semântico.';


CREATE TABLE IF NOT EXISTS semantico.resultado_consulta (
  resultado_consulta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_consulta_id uuid NOT NULL REFERENCES semantico.execucao_consulta(execucao_consulta_id) ON DELETE CASCADE,
  etapa_id bigint REFERENCES semantico.plano_consulta_etapa(plano_consulta_etapa_id),
  tipo varchar(80),
  linhas bigint,
  colunas integer,
  resultado_json jsonb,
  uri_resultado text,
  hash_resultado char(64),
  gerado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE semantico.resultado_consulta IS 'Resultado intermediário/final rastreado e hashado.';


CREATE TABLE IF NOT EXISTS semantico.resposta_xingu (
  resposta_xingu_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_consulta_id uuid NOT NULL REFERENCES semantico.execucao_consulta(execucao_consulta_id),
  texto text,
  formato varchar(60),
  gerada_em timestamptz NOT NULL DEFAULT now(),
  status varchar(50) NOT NULL DEFAULT 'gerada',
  confianca_global numeric(8,6),
  deve_exibir_alerta boolean NOT NULL DEFAULT false,
  hash_resposta char(64)
);
COMMENT ON TABLE semantico.resposta_xingu IS 'Resposta final como objeto auditável, não apenas texto transitório.';


CREATE TABLE IF NOT EXISTS semantico.afirmacao_resposta (
  afirmacao_resposta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  resposta_xingu_id uuid NOT NULL REFERENCES semantico.resposta_xingu(resposta_xingu_id) ON DELETE CASCADE,
  ordem integer NOT NULL,
  afirmacao text NOT NULL,
  tipo varchar(80),
  indicador_id bigint REFERENCES catalogo.indicador(indicador_id),
  territorio_id bigint REFERENCES referencia.territorio(territorio_id),
  periodo_id bigint REFERENCES referencia.periodo_referencia(periodo_id),
  confianca numeric(8,6),
  publicavel boolean NOT NULL DEFAULT true,
  UNIQUE(resposta_xingu_id,ordem)
);
COMMENT ON TABLE semantico.afirmacao_resposta IS 'Cada afirmação factual da resposta é auditável separadamente.';


CREATE TABLE IF NOT EXISTS semantico.afirmacao_evidencia (
  afirmacao_evidencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  afirmacao_resposta_id bigint NOT NULL REFERENCES semantico.afirmacao_resposta(afirmacao_resposta_id) ON DELETE CASCADE,
  evidencia_id bigint REFERENCES semantico.evidencia(evidencia_id),
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  observacao_id bigint REFERENCES dw.fato_observacao(observacao_id),
  tipo_evidencia_id bigint REFERENCES referencia.tipo_evidencia(tipo_evidencia_id),
  nivel_evidencia_id bigint REFERENCES referencia.nivel_evidencia(nivel_evidencia_id),
  papel varchar(50) NOT NULL DEFAULT 'suporte',
  peso numeric(8,6),
  CHECK(num_nonnulls(evidencia_id,objeto_dado_id,observacao_id)>=1)
);
COMMENT ON TABLE semantico.afirmacao_evidencia IS 'Liga cada afirmação a evidências concretas, inclusive contraditórias.';


CREATE TABLE IF NOT EXISTS semantico.limitacao_resposta_execucao (
  limitacao_resposta_execucao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  resposta_xingu_id uuid NOT NULL REFERENCES semantico.resposta_xingu(resposta_xingu_id) ON DELETE CASCADE,
  tipo varchar(100) NOT NULL,
  severidade varchar(30),
  descricao text NOT NULL,
  mensagem_usuario text,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  produto_dado_id bigint REFERENCES catalogo.produto_dado(produto_dado_id),
  impede_resposta boolean NOT NULL DEFAULT false
);
COMMENT ON TABLE semantico.limitacao_resposta_execucao IS 'Limitação concreta observada naquela resposta.';


CREATE TABLE IF NOT EXISTS semantico.decisao_resposta (
  decisao_resposta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  resposta_xingu_id uuid NOT NULL REFERENCES semantico.resposta_xingu(resposta_xingu_id),
  tipo varchar(80) NOT NULL,
  decisao varchar(80) NOT NULL,
  justificativa text NOT NULL,
  avaliacao_resposta_id bigint REFERENCES semantico.avaliacao_resposta(avaliacao_id),
  decisao_divulgacao_id bigint REFERENCES seguranca.decisao_divulgacao(decisao_divulgacao_id),
  decisao_reconciliacao_id bigint REFERENCES controle.decisao_reconciliacao(decisao_reconciliacao_id),
  decidido_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE semantico.decisao_resposta IS 'Por que a Xingú respondeu, agregou, alertou, recusou ou apresentou múltiplas fontes.';


CREATE TABLE IF NOT EXISTS semantico.auditoria_sql_xingu (
  auditoria_sql_xingu_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_consulta_id uuid NOT NULL REFERENCES semantico.execucao_consulta(execucao_consulta_id),
  etapa_id bigint REFERENCES semantico.plano_consulta_etapa(plano_consulta_etapa_id),
  sql_hash char(64),
  sql_texto text,
  aprovado_politica boolean,
  tempo_ms bigint,
  linhas bigint,
  explain_resumo jsonb,
  executado_em timestamptz NOT NULL DEFAULT now()
);
COMMENT ON TABLE semantico.auditoria_sql_xingu IS 'Auditoria do SQL gerado; prepara o hardening físico e impede SQL sem rastreio.';


CREATE TABLE IF NOT EXISTS catalogo.politica_particionamento (
  politica_particionamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  schema_tabela varchar(120) NOT NULL,
  nome_tabela varchar(180) NOT NULL,
  estrategia varchar(60) NOT NULL,
  chave varchar(200),
  intervalo varchar(80),
  subparticao varchar(160),
  criterio_ativacao text,
  observacoes text,
  UNIQUE(schema_tabela,nome_tabela)
);
COMMENT ON TABLE catalogo.politica_particionamento IS 'Recomendação/contrato de particionamento para a prova física.';


CREATE TABLE IF NOT EXISTS catalogo.politica_indexacao (
  politica_indexacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  schema_tabela varchar(120) NOT NULL,
  nome_tabela varchar(180) NOT NULL,
  tipo_indice varchar(40) NOT NULL,
  colunas_expressao text NOT NULL,
  condicao text,
  justificativa text,
  prioridade smallint,
  UNIQUE(schema_tabela,nome_tabela,tipo_indice,colunas_expressao)
);
COMMENT ON TABLE catalogo.politica_indexacao IS 'Índices pretendidos por padrão de consulta; serão provados com EXPLAIN ANALYZE.';


CREATE TABLE IF NOT EXISTS catalogo.politica_armazenamento (
