CREATE OR REPLACE VIEW semantico.vw_observacao_apta_resposta AS
SELECT o.*
FROM dw.fato_observacao o
LEFT JOIN dw.dim_status_dado sd ON sd.status_dado_sk=o.status_dado_sk
WHERE COALESCE(o.suprimido,false)=false
  AND COALESCE(sd.pode_divulgar,true)=true
  AND o.validade_sistema_fim IS NULL;

CREATE OR REPLACE VIEW controle.vw_saude_produto_dado AS
SELECT p.produto_dado_id,p.codigo,p.nome,p.dominio,p.camada,
       m.verificado_em,m.status_frescor,m.status_qualidade,m.status_disponibilidade,
       q.pontuacao,q.aprovado
FROM catalogo.produto_dado p
LEFT JOIN LATERAL (
  SELECT * FROM controle.monitoramento_produto_dado m2
  WHERE m2.produto_dado_id=p.produto_dado_id ORDER BY m2.verificado_em DESC LIMIT 1
) m ON true
LEFT JOIN LATERAL (
  SELECT aq.* FROM controle.avaliacao_qualidade_produto aq
  JOIN catalogo.versao_produto_dado vp ON vp.versao_produto_dado_id=aq.produto_dado_versao_id
  WHERE vp.produto_dado_id=p.produto_dado_id ORDER BY aq.avaliado_em DESC LIMIT 1
) q ON true;

