-- ===== CORE R2.1: PERIODICIDADE E ORQUESTRAÇÃO =====

-- ============================================================================
-- ITMT CORE R2.1
-- MODELO UNIVERSAL DE PERIODICIDADE, FRESCOR E ORQUESTRAÇÃO DE INGESTÃO
-- PostgreSQL 16+ / PostGIS 3+
--
-- Objetivo:
-- separar explicitamente:
--   1) granularidade temporal do dado;
--   2) periodicidade do fenômeno/origem;
--   3) frequência esperada de publicação;
--   4) frequência de verificação pelo ITMT;
--   5) frequência/estratégia de ingestão;
--   6) latência esperada;
--   7) janela de publicação;
--   8) revisão retroativa;
--   9) SLA de frescor;
--  10) estado operacional e próxima execução.
-- ============================================================================


CREATE SCHEMA IF NOT EXISTS orquestracao;

-- --------------------------------------------------------------------------
-- REFERÊNCIAS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS referencia.tipo_periodicidade_atualizacao (
  tipo_periodicidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(50) NOT NULL UNIQUE,
  nome varchar(150) NOT NULL,
  categoria varchar(40) NOT NULL CHECK (
    categoria IN ('tempo_fixo','calendario','evento','sob_demanda','continua','variavel')
  ),
  intervalo_referencia interval,
  ordem_aproximada_segundos bigint,
  descricao text,
  ativo boolean NOT NULL DEFAULT true
);

COMMENT ON TABLE referencia.tipo_periodicidade_atualizacao IS
'Vocabulário canônico para periodicidade de origem, publicação, verificação e ingestão.';

CREATE TABLE IF NOT EXISTS referencia.tipo_disparo_orquestracao (
  tipo_disparo_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(40) NOT NULL UNIQUE,
  nome varchar(120) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS referencia.status_frescor_dado (
  status_frescor_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(40) NOT NULL UNIQUE,
  nome varchar(120) NOT NULL,
  severidade smallint NOT NULL DEFAULT 0 CHECK (severidade BETWEEN 0 AND 5),
  descricao text
);

-- --------------------------------------------------------------------------
-- CATÁLOGO: POLÍTICAS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS catalogo.politica_atualizacao (
  politica_atualizacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

  -- Escopo: exatamente um nível deve ser informado.
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id) ON DELETE CASCADE,
  conjunto_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id) ON DELETE CASCADE,
  recurso_id bigint REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,

  nome varchar(250) NOT NULL,
  descricao text,

  -- Tempo do fenômeno/dado.
  granularidade_temporal_dado varchar(120),
  tipo_periodicidade_origem_id smallint
    REFERENCES referencia.tipo_periodicidade_atualizacao(tipo_periodicidade_id),
  intervalo_origem interval,

  -- Publicação pela fonte.
  tipo_periodicidade_publicacao_id smallint
    REFERENCES referencia.tipo_periodicidade_atualizacao(tipo_periodicidade_id),
  intervalo_publicacao interval,
  latencia_publicacao_esperada interval,
  janela_publicacao_inicio time,
  janela_publicacao_fim time,
  dias_semana_publicacao smallint[],

  -- ITMT: verificação e ingestão.
  tipo_periodicidade_verificacao_id smallint
    REFERENCES referencia.tipo_periodicidade_atualizacao(tipo_periodicidade_id),
  intervalo_verificacao interval,
  tipo_periodicidade_ingestao_id smallint
    REFERENCES referencia.tipo_periodicidade_atualizacao(tipo_periodicidade_id),
  intervalo_ingestao interval,

  -- Regras de revisão.
  permite_revisao_retroativa boolean NOT NULL DEFAULT false,
  periodo_revisavel interval,
  estrategia_revisao varchar(40) NOT NULL DEFAULT 'janela_deslizante'
    CHECK (estrategia_revisao IN (
      'nenhuma','janela_deslizante','reprocessar_competencia',
      'reprocessar_serie','versionar_sem_substituir','manual'
    )),

  -- Semântica da política.
  timezone_fonte varchar(100) NOT NULL DEFAULT 'America/Cuiaba',
  periodicidade_oficial boolean NOT NULL DEFAULT false,
  origem_definicao text,
  confianca_politica varchar(20) NOT NULL DEFAULT 'estimada'
    CHECK (confianca_politica IN ('oficial','inferida','estimada','contratual')),
  prioridade smallint NOT NULL DEFAULT 100,
  ativo boolean NOT NULL DEFAULT true,

  valido_desde timestamptz NOT NULL DEFAULT now(),
  valido_ate timestamptz,

  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now(),

  CHECK (num_nonnulls(fonte_id, conjunto_id, recurso_id) = 1),
  CHECK (janela_publicacao_fim IS NULL OR janela_publicacao_inicio IS NULL
         OR janela_publicacao_fim <> janela_publicacao_inicio)
);

COMMENT ON TABLE catalogo.politica_atualizacao IS
'Política temporal hierárquica. Recurso sobrescreve conjunto, que sobrescreve fonte.';

CREATE UNIQUE INDEX IF NOT EXISTS uq_politica_atualizacao_fonte_ativa
ON catalogo.politica_atualizacao(fonte_id)
WHERE fonte_id IS NOT NULL AND ativo = true AND valido_ate IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_politica_atualizacao_conjunto_ativa
ON catalogo.politica_atualizacao(conjunto_id)
WHERE conjunto_id IS NOT NULL AND ativo = true AND valido_ate IS NULL;

CREATE UNIQUE INDEX IF NOT EXISTS uq_politica_atualizacao_recurso_ativa
ON catalogo.politica_atualizacao(recurso_id)
WHERE recurso_id IS NOT NULL AND ativo = true AND valido_ate IS NULL;

CREATE TABLE IF NOT EXISTS catalogo.versao_politica_atualizacao (
  versao_politica_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  versao integer NOT NULL,
  snapshot jsonb NOT NULL,
  motivo text,
  alterado_por varchar(250),
  alterado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(politica_atualizacao_id, versao)
);

CREATE TABLE IF NOT EXISTS catalogo.calendario_publicacao (
  calendario_publicacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  ano smallint,
  competencia varchar(100),
  data_prevista_inicio timestamptz,
  data_prevista_fim timestamptz,
  data_oficial_anunciada timestamptz,
  origem_calendario text,
  status varchar(30) NOT NULL DEFAULT 'previsto'
    CHECK (status IN ('previsto','confirmado','publicado','adiado','cancelado','desconhecido')),
  observacoes text,
  UNIQUE(politica_atualizacao_id, ano, competencia)
);

CREATE TABLE IF NOT EXISTS catalogo.excecao_calendario_atualizacao (
  excecao_calendario_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  inicio timestamptz NOT NULL,
  fim timestamptz,
  tipo varchar(40) NOT NULL
    CHECK (tipo IN ('feriado','manutencao','indisponibilidade','adiamento','antecipacao','bloqueio','outro')),
  acao varchar(40) NOT NULL DEFAULT 'suspender'
    CHECK (acao IN ('suspender','adiar','antecipar','ignorar','executar_manual')),
  nova_data timestamptz,
  descricao text,
  fonte_evidencia text
);

CREATE TABLE IF NOT EXISTS catalogo.sla_atualizacao (
  sla_atualizacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  nome varchar(200) NOT NULL,
  atraso_alerta interval,
  atraso_critico interval,
  tolerancia_indisponibilidade interval,
  max_falhas_consecutivas integer NOT NULL DEFAULT 3,
  janela_medicao interval NOT NULL DEFAULT interval '30 days',
  percentual_disponibilidade_alvo numeric(7,4)
    CHECK (percentual_disponibilidade_alvo IS NULL
           OR percentual_disponibilidade_alvo BETWEEN 0 AND 100),
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(politica_atualizacao_id, nome)
);

CREATE TABLE IF NOT EXISTS catalogo.regra_revisao_retroativa (
  regra_revisao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  codigo varchar(100) NOT NULL,
  tipo_janela varchar(30) NOT NULL DEFAULT 'temporal'
    CHECK (tipo_janela IN ('temporal','competencias','edicoes','serie_completa','manual')),
  quantidade integer,
  unidade varchar(30),
  criterio_reprocessamento jsonb NOT NULL DEFAULT '{}'::jsonb,
  preservar_versao_anterior boolean NOT NULL DEFAULT true,
  recalcular_dw boolean NOT NULL DEFAULT true,
  recalcular_semantico boolean NOT NULL DEFAULT true,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(politica_atualizacao_id, codigo)
);

-- --------------------------------------------------------------------------
-- ORQUESTRAÇÃO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS orquestracao.agendamento_coleta (
  agendamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  politica_atualizacao_id bigint NOT NULL
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id) ON DELETE CASCADE,
  tipo_disparo_id smallint NOT NULL
    REFERENCES referencia.tipo_disparo_orquestracao(tipo_disparo_id),

  nome varchar(250) NOT NULL,
  expressao_cron varchar(150),
  expressao_rrule text,
  intervalo interval,
  timezone varchar(100) NOT NULL DEFAULT 'America/Cuiaba',

  jitter_segundos integer NOT NULL DEFAULT 0,
  timeout_segundos integer,
  max_tentativas integer NOT NULL DEFAULT 3,
  backoff_inicial_segundos integer NOT NULL DEFAULT 60,
  backoff_maximo_segundos integer NOT NULL DEFAULT 3600,

  executar_se_atualizacao_nao_detectada boolean NOT NULL DEFAULT false,
  deduplicar_execucao boolean NOT NULL DEFAULT true,
  concorrencia_maxima smallint NOT NULL DEFAULT 1,

  habilitado boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now(),

  CHECK (num_nonnulls(expressao_cron, expressao_rrule, intervalo) <= 1)
);

CREATE TABLE IF NOT EXISTS orquestracao.dependencia_agendamento (
  dependencia_agendamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  agendamento_id bigint NOT NULL
    REFERENCES orquestracao.agendamento_coleta(agendamento_id) ON DELETE CASCADE,
  depende_de_agendamento_id bigint NOT NULL
    REFERENCES orquestracao.agendamento_coleta(agendamento_id) ON DELETE CASCADE,
  condicao varchar(40) NOT NULL DEFAULT 'sucesso'
    CHECK (condicao IN ('sucesso','concluido','atualizacao_detectada','qualidade_aprovada','manual')),
  atraso_minimo interval,
  obrigatoria boolean NOT NULL DEFAULT true,
  UNIQUE(agendamento_id, depende_de_agendamento_id),
  CHECK (agendamento_id <> depende_de_agendamento_id)
);

CREATE TABLE IF NOT EXISTS orquestracao.estado_recurso (
  estado_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL UNIQUE
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  politica_efetiva_id bigint
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id),

  ultimo_dado_disponivel_em timestamptz,
  ultima_competencia_disponivel varchar(160),

  ultima_verificacao_em timestamptz,
  ultima_verificacao_status varchar(40),
  proxima_verificacao_em timestamptz,

  ultima_atualizacao_detectada_em timestamptz,
  ultima_publicacao_origem_em timestamptz,
  ultima_ingestao_sucesso_em timestamptz,
  proxima_ingestao_em timestamptz,

  etag_atual varchar(500),
  last_modified_atual timestamptz,
  checksum_atual char(64),
  schema_hash_atual char(64),
  cursor_atual text,

  falhas_consecutivas integer NOT NULL DEFAULT 0,
  status_frescor_id smallint
    REFERENCES referencia.status_frescor_dado(status_frescor_id),

  atraso_atual interval,
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE orquestracao.estado_recurso IS
'Estado materializado usado pelo scheduler. Não substitui o histórico de verificações.';

CREATE TABLE IF NOT EXISTS orquestracao.verificacao_recurso (
  verificacao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  politica_atualizacao_id bigint
    REFERENCES catalogo.politica_atualizacao(politica_atualizacao_id),
  agendamento_id bigint
    REFERENCES orquestracao.agendamento_coleta(agendamento_id),

  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK (status IN ('iniciada','sem_mudanca','mudanca_detectada','indisponivel','falha','cancelada')),

  status_http integer,
  etag_observado varchar(500),
  last_modified_observado timestamptz,
  checksum_observado char(64),
  schema_hash_observado char(64),
  registros_estimados bigint,

  data_publicacao_observada timestamptz,
  competencia_observada varchar(160),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  mensagem text
);

CREATE INDEX IF NOT EXISTS idx_verificacao_recurso_tempo
ON orquestracao.verificacao_recurso(recurso_id, iniciada_em DESC);

CREATE TABLE IF NOT EXISTS orquestracao.atualizacao_detectada (
  atualizacao_detectada_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  verificacao_id uuid NOT NULL
    REFERENCES orquestracao.verificacao_recurso(verificacao_id) ON DELETE CASCADE,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,

  tipo_mudanca varchar(40) NOT NULL
    CHECK (tipo_mudanca IN (
      'novo_periodo','novo_arquivo','conteudo_alterado','schema_alterado',
      'revisao_retroativa','recurso_removido','recurso_restaurado','metadado_alterado'
    )),

  competencia varchar(160),
  periodo_inicio date,
  periodo_fim date,
  versao_origem varchar(160),

  checksum_anterior char(64),
  checksum_novo char(64),
  schema_hash_anterior char(64),
  schema_hash_novo char(64),

  detectada_em timestamptz NOT NULL DEFAULT now(),
  exige_ingestao boolean NOT NULL DEFAULT true,
  exige_reprocessamento boolean NOT NULL DEFAULT false,
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS orquestracao.fila_ingestao (
  item_fila_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  atualizacao_detectada_id uuid
    REFERENCES orquestracao.atualizacao_detectada(atualizacao_detectada_id),
  agendamento_id bigint
    REFERENCES orquestracao.agendamento_coleta(agendamento_id),

  tipo_carga varchar(20) NOT NULL
    CHECK (tipo_carga IN ('completa','incremental','delta','reprocessamento','manual')),
  prioridade smallint NOT NULL DEFAULT 100,
  nao_antes_de timestamptz NOT NULL DEFAULT now(),
  expira_em timestamptz,

  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  status varchar(30) NOT NULL DEFAULT 'pendente'
    CHECK (status IN ('pendente','reservado','executando','sucesso','falha','cancelado','expirado')),

  tentativas integer NOT NULL DEFAULT 0,
  criado_em timestamptz NOT NULL DEFAULT now(),
  reservado_em timestamptz,
  finalizado_em timestamptz
);

CREATE INDEX IF NOT EXISTS idx_fila_ingestao_pronta
ON orquestracao.fila_ingestao(status, nao_antes_de, prioridade)
WHERE status = 'pendente';

CREATE TABLE IF NOT EXISTS orquestracao.execucao_agendada (
  execucao_agendada_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  agendamento_id bigint
    REFERENCES orquestracao.agendamento_coleta(agendamento_id),
  item_fila_id uuid
    REFERENCES orquestracao.fila_ingestao(item_fila_id),
  verificacao_id uuid
    REFERENCES orquestracao.verificacao_recurso(verificacao_id),
  lote_id uuid
    REFERENCES controle.lote_ingestao(lote_id),

  prevista_para timestamptz,
  iniciada_em timestamptz,
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'prevista'
    CHECK (status IN ('prevista','executando','sucesso','parcial','falha','cancelada','ignorada')),

  motivo_ignorada text,
  worker varchar(200),
  duracao_ms bigint,
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS orquestracao.incidente_atraso (
  incidente_atraso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  sla_atualizacao_id bigint
    REFERENCES catalogo.sla_atualizacao(sla_atualizacao_id),

  aberto_em timestamptz NOT NULL DEFAULT now(),
  esperado_em timestamptz,
  atraso_detectado interval,
  severidade varchar(20) NOT NULL
    CHECK (severidade IN ('informativa','baixa','media','alta','critica')),
  status varchar(30) NOT NULL DEFAULT 'aberto'
    CHECK (status IN ('aberto','reconhecido','resolvido','descartado')),

  causa varchar(100),
  descricao text,
  resolvido_em timestamptz,
  resolucao text
);

CREATE INDEX IF NOT EXISTS idx_incidente_atraso_aberto
ON orquestracao.incidente_atraso(recurso_id, aberto_em DESC)
WHERE status IN ('aberto','reconhecido');

CREATE TABLE IF NOT EXISTS orquestracao.historico_periodicidade_observada (
  historico_periodicidade_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  janela_inicio timestamptz NOT NULL,
  janela_fim timestamptz NOT NULL,

  atualizacoes_detectadas integer NOT NULL DEFAULT 0,
  intervalo_medio interval,
  intervalo_mediano interval,
  intervalo_minimo interval,
  intervalo_maximo interval,

  aderencia_politica_percentual numeric(7,4)
    CHECK (aderencia_politica_percentual IS NULL
           OR aderencia_politica_percentual BETWEEN 0 AND 100),

  classificacao_inferida varchar(80),
  calculado_em timestamptz NOT NULL DEFAULT now(),

  CHECK (janela_fim > janela_inicio)
);

