-- --------------------------------------------------------------------------
-- VIEWS: POLÍTICA EFETIVA E PAINEL DO ORQUESTRADOR
-- --------------------------------------------------------------------------

CREATE OR REPLACE VIEW catalogo.v_politica_atualizacao_efetiva AS
WITH candidatos AS (
  SELECT
    r.recurso_id,
    r.conjunto_id,
    c.fonte_id,
    p.politica_atualizacao_id,
    p.nome,
    p.granularidade_temporal_dado,
    p.tipo_periodicidade_origem_id,
    p.intervalo_origem,
    p.tipo_periodicidade_publicacao_id,
    p.intervalo_publicacao,
    p.latencia_publicacao_esperada,
    p.tipo_periodicidade_verificacao_id,
    p.intervalo_verificacao,
    p.tipo_periodicidade_ingestao_id,
    p.intervalo_ingestao,
    p.permite_revisao_retroativa,
    p.periodo_revisavel,
    p.estrategia_revisao,
    p.timezone_fonte,
    p.periodicidade_oficial,
    p.confianca_politica,
    CASE
      WHEN p.recurso_id IS NOT NULL THEN 3
      WHEN p.conjunto_id IS NOT NULL THEN 2
      WHEN p.fonte_id IS NOT NULL THEN 1
      ELSE 0
    END AS nivel_especificidade,
    p.prioridade
  FROM catalogo.recurso_fonte r
  JOIN catalogo.conjunto_dado c ON c.conjunto_id = r.conjunto_id
  JOIN catalogo.politica_atualizacao p
    ON p.ativo = true
   AND p.valido_ate IS NULL
   AND (
        p.recurso_id = r.recurso_id
     OR p.conjunto_id = r.conjunto_id
     OR p.fonte_id = c.fonte_id
   )
)
SELECT DISTINCT ON (recurso_id)
  *
FROM candidatos
ORDER BY recurso_id, nivel_especificidade DESC, prioridade ASC, politica_atualizacao_id DESC;

CREATE OR REPLACE VIEW orquestracao.v_painel_atualizacao AS
SELECT
  f.fonte_id,
  f.codigo AS fonte_codigo,
  f.nome AS fonte_nome,
  c.conjunto_id,
  c.nome AS conjunto_nome,
  r.recurso_id,
  r.nome AS recurso_nome,
  r.url_recurso,

  pe.politica_atualizacao_id,
  pe.granularidade_temporal_dado,
  po.codigo AS periodicidade_origem,
  pp.codigo AS periodicidade_publicacao,
  pv.codigo AS periodicidade_verificacao,
  pi.codigo AS periodicidade_ingestao,

  pe.intervalo_verificacao,
  pe.intervalo_ingestao,
  pe.latencia_publicacao_esperada,
  pe.permite_revisao_retroativa,
  pe.periodo_revisavel,

  e.ultimo_dado_disponivel_em,
  e.ultima_competencia_disponivel,
  e.ultima_verificacao_em,
  e.proxima_verificacao_em,
  e.ultima_atualizacao_detectada_em,
  e.ultima_ingestao_sucesso_em,
  e.proxima_ingestao_em,
  sf.codigo AS status_frescor,
  e.atraso_atual,
  e.falhas_consecutivas

FROM catalogo.recurso_fonte r
JOIN catalogo.conjunto_dado c ON c.conjunto_id = r.conjunto_id
JOIN catalogo.fonte_dado f ON f.fonte_id = c.fonte_id
LEFT JOIN catalogo.v_politica_atualizacao_efetiva pe
  ON pe.recurso_id = r.recurso_id
LEFT JOIN referencia.tipo_periodicidade_atualizacao po
  ON po.tipo_periodicidade_id = pe.tipo_periodicidade_origem_id
LEFT JOIN referencia.tipo_periodicidade_atualizacao pp
  ON pp.tipo_periodicidade_id = pe.tipo_periodicidade_publicacao_id
LEFT JOIN referencia.tipo_periodicidade_atualizacao pv
  ON pv.tipo_periodicidade_id = pe.tipo_periodicidade_verificacao_id
LEFT JOIN referencia.tipo_periodicidade_atualizacao pi
  ON pi.tipo_periodicidade_id = pe.tipo_periodicidade_ingestao_id
LEFT JOIN orquestracao.estado_recurso e
  ON e.recurso_id = r.recurso_id
LEFT JOIN referencia.status_frescor_dado sf
  ON sf.status_frescor_id = e.status_frescor_id;

-- ===== CORE R2.2: FRAMEWORK UNIVERSAL DE INGESTÃO =====

-- ============================================================================
-- ITMT CORE R2.2
-- FRAMEWORK UNIVERSAL DE INGESTÃO
-- PostgreSQL 16+ / PostGIS 3+
--
-- Princípio:
--   O código do conector implementa CAPACIDADES genéricas.
--   O banco declara ONDE, COMO, QUANDO e COM QUAIS REGRAS executar.
--
-- O framework complementa, sem substituir:
--   catalogo.fonte_dado / conjunto_dado / recurso_fonte
--   catalogo.contrato_dado_core
--   catalogo.politica_atualizacao
--   orquestracao.*
--   controle.lote_ingestao / arquivo_coletado / resposta_api_coletada
--   controle.checkpoint_coleta / qualidade / linhagem
--   bruto.*
-- ============================================================================


CREATE SCHEMA IF NOT EXISTS ingestao;

-- --------------------------------------------------------------------------
-- 1. VOCABULÁRIOS DO FRAMEWORK
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.tipo_conector (
  tipo_conector_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  familia varchar(80) NOT NULL,
  protocolo varchar(80),
  descricao text,
  suporta_descoberta boolean NOT NULL DEFAULT false,
  suporta_incremental boolean NOT NULL DEFAULT false,
  suporta_streaming boolean NOT NULL DEFAULT false,
  suporta_geoespacial boolean NOT NULL DEFAULT false,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.capacidade_conector (
  capacidade_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(100) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS ingestao.tipo_conector_capacidade (
  tipo_conector_id smallint NOT NULL
    REFERENCES ingestao.tipo_conector(tipo_conector_id) ON DELETE CASCADE,
  capacidade_id smallint NOT NULL
    REFERENCES ingestao.capacidade_conector(capacidade_id) ON DELETE CASCADE,
  obrigatoria boolean NOT NULL DEFAULT false,
  observacoes text,
  PRIMARY KEY(tipo_conector_id, capacidade_id)
);

CREATE TABLE IF NOT EXISTS ingestao.tipo_parser (
  tipo_parser_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(160) NOT NULL,
  categoria varchar(60) NOT NULL,
  mime_types text[],
  extensoes text[],
  suporta_schema boolean NOT NULL DEFAULT false,
  suporta_streaming boolean NOT NULL DEFAULT false,
  suporta_geometria boolean NOT NULL DEFAULT false,
  descricao text
);

CREATE TABLE IF NOT EXISTS ingestao.tipo_etapa_pipeline (
  tipo_etapa_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  grupo varchar(80) NOT NULL,
  descricao text
);

CREATE TABLE IF NOT EXISTS ingestao.estrategia_incremental (
  estrategia_incremental_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text,
  exige_checkpoint boolean NOT NULL DEFAULT false,
  preserva_historico boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.estrategia_deteccao_mudanca (
  estrategia_deteccao_id smallint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(80) NOT NULL UNIQUE,
  nome varchar(180) NOT NULL,
  descricao text,
  custo_relativo smallint NOT NULL DEFAULT 1 CHECK (custo_relativo BETWEEN 1 AND 5)
);

-- --------------------------------------------------------------------------
-- 2. CONECTOR: INSTÂNCIA, VERSÃO E SEGREDOS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.instancia_conector (
  instancia_conector_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  tipo_conector_id smallint NOT NULL
    REFERENCES ingestao.tipo_conector(tipo_conector_id),

  versao_runtime varchar(100),
  imagem_container varchar(500),
  digest_container varchar(200),
  repositorio_uri text,
  commit_hash varchar(160),

  ambiente varchar(30) NOT NULL DEFAULT 'producao'
    CHECK (ambiente IN ('desenvolvimento','teste','homologacao','producao')),
  modo_execucao varchar(40) NOT NULL DEFAULT 'worker'
    CHECK (modo_execucao IN ('worker','serverless','job','stream','mobile','externo')),

  configuracao_base jsonb NOT NULL DEFAULT '{}'::jsonb,
  habilitado boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now(),
  atualizado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS ingestao.versao_configuracao_conector (
  versao_configuracao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  instancia_conector_id bigint NOT NULL
    REFERENCES ingestao.instancia_conector(instancia_conector_id) ON DELETE CASCADE,
  versao integer NOT NULL,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  schema_configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  hash_configuracao char(64),
  motivo text,
  criado_por varchar(250),
  criado_em timestamptz NOT NULL DEFAULT now(),
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(instancia_conector_id, versao)
);

CREATE TABLE IF NOT EXISTS ingestao.credencial_referencia (
  credencial_referencia_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  provedor_segredo varchar(80) NOT NULL,
  localizador_segredo text NOT NULL,
  chave_versao varchar(160),
  tipo_credencial varchar(80),
  rotacao_recomendada_dias integer,
  ultimo_rotacionamento_em timestamptz,
  expira_em timestamptz,
  ativo boolean NOT NULL DEFAULT true,
  observacoes text,
  criado_em timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE ingestao.credencial_referencia IS
'Contém somente referência a Vault/KMS/secret manager; jamais armazena o segredo material.';

CREATE TABLE IF NOT EXISTS ingestao.perfil_autenticacao (
  perfil_autenticacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  tipo varchar(50) NOT NULL
    CHECK (tipo IN ('nenhuma','api_key','bearer','basic','oauth2_client_credentials',
                    'oauth2_authorization_code','certificado_cliente','aws_sigv4',
                    'ssh_key','token_customizado','clean_room')),
  credencial_referencia_id bigint
    REFERENCES ingestao.credencial_referencia(credencial_referencia_id),
  token_url text,
  scopes text[],
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.vinculo_conector_recurso (
  vinculo_conector_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  instancia_conector_id bigint NOT NULL
    REFERENCES ingestao.instancia_conector(instancia_conector_id),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  perfil_autenticacao_id bigint
    REFERENCES ingestao.perfil_autenticacao(perfil_autenticacao_id),
  prioridade smallint NOT NULL DEFAULT 1,
  finalidade varchar(80) NOT NULL DEFAULT 'coleta',
  valido_desde timestamptz NOT NULL DEFAULT now(),
  valido_ate timestamptz,
  ativo boolean NOT NULL DEFAULT true,
  configuracao_sobrescrita jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(instancia_conector_id, recurso_id, finalidade, valido_desde)
);

CREATE INDEX IF NOT EXISTS idx_vinculo_conector_recurso_ativo
ON ingestao.vinculo_conector_recurso(recurso_id, prioridade)
WHERE ativo = true AND valido_ate IS NULL;

-- --------------------------------------------------------------------------
-- 3. POLÍTICAS TÉCNICAS DE CONEXÃO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.perfil_http (
  perfil_http_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL UNIQUE
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  metodo varchar(10) NOT NULL DEFAULT 'GET',
  timeout_conexao_ms integer NOT NULL DEFAULT 10000,
  timeout_leitura_ms integer NOT NULL DEFAULT 120000,
  timeout_total_ms integer,
  user_agent varchar(300) NOT NULL DEFAULT 'ITMT-Ingestao/1.0',
  headers_publicos jsonb NOT NULL DEFAULT '{}'::jsonb,
  verifica_tls boolean NOT NULL DEFAULT true,
  proxy_referencia text,
  seguir_redirect boolean NOT NULL DEFAULT true,
  max_redirects smallint NOT NULL DEFAULT 5,
  aceita_compressao boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.regra_rate_limit (
  regra_rate_limit_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  requisicoes_por_janela integer,
  janela interval,
  concorrencia_maxima smallint NOT NULL DEFAULT 1,
  respeitar_retry_after boolean NOT NULL DEFAULT true,
  bucket_compartilhado varchar(160),
  margem_seguranca_percentual numeric(7,4) NOT NULL DEFAULT 10,
  UNIQUE(vinculo_conector_recurso_id)
);

CREATE TABLE IF NOT EXISTS ingestao.regra_retry (
  regra_retry_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL UNIQUE
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  max_tentativas smallint NOT NULL DEFAULT 5,
  estrategia varchar(30) NOT NULL DEFAULT 'exponencial_jitter'
    CHECK (estrategia IN ('fixa','linear','exponencial','exponencial_jitter','servidor')),
  espera_inicial_ms integer NOT NULL DEFAULT 1000,
  espera_maxima_ms integer NOT NULL DEFAULT 60000,
  codigos_http_retentaveis integer[] DEFAULT ARRAY[408,425,429,500,502,503,504],
  erros_rede_retentaveis boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.regra_circuit_breaker (
  regra_circuit_breaker_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL UNIQUE
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  falhas_para_abrir smallint NOT NULL DEFAULT 5,
  janela_avaliacao interval NOT NULL DEFAULT interval '10 minutes',
  tempo_aberto interval NOT NULL DEFAULT interval '15 minutes',
  sucessos_para_fechar smallint NOT NULL DEFAULT 2,
  habilitado boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.regra_paginacao (
  regra_paginacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL UNIQUE
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  estrategia varchar(40) NOT NULL
    CHECK (estrategia IN ('nenhuma','offset_limit','page_size','cursor',
                          'next_link','token','object_ids','result_offset',
                          'result_pagination_token','customizada')),
  parametro_offset varchar(120),
  parametro_limite varchar(120),
  parametro_cursor varchar(120),
  caminho_next_link varchar(300),
  caminho_token_resposta varchar(300),
  caminho_fim varchar(300),
  tamanho_pagina integer,
  ordenacao_estavel text,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS ingestao.configuracao_incremental (
  configuracao_incremental_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL UNIQUE
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  estrategia_incremental_id smallint NOT NULL
    REFERENCES ingestao.estrategia_incremental(estrategia_incremental_id),
  campo_watermark varchar(300),
  campo_chave varchar(300),
  parametro_inicio varchar(160),
  parametro_fim varchar(160),
  overlap_reprocessamento interval,
  cursor_inclusivo boolean NOT NULL DEFAULT false,
  ordenacao text,
  filtro_template text,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS ingestao.regra_deteccao_mudanca (
  regra_deteccao_mudanca_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  vinculo_conector_recurso_id bigint NOT NULL
    REFERENCES ingestao.vinculo_conector_recurso(vinculo_conector_recurso_id) ON DELETE CASCADE,
  estrategia_deteccao_id smallint NOT NULL
    REFERENCES ingestao.estrategia_deteccao_mudanca(estrategia_deteccao_id),
  ordem smallint NOT NULL DEFAULT 1,
  campo_metadado varchar(300),
  algoritmo_hash varchar(30) DEFAULT 'sha256',
  amostragem_bytes bigint,
  expressao_customizada text,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(vinculo_conector_recurso_id, ordem)
);

CREATE TABLE IF NOT EXISTS ingestao.regra_deduplicacao (
  regra_deduplicacao_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  codigo varchar(120) NOT NULL,
  escopo varchar(40) NOT NULL
    CHECK (escopo IN ('arquivo','pagina','registro','objeto','competencia','lote')),
  estrategia varchar(50) NOT NULL
    CHECK (estrategia IN ('sha256','chave_natural','hash_campos','versao_origem','uri_etag','customizada')),
  campos text[],
  expressao text,
  janela interval,
  acao_duplicado varchar(30) NOT NULL DEFAULT 'ignorar'
    CHECK (acao_duplicado IN ('ignorar','versionar','atualizar','quarentena','erro')),
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(recurso_id, codigo)
);

-- --------------------------------------------------------------------------
-- 4. DESCOBERTA DINÂMICA DE DATASETS/RECURSOS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.regra_descoberta_recurso (
  regra_descoberta_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  instancia_conector_id bigint NOT NULL
    REFERENCES ingestao.instancia_conector(instancia_conector_id) ON DELETE CASCADE,
  fonte_id bigint REFERENCES catalogo.fonte_dado(fonte_id),
  conjunto_pai_id bigint REFERENCES catalogo.conjunto_dado(conjunto_id),
  codigo varchar(160) NOT NULL,
  endpoint_catalogo text,
  expressao_selecao text,
  caminho_itens varchar(300),
  caminho_identificador varchar(300),
  caminho_nome varchar(300),
  caminho_url varchar(300),
  caminho_formato varchar(300),
  criar_conjunto_automaticamente boolean NOT NULL DEFAULT false,
  criar_recurso_automaticamente boolean NOT NULL DEFAULT false,
  exige_homologacao boolean NOT NULL DEFAULT true,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(instancia_conector_id, codigo)
);

CREATE TABLE IF NOT EXISTS ingestao.execucao_descoberta (
  execucao_descoberta_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  regra_descoberta_id bigint NOT NULL
    REFERENCES ingestao.regra_descoberta_recurso(regra_descoberta_id),
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK (status IN ('iniciada','sucesso','parcial','falha','cancelada')),
  itens_encontrados integer NOT NULL DEFAULT 0,
  itens_novos integer NOT NULL DEFAULT 0,
  itens_alterados integer NOT NULL DEFAULT 0,
  itens_removidos integer NOT NULL DEFAULT 0,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  mensagem text
);

CREATE TABLE IF NOT EXISTS ingestao.recurso_descoberto (
  recurso_descoberto_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_descoberta_id uuid NOT NULL
    REFERENCES ingestao.execucao_descoberta(execucao_descoberta_id) ON DELETE CASCADE,
  identificador_origem text NOT NULL,
  nome varchar(500),
  url_recurso text,
  formato varchar(100),
  mime_type varchar(160),
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  assinatura char(64),
  recurso_catalogado_id bigint
    REFERENCES catalogo.recurso_fonte(recurso_id),
  status varchar(30) NOT NULL DEFAULT 'novo'
    CHECK (status IN ('novo','inalterado','alterado','removido','homologado','ignorado')),
  detectado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(execucao_descoberta_id, identificador_origem)
);

-- --------------------------------------------------------------------------
-- 5. PARSING E DESCOBERTA DE SCHEMA
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.configuracao_parser (
  configuracao_parser_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  tipo_parser_id smallint NOT NULL
    REFERENCES ingestao.tipo_parser(tipo_parser_id),
  nome varchar(180) NOT NULL,
  encoding varchar(40),
  separador varchar(20),
  quote_char varchar(10),
  escape_char varchar(10),
  possui_cabecalho boolean,
  linha_cabecalho integer,
  caminho_raiz varchar(500),
  caminho_registros varchar(500),
  srid_origem integer,
  geometria_caminho varchar(300),
  timezone_dados varchar(100),
  locale varchar(40),
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(recurso_id, nome)
);

CREATE TABLE IF NOT EXISTS ingestao.schema_observado (
  schema_observado_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  execucao_pipeline_id uuid,
  detectado_em timestamptz NOT NULL DEFAULT now(),
  schema_hash char(64) NOT NULL,
  schema_json jsonb NOT NULL DEFAULT '{}'::jsonb,
  quantidade_campos integer,
  versao_origem varchar(160),
  versao_contrato_core_id bigint
    REFERENCES catalogo.versao_contrato_dado_core(versao_contrato_core_id),
  compatibilidade varchar(40)
    CHECK (compatibilidade IN ('identico','retrocompativel','compativel_com_alerta',
                               'breaking_change','desconhecido')),
  UNIQUE(recurso_id, schema_hash)
);

CREATE TABLE IF NOT EXISTS ingestao.campo_schema_observado (
  campo_schema_observado_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  schema_observado_id uuid NOT NULL
    REFERENCES ingestao.schema_observado(schema_observado_id) ON DELETE CASCADE,
  caminho varchar(500) NOT NULL,
  nome varchar(300),
  tipo_detectado varchar(120),
  nulavel boolean,
  cardinalidade varchar(80),
  exemplo jsonb,
  ordem integer,
  estatisticas jsonb NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE(schema_observado_id, caminho)
);

CREATE TABLE IF NOT EXISTS ingestao.versao_mapeamento (
  versao_mapeamento_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  versao varchar(80) NOT NULL,
  versao_contrato_core_id bigint
    REFERENCES catalogo.versao_contrato_dado_core(versao_contrato_core_id),
  schema_origem_hash char(64),
  status varchar(30) NOT NULL DEFAULT 'rascunho'
    CHECK (status IN ('rascunho','teste','homologado','ativo','desativado')),
  compatibilidade varchar(40),
  valido_desde timestamptz,
  valido_ate timestamptz,
  criado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(recurso_id, versao)
);

-- Integra o mapeamento já existente ao versionamento do R2.2.
ALTER TABLE catalogo.mapeamento_campo
  ADD COLUMN IF NOT EXISTS versao_mapeamento_id bigint
    REFERENCES ingestao.versao_mapeamento(versao_mapeamento_id),
  ADD COLUMN IF NOT EXISTS ordem_execucao integer,
  ADD COLUMN IF NOT EXISTS tratamento_erro varchar(30) DEFAULT 'rejeitar'
    CHECK (tratamento_erro IN ('rejeitar','nulo','default','quarentena','falhar_lote'));

-- --------------------------------------------------------------------------
-- 6. PIPELINES DECLARATIVOS
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.pipeline (
  pipeline_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  descricao text,
  tipo_conector_id smallint
    REFERENCES ingestao.tipo_conector(tipo_conector_id),
  reutilizavel boolean NOT NULL DEFAULT true,
  criticidade varchar(30) NOT NULL DEFAULT 'media',
  ativo boolean NOT NULL DEFAULT true,
  criado_em timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS ingestao.versao_pipeline (
  versao_pipeline_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  pipeline_id bigint NOT NULL
    REFERENCES ingestao.pipeline(pipeline_id) ON DELETE CASCADE,
  versao varchar(80) NOT NULL,
  status varchar(30) NOT NULL DEFAULT 'rascunho'
    CHECK (status IN ('rascunho','teste','homologado','ativo','desativado')),
  estrategia_falha varchar(40) NOT NULL DEFAULT 'parar'
    CHECK (estrategia_falha IN ('parar','continuar','parcial','quarentena','rollback')),
  parametros jsonb NOT NULL DEFAULT '{}'::jsonb,
  hash_definicao char(64),
  valido_desde timestamptz,
  valido_ate timestamptz,
  criado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(pipeline_id, versao)
);

CREATE TABLE IF NOT EXISTS ingestao.etapa_pipeline (
  etapa_pipeline_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  versao_pipeline_id bigint NOT NULL
    REFERENCES ingestao.versao_pipeline(versao_pipeline_id) ON DELETE CASCADE,
  codigo varchar(120) NOT NULL,
  nome varchar(250) NOT NULL,
  tipo_etapa_id smallint NOT NULL
    REFERENCES ingestao.tipo_etapa_pipeline(tipo_etapa_id),
  ordem integer,
  executor varchar(160),
  timeout interval,
  max_tentativas smallint,
  condicao_execucao text,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  obrigatoria boolean NOT NULL DEFAULT true,
  idempotente boolean NOT NULL DEFAULT true,
  permite_paralelismo boolean NOT NULL DEFAULT false,
  UNIQUE(versao_pipeline_id, codigo)
);

CREATE TABLE IF NOT EXISTS ingestao.dependencia_etapa_pipeline (
  dependencia_etapa_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  etapa_pipeline_id bigint NOT NULL
    REFERENCES ingestao.etapa_pipeline(etapa_pipeline_id) ON DELETE CASCADE,
  depende_de_etapa_id bigint NOT NULL
    REFERENCES ingestao.etapa_pipeline(etapa_pipeline_id) ON DELETE CASCADE,
  condicao varchar(40) NOT NULL DEFAULT 'sucesso'
    CHECK (condicao IN ('sucesso','concluida','mudanca_detectada',
                        'contrato_aprovado','qualidade_aprovada','sempre')),
  UNIQUE(etapa_pipeline_id, depende_de_etapa_id),
  CHECK (etapa_pipeline_id <> depende_de_etapa_id)
);

CREATE TABLE IF NOT EXISTS ingestao.vinculo_pipeline_recurso (
  vinculo_pipeline_recurso_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  versao_pipeline_id bigint NOT NULL
    REFERENCES ingestao.versao_pipeline(versao_pipeline_id),
  prioridade smallint NOT NULL DEFAULT 1,
  tipo_carga varchar(30)
    CHECK (tipo_carga IN ('completa','incremental','delta','reprocessamento','manual')),
  ativo boolean NOT NULL DEFAULT true,
  valido_desde timestamptz NOT NULL DEFAULT now(),
  valido_ate timestamptz,
  UNIQUE(recurso_id, versao_pipeline_id, tipo_carga, valido_desde)
);

CREATE TABLE IF NOT EXISTS ingestao.execucao_pipeline (
  execucao_pipeline_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  versao_pipeline_id bigint NOT NULL
    REFERENCES ingestao.versao_pipeline(versao_pipeline_id),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id),
  instancia_conector_id bigint
    REFERENCES ingestao.instancia_conector(instancia_conector_id),
  item_fila_id uuid
    REFERENCES orquestracao.fila_ingestao(item_fila_id),
  atualizacao_detectada_id uuid
    REFERENCES orquestracao.atualizacao_detectada(atualizacao_detectada_id),
  lote_id uuid
    REFERENCES controle.lote_ingestao(lote_id),

  chave_idempotencia varchar(500),
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK (status IN ('iniciada','sucesso','parcial','falha','cancelada','quarentena')),
  parametros_efetivos jsonb NOT NULL DEFAULT '{}'::jsonb,
  checkpoint_entrada jsonb NOT NULL DEFAULT '{}'::jsonb,
  checkpoint_saida jsonb NOT NULL DEFAULT '{}'::jsonb,
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb,
  log_uri text,
  worker varchar(250)
);

CREATE INDEX IF NOT EXISTS idx_execucao_pipeline_recurso_tempo
ON ingestao.execucao_pipeline(recurso_id, iniciada_em DESC);

CREATE UNIQUE INDEX IF NOT EXISTS uq_execucao_pipeline_idempotencia
ON ingestao.execucao_pipeline(recurso_id, chave_idempotencia)
WHERE chave_idempotencia IS NOT NULL
  AND status IN ('iniciada','sucesso','parcial');

CREATE TABLE IF NOT EXISTS ingestao.execucao_etapa_pipeline (
  execucao_etapa_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id) ON DELETE CASCADE,
  etapa_pipeline_id bigint NOT NULL
    REFERENCES ingestao.etapa_pipeline(etapa_pipeline_id),
  execucao_carga_id uuid
    REFERENCES controle.execucao_carga(execucao_id),
  tentativa smallint NOT NULL DEFAULT 1,
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK (status IN ('iniciada','sucesso','parcial','falha','cancelada','ignorada','quarentena')),
  entrada jsonb NOT NULL DEFAULT '{}'::jsonb,
  saida jsonb NOT NULL DEFAULT '{}'::jsonb,
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb,
  mensagem text,
  UNIQUE(execucao_pipeline_id, etapa_pipeline_id, tentativa)
);

CREATE TABLE IF NOT EXISTS ingestao.tentativa_requisicao (
  tentativa_requisicao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_etapa_id uuid NOT NULL
    REFERENCES ingestao.execucao_etapa_pipeline(execucao_etapa_id) ON DELETE CASCADE,
  tentativa smallint NOT NULL,
  metodo varchar(10),
  url_sanitizada text,
  headers_requisicao_sanitizados jsonb NOT NULL DEFAULT '{}'::jsonb,
  status_http integer,
  headers_resposta_sanitizados jsonb NOT NULL DEFAULT '{}'::jsonb,
  bytes_recebidos bigint,
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  erro_classe varchar(160),
  erro_mensagem text,
  retry_after interval,
  UNIQUE(execucao_etapa_id, tentativa)
);

COMMENT ON TABLE ingestao.tentativa_requisicao IS
'Log de transporte com URL/cabeçalhos sanitizados; nunca persistir tokens, cookies ou segredos.';

-- --------------------------------------------------------------------------
-- 7. MANIFESTO, IDEMPOTÊNCIA, CHECKPOINT E LEASE
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.manifesto_captura (
  manifesto_captura_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL UNIQUE
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id) ON DELETE CASCADE,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id),
  versao_recurso_id bigint
    REFERENCES catalogo.versao_recurso(versao_recurso_id),
  criado_em timestamptz NOT NULL DEFAULT now(),
  algoritmo_hash varchar(30) NOT NULL DEFAULT 'sha256',
  hash_manifesto char(64),
  quantidade_itens integer NOT NULL DEFAULT 0,
  total_bytes bigint NOT NULL DEFAULT 0,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS ingestao.item_manifesto_captura (
  item_manifesto_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  manifesto_captura_id uuid NOT NULL
    REFERENCES ingestao.manifesto_captura(manifesto_captura_id) ON DELETE CASCADE,
  tipo varchar(40) NOT NULL
    CHECK (tipo IN ('arquivo','resposta_api','pagina','objeto','documento','tile','chunk','stream','outro')),
  identificador_origem text,
  uri_origem text,
  uri_armazenamento text,
  sha256 char(64),
  etag varchar(500),
  last_modified timestamptz,
  tamanho_bytes bigint,
  mime_type varchar(160),
  arquivo_id uuid REFERENCES controle.arquivo_coletado(arquivo_id),
  resposta_id uuid REFERENCES controle.resposta_api_coletada(resposta_id),
  ordem bigint,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE INDEX IF NOT EXISTS idx_item_manifesto_hash
ON ingestao.item_manifesto_captura(sha256)
WHERE sha256 IS NOT NULL;

CREATE TABLE IF NOT EXISTS ingestao.chave_idempotencia (
  chave_idempotencia_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  chave varchar(500) NOT NULL,
  escopo varchar(40) NOT NULL,
  hash_parametros char(64),
  primeira_execucao_id uuid
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  ultima_execucao_id uuid
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  status varchar(30) NOT NULL DEFAULT 'reservada'
    CHECK (status IN ('reservada','processando','concluida','falha','expirada')),
  criada_em timestamptz NOT NULL DEFAULT now(),
  expira_em timestamptz,
  UNIQUE(recurso_id, chave)
);

CREATE TABLE IF NOT EXISTS ingestao.lease_recurso (
  lease_recurso_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  finalidade varchar(80) NOT NULL DEFAULT 'ingestao',
  proprietario varchar(250) NOT NULL,
  adquirido_em timestamptz NOT NULL DEFAULT now(),
  expira_em timestamptz NOT NULL,
  heartbeat_em timestamptz NOT NULL DEFAULT now(),
  liberado_em timestamptz,
  UNIQUE(recurso_id, finalidade)
);

CREATE TABLE IF NOT EXISTS ingestao.checkpoint_candidato (
  checkpoint_candidato_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id) ON DELETE CASCADE,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  chave varchar(200) NOT NULL,
  valor_anterior text,
  valor_candidato text,
  valor_json jsonb,
  status varchar(30) NOT NULL DEFAULT 'candidato'
    CHECK (status IN ('candidato','confirmado','descartado')),
  criado_em timestamptz NOT NULL DEFAULT now(),
  confirmado_em timestamptz,
  UNIQUE(execucao_pipeline_id, chave)
);

CREATE TABLE IF NOT EXISTS ingestao.historico_checkpoint (
  historico_checkpoint_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id) ON DELETE CASCADE,
  checkpoint_id bigint
    REFERENCES controle.checkpoint_coleta(checkpoint_id),
  execucao_pipeline_id uuid
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  chave varchar(200) NOT NULL,
  valor_anterior text,
  valor_novo text,
  confirmado_em timestamptz NOT NULL DEFAULT now(),
  motivo varchar(160),
  hash_estado char(64)
);

ALTER TABLE controle.checkpoint_coleta
  ADD COLUMN IF NOT EXISTS tipo_checkpoint varchar(40) DEFAULT 'customizado',
  ADD COLUMN IF NOT EXISTS valor_json jsonb,
  ADD COLUMN IF NOT EXISTS confirmado_em timestamptz,
  ADD COLUMN IF NOT EXISTS execucao_pipeline_id uuid
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id);

-- --------------------------------------------------------------------------
-- 8. QUARENTENA E HOMOLOGAÇÃO
-- --------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS ingestao.item_quarentena (
  item_quarentena_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid
    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  execucao_etapa_id uuid
    REFERENCES ingestao.execucao_etapa_pipeline(execucao_etapa_id),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id),
  objeto_id uuid REFERENCES bruto.objeto_coletado(objeto_id),
  item_manifesto_id uuid
    REFERENCES ingestao.item_manifesto_captura(item_manifesto_id),

  motivo_codigo varchar(120) NOT NULL,
  motivo text NOT NULL,
  severidade varchar(20) NOT NULL
    CHECK (severidade IN ('info','aviso','erro','critico')),
  payload_amostra jsonb,
  uri_evidencia text,

  status varchar(30) NOT NULL DEFAULT 'aberto'
    CHECK (status IN ('aberto','em_analise','liberado','corrigido','descartado')),
  criado_em timestamptz NOT NULL DEFAULT now(),
  resolvido_em timestamptz
);

CREATE INDEX IF NOT EXISTS idx_quarentena_aberta
ON ingestao.item_quarentena(recurso_id, criado_em DESC)
WHERE status IN ('aberto','em_analise');

CREATE TABLE IF NOT EXISTS ingestao.decisao_quarentena (
  decisao_quarentena_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  item_quarentena_id uuid NOT NULL
    REFERENCES ingestao.item_quarentena(item_quarentena_id) ON DELETE CASCADE,
  decisao varchar(30) NOT NULL
    CHECK (decisao IN ('liberar','corrigir_reprocessar','descartar','escalar','manter')),
  justificativa text NOT NULL,
  decidido_por varchar(250) NOT NULL,
  decidido_em timestamptz NOT NULL DEFAULT now(),
  parametros_reprocessamento jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS ingestao.teste_conector (
  teste_conector_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  categoria varchar(80) NOT NULL,
  descricao text,
  bloqueante boolean NOT NULL DEFAULT false,
  configuracao jsonb NOT NULL DEFAULT '{}'::jsonb,
  ativo boolean NOT NULL DEFAULT true
);

CREATE TABLE IF NOT EXISTS ingestao.resultado_teste_conector (
  resultado_teste_conector_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  instancia_conector_id bigint NOT NULL
    REFERENCES ingestao.instancia_conector(instancia_conector_id) ON DELETE CASCADE,
  recurso_id bigint
    REFERENCES catalogo.recurso_fonte(recurso_id),
  teste_conector_id bigint NOT NULL
    REFERENCES ingestao.teste_conector(teste_conector_id),
  executado_em timestamptz NOT NULL DEFAULT now(),
  aprovado boolean NOT NULL,
  duracao_ms bigint,
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb,
  mensagem text
);

CREATE TABLE IF NOT EXISTS ingestao.homologacao_conector (
  homologacao_conector_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  instancia_conector_id bigint NOT NULL
    REFERENCES ingestao.instancia_conector(instancia_conector_id),
  recurso_id bigint
    REFERENCES catalogo.recurso_fonte(recurso_id),
  versao_configuracao_id bigint
    REFERENCES ingestao.versao_configuracao_conector(versao_configuracao_id),
  versao_pipeline_id bigint
    REFERENCES ingestao.versao_pipeline(versao_pipeline_id),
  status varchar(30) NOT NULL DEFAULT 'pendente'
    CHECK (status IN ('pendente','aprovado','reprovado','expirado','revogado')),
  homologado_por varchar(250),
  homologado_em timestamptz,
  valido_ate timestamptz,
  criterios jsonb NOT NULL DEFAULT '{}'::jsonb,
  observacoes text
);

-- --------------------------------------------------------------------------
-- 9. INTEGRAÇÃO COM ORQUESTRAÇÃO E DETECÇÃO DO R2.1
-- --------------------------------------------------------------------------

ALTER TABLE orquestracao.fila_ingestao
  ADD COLUMN IF NOT EXISTS instancia_conector_id bigint
    REFERENCES ingestao.instancia_conector(instancia_conector_id),
  ADD COLUMN IF NOT EXISTS versao_pipeline_id bigint
    REFERENCES ingestao.versao_pipeline(versao_pipeline_id),
  ADD COLUMN IF NOT EXISTS chave_idempotencia varchar(500);

ALTER TABLE orquestracao.atualizacao_detectada
  ADD COLUMN IF NOT EXISTS regra_deteccao_mudanca_id bigint
    REFERENCES ingestao.regra_deteccao_mudanca(regra_deteccao_mudanca_id),
  ADD COLUMN IF NOT EXISTS confianca_deteccao numeric(8,6);

ALTER TABLE catalogo.recurso_fonte
  ADD COLUMN IF NOT EXISTS checksum_algoritmo_preferencial varchar(30) DEFAULT 'sha256',
  ADD COLUMN IF NOT EXISTS exige_preservacao_bruto boolean NOT NULL DEFAULT true,
  ADD COLUMN IF NOT EXISTS permite_descoberta_schema boolean NOT NULL DEFAULT true;

