INSERT INTO ingestao.etapa_pipeline
(versao_pipeline_id,codigo,nome,tipo_etapa_id,ordem,obrigatoria,idempotente)
SELECT vp.versao_pipeline_id, ps.codigo, ps.nome, te.tipo_etapa_id,
       ps.ordem, ps.obrigatoria, true
FROM passos ps
JOIN ingestao.pipeline p ON p.codigo=ps.pipeline_codigo
JOIN ingestao.versao_pipeline vp ON vp.pipeline_id=p.pipeline_id AND vp.versao='1.0'
JOIN ingestao.tipo_etapa_pipeline te ON te.codigo=ps.tipo_codigo
ON CONFLICT (versao_pipeline_id,codigo) DO NOTHING;

INSERT INTO ingestao.dependencia_etapa_pipeline
(etapa_pipeline_id,depende_de_etapa_id,condicao)
SELECT atual.etapa_pipeline_id, anterior.etapa_pipeline_id, 'concluida'
FROM ingestao.etapa_pipeline atual
JOIN ingestao.etapa_pipeline anterior
  ON anterior.versao_pipeline_id=atual.versao_pipeline_id
 AND anterior.ordem=(
   SELECT max(x.ordem)
   FROM ingestao.etapa_pipeline x
   WHERE x.versao_pipeline_id=atual.versao_pipeline_id
     AND x.ordem < atual.ordem
 )
ON CONFLICT (etapa_pipeline_id,depende_de_etapa_id) DO NOTHING;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname='fk_schema_observado_execucao_pipeline'
      AND conrelid='ingestao.schema_observado'::regclass
  ) THEN
    ALTER TABLE ingestao.schema_observado
      ADD CONSTRAINT fk_schema_observado_execucao_pipeline
      FOREIGN KEY (execucao_pipeline_id)
      REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id);
  END IF;
END $$;

-- --------------------------------------------------------------------------
-- 14. VIEW E FUNÇÃO: "O CONECTOR PERGUNTA AO BANCO COMO EXECUTAR"
-- --------------------------------------------------------------------------

CREATE OR REPLACE VIEW ingestao.v_plano_execucao_recurso AS
SELECT
  f.fonte_id,
  f.codigo AS fonte_codigo,
  f.nome AS fonte_nome,
  c.conjunto_id,
  c.codigo_origem AS conjunto_codigo_origem,
  c.nome AS conjunto_nome,
  r.recurso_id,
  r.codigo_origem AS recurso_codigo_origem,
  r.nome AS recurso_nome,
  r.url_recurso,
  r.formato,
  r.tipo_recurso,
  r.metodo_http,

  pe.politica_atualizacao_id,
  pe.granularidade_temporal_dado,
  pe.intervalo_verificacao,
  pe.intervalo_ingestao,
  pe.latencia_publicacao_esperada,
  pe.permite_revisao_retroativa,
  pe.periodo_revisavel,
  pe.estrategia_revisao,
  pe.timezone_fonte,

  vcr.vinculo_conector_recurso_id,
  ic.instancia_conector_id,
  ic.codigo AS conector_codigo,
  tc.codigo AS tipo_conector,
  ic.versao_runtime,
  ic.imagem_container,
  ic.digest_container,
  ic.configuracao_base || vcr.configuracao_sobrescrita AS configuracao_conector,
  pa.tipo AS tipo_autenticacao,

  ph.metodo AS http_metodo,
  ph.timeout_conexao_ms,
  ph.timeout_leitura_ms,
  ph.timeout_total_ms,
  ph.user_agent,
  ph.headers_publicos,
  ph.verifica_tls,

  rl.requisicoes_por_janela,
  rl.janela AS rate_limit_janela,
  rl.concorrencia_maxima,

  rr.max_tentativas AS retry_max_tentativas,
  rr.estrategia AS retry_estrategia,
  rr.espera_inicial_ms AS retry_espera_inicial_ms,
  rr.espera_maxima_ms AS retry_espera_maxima_ms,

  rp.estrategia AS paginacao_estrategia,
  rp.tamanho_pagina,
  rp.configuracao AS paginacao_configuracao,

  ei.codigo AS incremental_estrategia,
  ci.campo_watermark,
  ci.campo_chave,
  ci.overlap_reprocessamento,

  cp.configuracao_parser_id,
  tp.codigo AS parser_codigo,
  cp.configuracao AS parser_configuracao,

  vpr.versao_pipeline_id,
  p.codigo AS pipeline_codigo,
  vp.versao AS pipeline_versao,

  e.ultima_verificacao_em,
  e.proxima_verificacao_em,
  e.ultima_atualizacao_detectada_em,
  e.ultima_ingestao_sucesso_em,
  e.status_frescor_id,

  r.exige_preservacao_bruto,
  r.permite_descoberta_schema

FROM catalogo.recurso_fonte r
JOIN catalogo.conjunto_dado c ON c.conjunto_id=r.conjunto_id
JOIN catalogo.fonte_dado f ON f.fonte_id=c.fonte_id
LEFT JOIN catalogo.v_politica_atualizacao_efetiva pe
  ON pe.recurso_id=r.recurso_id
LEFT JOIN LATERAL (
  SELECT x.*
  FROM ingestao.vinculo_conector_recurso x
  WHERE x.recurso_id=r.recurso_id
    AND x.ativo=true
    AND x.valido_ate IS NULL
  ORDER BY x.prioridade, x.vinculo_conector_recurso_id DESC
  LIMIT 1
) vcr ON true
LEFT JOIN ingestao.instancia_conector ic
  ON ic.instancia_conector_id=vcr.instancia_conector_id
LEFT JOIN ingestao.tipo_conector tc
  ON tc.tipo_conector_id=ic.tipo_conector_id
LEFT JOIN ingestao.perfil_autenticacao pa
  ON pa.perfil_autenticacao_id=vcr.perfil_autenticacao_id
LEFT JOIN ingestao.perfil_http ph
  ON ph.vinculo_conector_recurso_id=vcr.vinculo_conector_recurso_id
LEFT JOIN ingestao.regra_rate_limit rl
  ON rl.vinculo_conector_recurso_id=vcr.vinculo_conector_recurso_id
LEFT JOIN ingestao.regra_retry rr
  ON rr.vinculo_conector_recurso_id=vcr.vinculo_conector_recurso_id
LEFT JOIN ingestao.regra_paginacao rp
  ON rp.vinculo_conector_recurso_id=vcr.vinculo_conector_recurso_id
LEFT JOIN ingestao.configuracao_incremental ci
  ON ci.vinculo_conector_recurso_id=vcr.vinculo_conector_recurso_id
LEFT JOIN ingestao.estrategia_incremental ei
  ON ei.estrategia_incremental_id=ci.estrategia_incremental_id
LEFT JOIN LATERAL (
  SELECT x.*
  FROM ingestao.configuracao_parser x
  WHERE x.recurso_id=r.recurso_id AND x.ativo=true
  ORDER BY x.configuracao_parser_id DESC
  LIMIT 1
) cp ON true
LEFT JOIN ingestao.tipo_parser tp
  ON tp.tipo_parser_id=cp.tipo_parser_id
LEFT JOIN LATERAL (
  SELECT x.*
  FROM ingestao.vinculo_pipeline_recurso x
  WHERE x.recurso_id=r.recurso_id
    AND x.ativo=true
    AND x.valido_ate IS NULL
  ORDER BY x.prioridade, x.vinculo_pipeline_recurso_id DESC
  LIMIT 1
) vpr ON true
LEFT JOIN ingestao.versao_pipeline vp
  ON vp.versao_pipeline_id=vpr.versao_pipeline_id
LEFT JOIN ingestao.pipeline p
  ON p.pipeline_id=vp.pipeline_id
LEFT JOIN orquestracao.estado_recurso e
  ON e.recurso_id=r.recurso_id;

CREATE OR REPLACE FUNCTION ingestao.obter_plano_execucao(p_recurso_id bigint)
RETURNS jsonb
LANGUAGE sql
STABLE
AS $$
  SELECT to_jsonb(v)
  FROM ingestao.v_plano_execucao_recurso v
  WHERE v.recurso_id=p_recurso_id;
$$;

COMMENT ON FUNCTION ingestao.obter_plano_execucao(bigint) IS
'Retorna em JSON o plano efetivo: onde buscar, quando, conector, auth, timeouts, paginação, incremental, parser e pipeline.';

CREATE OR REPLACE VIEW ingestao.v_saude_conectores AS
SELECT
  ic.instancia_conector_id,
  ic.codigo,
  ic.nome,
  tc.codigo AS tipo_conector,
  ic.ambiente,
  ic.habilitado,
  count(DISTINCT vcr.recurso_id) AS recursos_vinculados,
  max(rtc.executado_em) AS ultimo_teste_em,
  bool_and(rtc.aprovado) FILTER (
    WHERE rtc.executado_em >= now() - interval '30 days'
  ) AS testes_recentes_aprovados,
  count(*) FILTER (
    WHERE rtc.aprovado=false
      AND rtc.executado_em >= now() - interval '30 days'
  ) AS falhas_teste_30d
FROM ingestao.instancia_conector ic
JOIN ingestao.tipo_conector tc
  ON tc.tipo_conector_id=ic.tipo_conector_id
LEFT JOIN ingestao.vinculo_conector_recurso vcr
  ON vcr.instancia_conector_id=ic.instancia_conector_id AND vcr.ativo=true
LEFT JOIN ingestao.resultado_teste_conector rtc
  ON rtc.instancia_conector_id=ic.instancia_conector_id
GROUP BY ic.instancia_conector_id,ic.codigo,ic.nome,tc.codigo,ic.ambiente,ic.habilitado;

