CREATE TABLE IF NOT EXISTS ingestao.execucao_validacao_contrato (
  execucao_validacao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id) ON DELETE CASCADE,
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
  versao_contrato_core_id bigint REFERENCES catalogo.versao_contrato_dado_core(versao_contrato_core_id),
  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK (status IN ('iniciada','aprovada','aprovada_com_alerta','reprovada','falha')),
  registros_avaliados bigint NOT NULL DEFAULT 0,
  registros_validos bigint NOT NULL DEFAULT 0,
  registros_invalidos bigint NOT NULL DEFAULT 0,
  taxa_validade numeric(8,6),
  schema_hash_observado char(64),
  metricas jsonb NOT NULL DEFAULT '{}'::jsonb
);

CREATE TABLE IF NOT EXISTS ingestao.violacao_contrato (
  violacao_contrato_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  execucao_validacao_id uuid NOT NULL REFERENCES ingestao.execucao_validacao_contrato(execucao_validacao_id) ON DELETE CASCADE,
  indice_registro bigint,
  caminho_campo varchar(500),
  codigo varchar(120) NOT NULL,
  severidade varchar(20) NOT NULL CHECK (severidade IN ('info','aviso','erro','critico')),
  mensagem text NOT NULL,
  valor_amostra text,
  bloqueante boolean NOT NULL DEFAULT false,
  criada_em timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_violacao_contrato_execucao
ON ingestao.violacao_contrato(execucao_validacao_id,bloqueante,severidade);

CREATE TABLE IF NOT EXISTS ingestao.quality_gate_execucao (
  quality_gate_execucao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id) ON DELETE CASCADE,
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
  codigo_gate varchar(120) NOT NULL,
  nome varchar(250) NOT NULL,
  valor_observado numeric(30,12),
  operador varchar(10) NOT NULL CHECK (operador IN ('>=','>','=','<=','<','!=','custom')),
  limite numeric(30,12),
  aprovado boolean NOT NULL,
  bloqueante boolean NOT NULL DEFAULT true,
  detalhes jsonb NOT NULL DEFAULT '{}'::jsonb,
  avaliado_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(execucao_pipeline_id,codigo_gate)
);

CREATE TABLE IF NOT EXISTS ingestao.publicacao_produto_execucao (
  publicacao_produto_execucao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  versao_produto_dado_id bigint NOT NULL REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
  registros_publicados bigint NOT NULL DEFAULT 0,
  registros_quarentena bigint NOT NULL DEFAULT 0,
  conteudo_hash char(64),
  status varchar(30) NOT NULL DEFAULT 'publicada'
    CHECK (status IN ('publicada','parcial','bloqueada','revogada')),
  publicada_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(execucao_pipeline_id,produto_dado_id)
);

CREATE TABLE IF NOT EXISTS semantico.evidencia_ingestao (
  evidencia_ingestao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_pipeline_id uuid NOT NULL REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  produto_dado_id bigint NOT NULL REFERENCES catalogo.produto_dado(produto_dado_id),
  versao_produto_dado_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  recurso_id bigint NOT NULL REFERENCES catalogo.recurso_fonte(recurso_id),
  observacao_id bigint REFERENCES dw.fato_observacao(observacao_id),
  objeto_dado_id uuid REFERENCES controle.objeto_dado(objeto_dado_id),
  tipo varchar(80) NOT NULL DEFAULT 'ingestao',
  titulo varchar(500),
  url_origem text,
  data_coleta timestamptz NOT NULL DEFAULT now(),
  checksum char(64),
  confianca numeric(8,6),
  publicavel boolean NOT NULL DEFAULT true,
  metadados jsonb NOT NULL DEFAULT '{}'::jsonb,
  CHECK(num_nonnulls(versao_produto_dado_id,observacao_id,objeto_dado_id) >= 1)
);

ALTER TABLE integracao.ibge_sidra_observacao
  ADD COLUMN IF NOT EXISTS execucao_pipeline_id uuid REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  ADD COLUMN IF NOT EXISTS versao_produto_dado_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
  ADD COLUMN IF NOT EXISTS numero_linha bigint,
  ADD COLUMN IF NOT EXISTS status_valor varchar(40) DEFAULT 'valor',
  ADD COLUMN IF NOT EXISTS sha256_registro char(64),
  ADD COLUMN IF NOT EXISTS publicavel boolean NOT NULL DEFAULT true;

CREATE UNIQUE INDEX IF NOT EXISTS uq_sidra_obs_sha256_registro
ON integracao.ibge_sidra_observacao(tabela_sidra_id,sha256_registro)
WHERE sha256_registro IS NOT NULL;

ALTER TABLE dw.fato_observacao
  ADD COLUMN IF NOT EXISTS versao_produto_dado_id bigint REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),
