CREATE TABLE IF NOT EXISTS catalogo.mapeamento_indicador_origem (
  mapeamento_indicador_origem_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(180) NOT NULL UNIQUE,
  indicador_id bigint NOT NULL
    REFERENCES catalogo.indicador(indicador_id),
  indicador_versao_id bigint NOT NULL
    REFERENCES catalogo.indicador_versao(indicador_versao_id),
  indicador_fonte_id bigint NOT NULL
    REFERENCES catalogo.indicador_fonte(indicador_fonte_id),
  recurso_id bigint NOT NULL
    REFERENCES catalogo.recurso_fonte(recurso_id),

  tabela_origem varchar(120),
  variavel_origem varchar(120),
  unidade_origem varchar(160),

  unidade_id smallint NOT NULL
    REFERENCES referencia.unidade_medida(unidade_id),
  tipo_medida_id bigint NOT NULL
    REFERENCES referencia.tipo_medida(tipo_medida_id),
  natureza_valor_id bigint NOT NULL
    REFERENCES referencia.natureza_valor(natureza_valor_id),
  status_dado_id smallint NOT NULL
    REFERENCES referencia.status_dado(status_dado_id),

  tipo_periodo_destino varchar(30) NOT NULL,
  tipo_territorio_destino varchar(50) NOT NULL,
  regra_filtro jsonb NOT NULL DEFAULT '{}'::jsonb,
  classificacoes_chave text[] NOT NULL DEFAULT ARRAY[]::text[],

  permite_promocao boolean NOT NULL DEFAULT true,
  exige_qualidade_aprovada boolean NOT NULL DEFAULT true,
  exige_territorio_resolvido boolean NOT NULL DEFAULT true,
  exige_periodo_resolvido boolean NOT NULL DEFAULT true,

  versao_mapeamento varchar(80) NOT NULL DEFAULT '1.0',
  valido_desde date NOT NULL DEFAULT current_date,
  valido_ate date,
  ativo boolean NOT NULL DEFAULT true,
  observacoes text,

  UNIQUE(indicador_versao_id,recurso_id,tabela_origem,variavel_origem,versao_mapeamento)
);

COMMENT ON TABLE catalogo.mapeamento_indicador_origem IS
'Contrato explícito que autoriza uma variável de origem a ser promovida para um indicador governado do ITMT.';

CREATE TABLE IF NOT EXISTS controle.execucao_promocao_indicador (
  execucao_promocao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  mapeamento_indicador_origem_id bigint NOT NULL
    REFERENCES catalogo.mapeamento_indicador_origem(mapeamento_indicador_origem_id),
