    REFERENCES ingestao.execucao_pipeline(execucao_pipeline_id),
  versao_produto_dado_id bigint
    REFERENCES catalogo.versao_produto_dado(versao_produto_dado_id),

  iniciada_em timestamptz NOT NULL DEFAULT now(),
  finalizada_em timestamptz,
  status varchar(30) NOT NULL DEFAULT 'iniciada'
    CHECK(status IN ('iniciada','sucesso','parcial','bloqueada','falha','cancelada')),

  candidatos bigint NOT NULL DEFAULT 0,
  promovidos bigint NOT NULL DEFAULT 0,
  sem_alteracao bigint NOT NULL DEFAULT 0,
  revisados bigint NOT NULL DEFAULT 0,
  bloqueados bigint NOT NULL DEFAULT 0,
  ignorados bigint NOT NULL DEFAULT 0,

  metricas jsonb NOT NULL DEFAULT '{}'::jsonb,
  mensagem text
);

CREATE TABLE IF NOT EXISTS controle.decisao_promocao_observacao (
  decisao_promocao_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  execucao_promocao_id uuid NOT NULL
    REFERENCES controle.execucao_promocao_indicador(execucao_promocao_id) ON DELETE CASCADE,
  mapeamento_indicador_origem_id bigint NOT NULL
    REFERENCES catalogo.mapeamento_indicador_origem(mapeamento_indicador_origem_id),

  origem_schema varchar(120) NOT NULL,
  origem_tabela varchar(180) NOT NULL,
  origem_chave text NOT NULL,
  objeto_origem_id uuid
    REFERENCES controle.objeto_dado(objeto_dado_id),

  chave_logica char(64),
  chave_versao char(64),

  decisao varchar(30) NOT NULL
    CHECK(decisao IN (
      'PROMOVER','REVISAO','SEM_ALTERACAO','BLOQUEAR',
      'IGNORAR_SEM_VALOR','IGNORAR_FORA_ESCOPO'
    )),
  motivo_codigo varchar(120),
  motivo text,

  observacao_id bigint
    REFERENCES dw.fato_observacao(observacao_id),
  observacao_anterior_id bigint
    REFERENCES dw.fato_observacao(observacao_id),

  criada_em timestamptz NOT NULL DEFAULT now(),
  UNIQUE(execucao_promocao_id,origem_schema,origem_tabela,origem_chave)
);

