INSERT INTO catalogo.conjunto_dado
(fonte_id,codigo_origem,nome,descricao,dominio,granularidade,periodicidade,
 url_catalogo,possui_dados_pessoais,nivel_acesso,ativo)
SELECT f.fonte_id,
       'SIDRA_4709_CENSO_2022',
       'SIDRA 4709 — População residente e crescimento — Censo 2022',
       'Tabela SIDRA 4709 usada no piloto governado de população residente.',
       'Demografia',
       'Município',
       'Censo 2022',
       'https://sidra.ibge.gov.br/tabela/4709',
       false,'publico',true
FROM catalogo.fonte_dado f
WHERE f.codigo='IBGE_SIDRA'
ON CONFLICT (fonte_id,codigo_origem)
DO UPDATE SET nome=EXCLUDED.nome,descricao=EXCLUDED.descricao,
              granularidade=EXCLUDED.granularidade,periodicidade=EXCLUDED.periodicidade,
              url_catalogo=EXCLUDED.url_catalogo,ativo=true;

