INSERT INTO catalogo.mapeamento_indicador_origem
(codigo,indicador_id,indicador_versao_id,indicador_fonte_id,recurso_id,
 tabela_origem,variavel_origem,unidade_origem,unidade_id,tipo_medida_id,
 natureza_valor_id,status_dado_id,tipo_periodo_destino,tipo_territorio_destino,
 regra_filtro,classificacoes_chave,permite_promocao,exige_qualidade_aprovada,
