-- View: somente versões atuais e publicáveis.
CREATE OR REPLACE VIEW semantico.v_observacao_indicador_atual AS
SELECT
  fo.observacao_id,
  di.codigo AS indicador_codigo,
  di.nome AS indicador_nome,
  dt.territorio_id,
  dt.codigo_oficial AS territorio_codigo,
  dt.nome AS territorio_nome,
  dt.uf_sigla,
  dp.periodo_id,
  dp.tipo AS periodo_tipo,
  dp.codigo AS periodo_codigo,
  dp.descricao AS periodo_descricao,
  du.codigo AS unidade_codigo,
  du.nome AS unidade_nome,
  fo.valor_numero,
  fo.valor_texto,
  fo.qualidade_geral,
  fo.provisorio,
  fo.suprimido,
  fo.revisao,
  fo.revisao_numero,
  fo.validade_sistema_inicio,
  fo.publicado_em,
  df.codigo AS fonte_codigo,
  df.nome AS fonte_nome,
  fo.produto_dado_versao_id,
  fo.objeto_dado_id,
  fo.chave_logica,
  fo.chave_observacao
FROM dw.fato_observacao fo
JOIN dw.dim_indicador di ON di.indicador_sk=fo.indicador_sk
LEFT JOIN dw.dim_territorio dt ON dt.territorio_sk=fo.territorio_principal_sk
LEFT JOIN dw.dim_periodo dp ON dp.periodo_sk=fo.periodo_sk
LEFT JOIN dw.dim_unidade_medida du ON du.unidade_sk=fo.unidade_sk
JOIN dw.dim_fonte df ON df.fonte_sk=fo.fonte_sk
WHERE fo.versao_atual=true
  AND fo.validade_sistema_fim IS NULL
  AND fo.suprimido=false;

CREATE OR REPLACE FUNCTION semantico.consultar_indicador(
  p_indicador_codigo varchar,
  p_periodo_codigo varchar DEFAULT NULL,
  p_uf_sigla varchar DEFAULT NULL,
  p_territorio_codigo varchar DEFAULT NULL
)
RETURNS TABLE(
  observacao_id bigint,
  indicador_codigo varchar,
  territorio_codigo varchar,
  territorio_nome varchar,
  uf_sigla char(2),
  periodo_codigo varchar,
  unidade_codigo varchar,
  valor_numero numeric,
  fonte_codigo varchar,
  revisao_numero integer,
  qualidade_geral numeric
)
LANGUAGE sql
STABLE
AS $$
  SELECT
    v.observacao_id,
    v.indicador_codigo,
    v.territorio_codigo,
    v.territorio_nome,
    v.uf_sigla,
    v.periodo_codigo,
    v.unidade_codigo,
    v.valor_numero,
    v.fonte_codigo,
    v.revisao_numero,
    v.qualidade_geral
  FROM semantico.v_observacao_indicador_atual v
  WHERE v.indicador_codigo=p_indicador_codigo
    AND (p_periodo_codigo IS NULL OR v.periodo_codigo=p_periodo_codigo)
    AND (p_uf_sigla IS NULL OR v.uf_sigla=p_uf_sigla)
    AND (p_territorio_codigo IS NULL OR v.territorio_codigo=p_territorio_codigo)
  ORDER BY v.territorio_nome;
$$;

