-- Documentação normativa operacional para símbolos SIDRA.
CREATE TABLE IF NOT EXISTS catalogo.regra_valor_especial_origem (
  regra_valor_especial_origem_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  fonte_id bigint NOT NULL REFERENCES catalogo.fonte_dado(fonte_id),
  codigo varchar(120) NOT NULL,
  simbolo varchar(20) NOT NULL,
  significado varchar(200) NOT NULL,
  status_valor_destino varchar(60) NOT NULL,
  valor_numerico_destino numeric,
  promovivel boolean NOT NULL DEFAULT false,
  observacoes text,
  valido_desde date NOT NULL DEFAULT current_date,
  valido_ate date,
  ativo boolean NOT NULL DEFAULT true,
  UNIQUE(fonte_id,codigo,simbolo,valido_desde)
);

INSERT INTO catalogo.regra_valor_especial_origem
(fonte_id,codigo,simbolo,significado,status_valor_destino,
 valor_numerico_destino,promovivel,observacoes,valido_desde)
SELECT f.fonte_id,x.codigo,x.simbolo,x.significado,x.status_valor,
       x.valor_numero,x.promovivel,x.observacoes,current_date
FROM catalogo.fonte_dado f
CROSS JOIN (
  VALUES
  ('SIDRA_ZERO_ABSOLUTO','-','Zero absoluto','valor_zero_absoluto',0::numeric,true,
   'Zero absoluto; não tratar como ausência.'),
  ('SIDRA_ZERO_ARREDONDADO','0','Zero resultante de cálculo/arredondamento','valor',0::numeric,true,
   'Zero publicado explicitamente como 0.'),
  ('SIDRA_SUPRIMIDO','X','Valor inibido','suprimido',NULL::numeric,false,
   'Não promover como valor numérico.'),
  ('SIDRA_NAO_APLICAVEL','..','Valor não se aplica','nao_aplicavel',NULL::numeric,false,
   'Não promover como zero.'),
  ('SIDRA_NAO_DISPONIVEL','...','Valor não disponível','nao_disponivel',NULL::numeric,false,
   'Não confundir com zero nem com inexistência do território.')
) AS x(codigo,simbolo,significado,status_valor,valor_numero,promovivel,observacoes)
WHERE f.codigo='IBGE_SIDRA'
ON CONFLICT (fonte_id,codigo,simbolo,valido_desde)
DO UPDATE SET significado=EXCLUDED.significado,
              status_valor_destino=EXCLUDED.status_valor_destino,
              valor_numerico_destino=EXCLUDED.valor_numerico_destino,
              promovivel=EXCLUDED.promovivel,
              observacoes=EXCLUDED.observacoes,
              ativo=true;

COMMENT ON TABLE catalogo.regra_valor_especial_origem IS
'Regras versionáveis para símbolos especiais da fonte. Impede que o parser trate convenções semânticas da origem como valores ausentes ou zero de forma incorreta.';

-- Perfil de compatibilidade física.
CREATE TABLE IF NOT EXISTS controle.preflight_ambiente (
  preflight_ambiente_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  executado_em timestamptz NOT NULL DEFAULT now(),
  postgres_version_num integer NOT NULL,
  postgres_version text NOT NULL,
  postgis_version text,
  pgcrypto_disponivel boolean NOT NULL,
  timezone text,
  resultado varchar(30) NOT NULL
    CHECK(resultado IN ('APROVADO','APROVADO_COM_ALERTA','REPROVADO')),
  verificacoes jsonb NOT NULL DEFAULT '{}'::jsonb,
  observacoes text
);

CREATE TABLE IF NOT EXISTS controle.preflight_regra (
  preflight_regra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  codigo varchar(160) NOT NULL UNIQUE,
  nome varchar(300) NOT NULL,
  categoria varchar(80) NOT NULL,
  bloqueante boolean NOT NULL DEFAULT true,
  descricao text,
  ativo boolean NOT NULL DEFAULT true
);

INSERT INTO controle.preflight_regra(codigo,nome,categoria,bloqueante,descricao)
VALUES
('PG_VERSION','PostgreSQL compatível','banco',true,'Versão mínima PostgreSQL 16; PostgreSQL 17 suportado.'),
('POSTGIS','PostGIS disponível','geoespacial',true,'Extensão PostGIS precisa estar disponível.'),
('PGCRYPTO','pgcrypto disponível','banco',true,'Necessário para digest/hash em SQL.'),
('CORE_R232','Core R2.3.2 aplicado','schema',true,'Tabelas e funções do Core R2.3.2 precisam existir.'),
('SIDRA_CONTRACT','Contrato SIDRA ativo','governanca',true,'Contrato normalizado SIDRA precisa existir.'),
('SIDRA_MAPPING','Mapeamento população ativo','governanca',true,'Mapeamento 4709/V93 precisa existir e estar ativo.'),
('QUALITY_PROFILE','Perfil de qualidade ativo','qualidade',true,'Quality Profile SIDRA precisa existir.'),
('SEMANTIC_FUNCTION','Função semântica disponível','semantico',true,'semantico.consultar_indicador precisa existir.')
ON CONFLICT (codigo)
DO UPDATE SET nome=EXCLUDED.nome,categoria=EXCLUDED.categoria,
              bloqueante=EXCLUDED.bloqueante,descricao=EXCLUDED.descricao,ativo=true;

CREATE TABLE IF NOT EXISTS controle.preflight_resultado_regra (
  preflight_resultado_regra_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  preflight_ambiente_id uuid NOT NULL
    REFERENCES controle.preflight_ambiente(preflight_ambiente_id) ON DELETE CASCADE,
  preflight_regra_id bigint NOT NULL
    REFERENCES controle.preflight_regra(preflight_regra_id),
  aprovado boolean NOT NULL,
  valor_observado text,
  mensagem text,
  UNIQUE(preflight_ambiente_id,preflight_regra_id)
);

-- Função de preflight físico.
CREATE OR REPLACE FUNCTION controle.executar_preflight_r233()
RETURNS uuid
LANGUAGE plpgsql
AS $$
DECLARE
  v_id uuid := gen_random_uuid();
  v_pg_num integer := current_setting('server_version_num')::integer;
  v_pg text := version();
  v_postgis text;
  v_pgcrypto boolean;
  v_result varchar(30) := 'APROVADO';
  v_ok boolean;
  v_rule bigint;
BEGIN
  SELECT EXISTS(SELECT 1 FROM pg_extension WHERE extname='pgcrypto')
    INTO v_pgcrypto;

  BEGIN
    SELECT postgis_full_version() INTO v_postgis;
  EXCEPTION WHEN undefined_function THEN
    v_postgis := NULL;
  END;

  IF v_pg_num < 160000 OR v_postgis IS NULL OR NOT v_pgcrypto THEN
    v_result := 'REPROVADO';
  END IF;

  INSERT INTO controle.preflight_ambiente(
    preflight_ambiente_id,postgres_version_num,postgres_version,
    postgis_version,pgcrypto_disponivel,timezone,resultado,verificacoes
  )
  VALUES (
    v_id,v_pg_num,v_pg,v_postgis,v_pgcrypto,current_setting('TimeZone'),v_result,
    jsonb_build_object(
      'min_postgres',160000,
      'core_target','PostgreSQL 16+; homologação preferencial PG17 + PostGIS 3+'
    )
  );

  -- PG_VERSION
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='PG_VERSION';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_pg_num>=160000,v_pg_num::text,
          CASE WHEN v_pg_num>=160000 THEN 'OK' ELSE 'PostgreSQL abaixo da versão mínima.' END);

  -- POSTGIS
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='POSTGIS';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_postgis IS NOT NULL,COALESCE(v_postgis,'ausente'),
          CASE WHEN v_postgis IS NOT NULL THEN 'OK' ELSE 'PostGIS ausente.' END);

  -- PGCRYPTO
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='PGCRYPTO';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_pgcrypto,v_pgcrypto::text,
          CASE WHEN v_pgcrypto THEN 'OK' ELSE 'pgcrypto ausente.' END);

  -- CORE_R232
  SELECT to_regclass('catalogo.mapeamento_indicador_origem') IS NOT NULL INTO v_ok;
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='CORE_R232';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_ok,COALESCE(to_regclass('catalogo.mapeamento_indicador_origem')::text,'ausente'),
          CASE WHEN v_ok THEN 'OK' ELSE 'Core R2.3.2 não detectado.' END);

  -- SIDRA_CONTRACT
  SELECT EXISTS(
    SELECT 1 FROM catalogo.contrato_dado_core
    WHERE codigo='CONTRATO_IBGE_SIDRA_NORMALIZADO' AND status='ativo'
  ) INTO v_ok;
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='SIDRA_CONTRACT';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_ok,v_ok::text,
          CASE WHEN v_ok THEN 'OK' ELSE 'Contrato SIDRA não está ativo.' END);

  -- SIDRA_MAPPING
  SELECT EXISTS(
    SELECT 1 FROM catalogo.mapeamento_indicador_origem
    WHERE codigo='MAP_POP_RES_CENSO2022_SIDRA4709_V93'
      AND ativo=true AND permite_promocao=true
  ) INTO v_ok;
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='SIDRA_MAPPING';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_ok,v_ok::text,
          CASE WHEN v_ok THEN 'OK' ELSE 'Mapeamento SIDRA 4709/V93 indisponível.' END);

  -- QUALITY_PROFILE
  SELECT EXISTS(
    SELECT 1
    FROM catalogo.perfil_qualidade_produto pq
    JOIN catalogo.produto_dado pd ON pd.produto_dado_id=pq.produto_dado_id
    WHERE pd.codigo='IBGE_SIDRA_OBSERVACOES_NORMALIZADAS'
      AND pq.codigo='SIDRA_INTEGRACAO'
      AND pq.ativo=true
  ) INTO v_ok;
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='QUALITY_PROFILE';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_ok,v_ok::text,
          CASE WHEN v_ok THEN 'OK' ELSE 'Perfil de qualidade SIDRA ausente.' END);

  -- SEMANTIC_FUNCTION
  SELECT to_regprocedure('semantico.consultar_indicador(character varying,character varying,character varying,character varying)') IS NOT NULL INTO v_ok;
  SELECT preflight_regra_id INTO v_rule FROM controle.preflight_regra WHERE codigo='SEMANTIC_FUNCTION';
  INSERT INTO controle.preflight_resultado_regra
  VALUES (DEFAULT,v_id,v_rule,v_ok,v_ok::text,
          CASE WHEN v_ok THEN 'OK' ELSE 'Função semântica não encontrada.' END);

  IF EXISTS(
    SELECT 1
    FROM controle.preflight_resultado_regra rr
    JOIN controle.preflight_regra r ON r.preflight_regra_id=rr.preflight_regra_id
    WHERE rr.preflight_ambiente_id=v_id
      AND r.bloqueante=true
      AND rr.aprovado=false
  ) THEN
    UPDATE controle.preflight_ambiente
       SET resultado='REPROVADO'
     WHERE preflight_ambiente_id=v_id;
  END IF;

  RETURN v_id;
END;
$$;

CREATE OR REPLACE VIEW controle.v_preflight_ultimo AS
SELECT
  p.preflight_ambiente_id,
  p.executado_em,
  p.postgres_version_num,
  p.postgres_version,
  p.postgis_version,
  p.pgcrypto_disponivel,
  p.timezone,
  p.resultado,
  count(*) FILTER (WHERE rr.aprovado) AS regras_aprovadas,
  count(*) FILTER (WHERE NOT rr.aprovado) AS regras_reprovadas
FROM controle.preflight_ambiente p
LEFT JOIN controle.preflight_resultado_regra rr
  ON rr.preflight_ambiente_id=p.preflight_ambiente_id
WHERE p.preflight_ambiente_id=(
  SELECT preflight_ambiente_id
  FROM controle.preflight_ambiente
  ORDER BY executado_em DESC
  LIMIT 1
)
GROUP BY p.preflight_ambiente_id,p.executado_em,p.postgres_version_num,
         p.postgres_version,p.postgis_version,p.pgcrypto_disponivel,
         p.timezone,p.resultado;


-- ------------------------------------------------------------
-- Privilegios: fechado por padrao (diretriz do usuario).
-- ------------------------------------------------------------
DO $priv$
DECLARE s text;
BEGIN
  FOREACH s IN ARRAY ARRAY['bruto','campo','catalogo','controle','documental','dw','geoespacial','ingestao','integracao','levantamento','midia','municipal','nucleo','orquestracao','parceria','pesquisa','producao','referencia','seguranca','semantico'] LOOP
    EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA %I FROM itmt_app', s);
    EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA %I FROM itmt_app', s);
    EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA %I FROM itmt_app', s);
    EXECUTE format('REVOKE ALL ON SCHEMA %I FROM itmt_app', s);
    EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA %I REVOKE ALL ON TABLES FROM itmt_app', s);
  END LOOP;
END
$priv$;

-- ------------------------------------------------------------
-- Verificacao. A classe "seed silencioso" ja reincidiu cinco vezes neste
-- programa; aqui a contagem falha alto.
-- ------------------------------------------------------------
DO $conf$
DECLARE n_tabelas int; n_geom int; n_schemas int; visivel int;
BEGIN
  SELECT count(*) INTO n_tabelas FROM pg_tables
   WHERE schemaname IN ('bruto','campo','catalogo','controle','documental','dw',
                        'geoespacial','ingestao','integracao','levantamento','midia',
                        'municipal','nucleo','orquestracao','parceria','pesquisa',
                        'producao','referencia','seguranca','semantico');

  SELECT count(*) INTO n_geom FROM information_schema.columns
   WHERE udt_name = 'geometry' AND table_schema NOT IN ('topology','tiger','tiger_data');

  SELECT count(DISTINCT schemaname) INTO n_schemas FROM pg_tables
   WHERE schemaname IN ('bruto','campo','catalogo','controle','documental','dw',
                        'geoespacial','ingestao','integracao','levantamento','midia',
                        'municipal','nucleo','orquestracao','parceria','pesquisa',
                        'producao','referencia','seguranca','semantico');

  SELECT count(*) INTO visivel FROM information_schema.role_table_grants
   WHERE grantee = 'itmt_app'
     AND table_schema IN ('bruto','campo','catalogo','controle','documental','dw',
                        'geoespacial','ingestao','integracao','levantamento','midia',
                        'municipal','nucleo','orquestracao','parceria','pesquisa',
                        'producao','referencia','seguranca','semantico');

  IF n_tabelas <> 1299 THEN
    RAISE EXCEPTION 'db/68: criadas % tabelas nos schemas analiticos, esperado 1299.', n_tabelas;
  END IF;
  IF n_geom <> 226 THEN
    RAISE EXCEPTION 'db/68: % colunas de geometria, esperado 226.', n_geom;
  END IF;
  IF n_schemas <> 20 THEN
    RAISE EXCEPTION 'db/68: % schemas analiticos, esperado 20.', n_schemas;
  END IF;
  IF visivel <> 0 THEN
    RAISE EXCEPTION 'db/68: itmt_app enxerga % tabela(s) dos schemas analiticos; a diretriz e fechado por padrao.', visivel;
  END IF;

  RAISE NOTICE 'db/68: % tabelas em % schemas, % colunas de geometria, 0 visiveis a itmt_app.',
    n_tabelas, n_schemas, n_geom;
END
$conf$;

COMMIT;
